/* Generated by tools/editorial/compile_main_story_k.cjs from tools/editorial/main_story_k/*.md. Do not edit by hand. */
(function(root){root.CRPGMainStoryK={"version":1,"chains":[{"id":"ISK_L01_K","entry":"ISK_L01_K_001","items":[{"k":"keep","id":"ISK_L01_K_001","text":"성문 밖의 길은 멀리서 볼 때보다 좁았다. 수레 한 대가 지날 때마다 사람은 풀밭 쪽으로 비켜섰다. 어깨끈을 한 번 당겼다가, 진이 보고 있다는 걸 알고 아무렇지 않은 척 손을 내렸다."},{"k":"line","id":"PRO_L01K_depart_001","speaker":"진","text":"잠깐만요. 가방끈이 뒤집혔군요. 그대로 걸으면 어깨가 쓸릴 겁니다. 내려 보시겠어요?","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_002","text":"잠깐. 가방끈이 뒤집혔어. 그대로 걸으면 어깨가 쓸릴 거야. 짐 좀 내려 봐."}},{"k":"line","id":"PRO_L01K_depart_003","speaker":"나","text":"출발도 전에 들켰네요. 부탁드릴게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_004","speaker":"진","text":"이쪽을 잡아 주세요. 안에 든 천을 받치면 낫겠어요. 먼 길을 갈 때는 이런 불편부터 고쳐야 하니까요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_005","text":"이쪽을 잡아 줘. 안에 든 천을 받치면 낫겠네. 먼 길 갈 건데, 이런 건 참지 말고."}},{"k":"line","id":"PRO_L01K_depart_006","speaker":"","text":"진은 천을 접어 끈 아래에 받친 뒤, 다시 멘 가방이 기울지 않는지 살폈다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_007","speaker":"나","text":"훨씬 낫네요. 고맙습니다, 진 단장.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_008","speaker":"진","text":"다행이네요. 가다가 다시 불편해지면 바로 고치세요. 리월에 도착하면 편지도 부탁드려요. 무사히 도착했는지 궁금할 테니까요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_009","text":"다행이네. 가다가 다시 불편하면 바로 고쳐. 리월에 도착하면 편지 보내 줘. 잘 도착했는지 궁금할 테니까."}},{"k":"line","id":"PRO_L01K_depart_010","speaker":"나","text":"맛있는 것만 먹었다고 써도 되죠?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_011","speaker":"진","text":"그런 소식이라면 기쁘게 읽겠습니다. 다만 음식 이야기 전에 잘 도착했다는 말부터 써 주세요. 기다리는 사람이 안심할 수 있게요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_012","text":"물론이지. 음식 이야기 전에 잘 도착했다는 말부터 써 줘. 기다리는 사람부터 안심시켜야지."}},{"k":"line","id":"PRO_L01K_depart_013","speaker":"","text":"발길을 떼려다, 죽어 있던 드발린의 모습이 떠올라 멈칫했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_014","speaker":"나","text":"진 단장, 드발린이 죽어 있었던 일도 기록에 남겨 주세요. 제가 잘못 본 게 아니니까요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_015","speaker":"진","text":"물론입니다. 저도 그 자리에 있었어요. 죽어 있었던 일과 다시 살아난 일, 둘 다 남기겠습니다. 이유를 모르겠다고 목격한 사실까지 지울 수는 없죠.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_016","text":"물론이야. 나도 그 자리에 있었잖아. 죽어 있었던 일도, 다시 살아난 일도 남길게. 이유를 모른다고 본 것까지 지우지는 않아."}},{"k":"line","id":"PRO_L01K_depart_017","speaker":"나","text":"……그 말을 듣고 싶었어요. 그럼 다녀오겠습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_018","speaker":"진","text":"필요하면 제게 연락하세요. 몬드에서 함께 겪은 일은 제가 증언하겠습니다. 오늘은 도착해서 쉴 곳부터 찾으시고요. 편지 기다릴게요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_019","text":"필요하면 내게 연락해. 몬드에서 함께 겪은 일은 내가 증언할게. 오늘은 도착해서 쉴 곳부터 찾고. 편지 기다릴게."}},{"k":"line","id":"PRO_L01K_depart_020","speaker":"","text":"진은 손을 들어 배웅한 뒤, 기다리던 기사의 보고를 받으며 성안으로 돌아갔다.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_L01_K_016","text":"해가 기울 무렵 망서 객잔의 기둥이 보였다. 반가움은 짧았다. 객잔 아래 짐을 올리는 승강기가 한쪽으로 기울어 있었고, 끊어질 듯한 줄 끝에 짐꾼 하나가 매달려 있었다. 두 사람이 그 아래로 달려왔다."},{"k":"line","id":"PRO_L01K_wangshu_001","speaker":"","text":"상자를 치운 자리로 줄이 또 한 뼘 미끄러졌다. 위에서 짐꾼이 짧게 숨을 들이켰다. 지금 내가 할 수 있는 일은 하나였다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_wangshu_002","options":[{"label":"받침목 여기 있어요! 제가 끼울 테니 자리를 짚어 줘요!","keep":"REV02_K_LIFT_C1","items":[{"k":"line","id":"PRO_L01K_wangshu_003","speaker":"중운","text":"거기! 바퀴 뒤쪽! 더 깊이!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_004","speaker":"","text":"받침목이 들어가자 승강기가 덜컥 멈췄다. 흔들림이 가라앉은 뒤에야 행추가 줄을 당겨 짐꾼을 끌어올렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_005","speaker":"행추","text":"자네, 손이 빠르군. 받침 자리를 한 번에 찍었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_006","speaker":"나","text":"운이 좋았어. 두 번째였으면 손이 떨려서 못 했을 거야.","map":"MAP_LIYUE_PLAINS"}]},{"label":"줄은 못 버텨요! 이 천 펴요! 거기 두 분, 구경 말고 모서리 좀 잡아 줘요!","keep":"REV02_K_LIFT_C2","items":[{"k":"line","id":"PRO_L01K_wangshu_007","speaker":"","text":"구경꾼 둘이 얼떨결에 천을 잡았다. 줄이 끊어진 건 그 직후였다. 짐꾼은 천 위로 떨어져 한 바퀴 굴렀고, 나는 그 반동에 엉덩방아를 찧었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_008","speaker":"중운","text":"다친 사람 없지? 없으면 다들 한 번씩 숨 쉬어!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_009","speaker":"행추","text":"줄이 못 버틴다는 걸 먼저 본 사람은 자네 하나였네. 천을 고른 것도 좋았어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_010","speaker":"나","text":"좋았다는 말은 내 허리한테 해 줘. 바닥이 생각보다 딱딱했어.","map":"MAP_LIYUE_PLAINS"}]},{"label":"손이 모자라잖아요! 저도 줄 잡을게요! 저까지 딸려가면 바로 잡아 줘요!","keep":"REV02_K_LIFT_C3","items":[{"k":"line","id":"PRO_L01K_wangshu_011","speaker":"","text":"줄을 잡은 순간 발이 바닥에서 떴다. 중운이 내 허리띠를 잡아 끌어내렸고, 그 사이 행추가 위에서 짐꾼을 받쳐 올렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_012","speaker":"중운","text":"딸려가면 잡아 달라더니 진짜 딸려가는 사람은 처음 봤다!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_013","speaker":"행추","text":"그래도 줄이 멈췄네. 자네 몸무게가 받침목 몫을 했어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_014","speaker":"나","text":"칭찬인지 아닌지 모르겠지만 받을게. 다음엔 받침목을 들게.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_wangshu_015","speaker":"","text":"짐꾼은 땅에 내려서자마자 쭈그려 앉아 허리를 두드렸다. 한참 뒤에야 우리 쪽을 올려다봤다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_016","speaker":"짐꾼","text":"사람 셋이 달라붙어서 간신히 내린 게 이 몸뚱이 하나라니. 짐은 떨어졌소?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_017","speaker":"중운","text":"짐보다 아저씨가 먼저죠!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_018","speaker":"짐꾼","text":"짐이 떨어지면 내 품삯이 떨어지는 거라오. 어쨌든… 고맙소. 셋 다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_019","speaker":"","text":"그가 '셋'이라고 셀 때 내 쪽도 한 번 보았다. 묘하게 뿌듯했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_020","speaker":"행추","text":"우리는 객잔에 짐을 올려 두고 바로 떠나야 하네. 자네는?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_021","speaker":"나","text":"오늘은 여기서 자고 내일 리월항으로 가. 가서 할 일이 있어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_022","speaker":"행추","text":"그럼 항구 근처에서 다시 보겠군. 요즘 그쪽이 조금 시끄러워서 말이야. 중운, 가자.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_023","speaker":"중운","text":"아까 그 책, 먼저 주워 두라고 했잖아!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_024","speaker":"","text":"두 사람이 멀어진 뒤에도 승강기 줄은 바람에 조금씩 흔들렸다. 그때 등 뒤에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_025","speaker":"소","text":"움직이지 마.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_026","speaker":"","text":"돌아보자 지붕 위에 창을 든 사람이 서 있었다. 가면은 쓰지 않았지만, 그 눈빛만으로 누구인지 알 수 있었다. 소. 내가 아는 이야기 속에서는 이 객잔을 지키는 선인이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_027","speaker":"소","text":"네 주변에서 낯선 냄새가 난다. 죽음과 생명의 냄새가 함께. 사람 하나에게서 나기엔 이상한 조합이지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_028","speaker":"나","text":"……제가 뭘 한 건 아니에요. 적어도 제가 아는 한은요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_029","speaker":"소","text":"그렇게 보인다. 네가 남을 해쳤다는 징후는 없어. 하지만 마신을 미워하는 기척이 네 곁을 스쳤다. 그게 네 것인지, 네가 지나온 곳의 것인지는 모른다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_030","speaker":"나","text":"그럼 저는 어떡해야 합니까? 사람을 피해야 하나요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_031","speaker":"소","text":"이상을 느끼면 모르는 척하지 마. 기척을 시험하겠다며 사람들 속으로 들어가지도 말고. 그 정도다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_032","speaker":"","text":"다음 질문을 꺼내기 전에 지붕 위는 비어 있었다. 바람 소리만 남았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_001","speaker":"","text":"객잔 종업원이 방 열쇠와 함께 따뜻한 물을 내줬다. 아래층 소란을 전부 본 모양이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_002","speaker":"객잔 종업원","text":"승강기 일은 들었어요. 오늘은 그냥 쉬세요. 여행길에 만난 사람 말이 전부 머리에 남으면 잠들 틈이 없어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_003","speaker":"나","text":"그 말, 제가 들은 걸 다 아시는 것처럼 들리네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_004","speaker":"객잔 종업원","text":"여기 지붕 위에 누가 사는지는 다들 알죠. 그분 말은 무서워도 틀린 적은 없어요. 그러니 더 쉬어야 하고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_005","speaker":"","text":"방에 누워도 죽음과 생명의 냄새라는 말이 천장에 붙어 있었다. 드발린의 식은 몸, 그리고 다시 날아오르던 모습이 번갈아 떠올랐다. 잠은 늦게 왔다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_064","text":"아침 길에 어제의 짐꾼을 다시 만났다. 그는 어제 떨어질 뻔한 포대를 등에 얹고 있었다. 돕겠다고 손을 뻗자 먼저 내 신발부터 내려다봤다."},{"k":"line","id":"PRO_L01K_wangshu_night_006","speaker":"짐꾼","text":"그 신발로 내 짐까지 들면 리월에는 발바닥만 도착하겠네. 옆에서 길이나 봐 주시오. 수레 오면 소리 지르고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_007","speaker":"나","text":"그 정도는 할 수 있어요. 어디까지 가세요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_008","speaker":"짐꾼","text":"리월항. 이 포대는 항구 창고에 들어가야 품삯이 나오거든. 자네도 그쪽이면 같이 가지. 혼자 걷는 길은 길어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_009","speaker":"","text":"그렇게 동행이 생겼다. 그는 자기 이름을 말하지 않았고, 나도 묻지 않았다. 아직은 짐꾼과 손님으로 충분했다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_069","text":"귀리 평원으로 접어들자 오래된 돌무더기가 길 양쪽에 늘어났다. 폐허를 오래 보지 않으려 했다. 드발린이 떨어졌을 때 땅에서 올라온 울림이 이런 돌벽에서도 쉽게 떠올랐다. 그래도 길에는 살아 있는 사람이 더 많았다."},{"k":"line","id":"PRO_L01K_guili_001","speaker":"짐꾼","text":"자네, 어제 지붕 위 그분하고 말했지? 뭐라던가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_002","speaker":"나","text":"……들으셨어요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_003","speaker":"짐꾼","text":"듣진 못했소. 그분이 사람한테 직접 말하는 걸 본 게 처음이라 그렇지. 말하기 싫으면 말고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_004","speaker":"나","text":"제 주변에 이상한 게 있다고요. 뭔지는 자기도 모른다고 했어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_005","speaker":"짐꾼","text":"그러면 모르는 거지. 선인이 모른다는 걸 자네가 밤새 고민해서 알 수 있겠소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_006","speaker":"","text":"그 말이 의외로 위로가 되었다. 앞줄이 멈출 때마다 그는 포대를 내려놓고, 나는 앞을 보러 갔다. 짐은 그가, 길은 내가 살폈다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_007","speaker":"짐꾼","text":"이유를 들으면 뒤에도 좀 알려 주시오. 앞사람 말이란 게 뒤로 올수록 점점 커져서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_008","speaker":"나","text":"들은 말과 사람들이 짐작한 말은 나눠서 전할게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_009","speaker":"짐꾼","text":"그렇게 해 주면 좋겠소. 뒤에서는 그 둘이 구분이 안 되니.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_075","text":"리월항 입구는 수레와 사람으로 막혀 있었다. 차단선 옆에서 보라색 머리의 여자가 직접 포대를 옮기고 있었다. 각청. 그녀가 여기서 짐을 나르고 있을 줄은 몰랐다. 눈이 마주쳤다."},{"k":"line","id":"PRO_L01K_blockade_001","speaker":"각청","text":"구경할 힘은 남았나 보네. 그 줄 좀 잡아 줘. 이야기는 사람들이 그늘로 옮겨 간 다음에 듣겠어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_002","speaker":"","text":"그늘막 줄을 잡고 한 시간이 지났다. 사람들이 그늘로 들어간 뒤, 각청은 접수대 위에 두 장의 표를 나란히 놓았다. 같은 짐의 수량이 적혀 있었지만, 아래에 붙은 설명은 서로 달랐다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_003","speaker":"각청","text":"이건 물건을 넘겼다는 확인서. 이쪽은 같은 짐을 받지 못했다는 신고야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_004","speaker":"나","text":"...같은 짐인데요? 그럼 누가 거짓말을...","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_005","speaker":"각청","text":"아직 몰라. 기억이 끊긴 사람도 있거든. 누구 말을 믿을지 고르기 전에 짐부터 확인해야 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_006","speaker":"나","text":"그걸... 본인도 모르는 거예요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_007","speaker":"각청","text":"그래. 확인하려고 짐을 다시 풀었다가 다른 수레의 짐까지 섞인 일도 있어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_008","speaker":"","text":"각청은 두 장을 따로 묶고, 뒤쪽 수레가 접수대 앞으로 밀려오지 않도록 손을 들었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_009","speaker":"각청","text":"그 짐은 거기서 기다려 줘. 뒤에 도착한 사람들 것하고 섞이지 않게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_010","speaker":"","text":"기다리라는 말을 들은 수레는 짐꾼의 것이었다. 그는 포대를 내려놓고 어제처럼 허리를 두드렸다. 그 옆의 병사는 아까부터 표찰만 들여다보고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_011","speaker":"나","text":"...저 병사도 아까부터 표찰만 보고 있던데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_012","speaker":"각청","text":"그것만 보고 단정하진 마. 지쳤거나 표가 틀렸을 수도 있으니까. 내가 물어볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_013","speaker":"","text":"각청은 병사에게 표를 받아, 글씨가 보이도록 돌려 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_014","speaker":"각청","text":"어디까지 확인했어? 마지막으로 본 짐을 짚어 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_015","speaker":"천암군 병사","text":"그게... 잠시만요. 다시 보면 알 수 있을 것 같습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_016","speaker":"","text":"병사의 손가락이 같은 줄을 몇 번이나 오갔다. 각청은 대답을 재촉하지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_017","speaker":"각청","text":"확실히 기억나는 데까지만 말하면 돼. 모르는 건 비워 두고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_018","speaker":"천암군 병사","text":"죄송합니다. 한 번만 더 확인하면...","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_019","speaker":"각청","text":"사과부터 할 필요 없어. 교대하고 물 좀 마셔. 이 표는 내가 확인할게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_020","speaker":"천암군 병사","text":"그럼... 나중에 다시 말씀드려도 되겠습니까?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_021","speaker":"각청","text":"생각나면 와. 억지로 채워 넣지는 말고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_022","speaker":"","text":"병사가 자리를 뜨자 각청은 표를 접수대 한쪽에 따로 놓았다. 밀려드는 서류 밑에 들어가지 않도록 모서리를 밖으로 빼 두었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_023","speaker":"나","text":"...못 떠올리는 사람만 잘못한 것 같아지네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_024","speaker":"각청","text":"그래서 확인하는 거야. 짐이 없어졌다면 찾아야 하고, 빼돌린 사람이 있다면 그쪽을 찾아야지.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_105","text":"접수대 뒤 공고를 다시 보았다. 송신의례. 내가 아는 이야기에서 이 시기에 열리는 것은 청신의례였다. 글자 하나가 다른데, 그 하나가 어떤 뜻인지는 여기서 알 수 없었다. 그 사이 봉쇄선 밖에서 아는 목소리가 들렸다."},{"k":"line","id":"PRO_L01K_desk_001","speaker":"","text":"돌아오자 각청이 접수대 한쪽을 비워 주었다. 펼쳐 둔 종이 위에서 펜 끝이 멈췄다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_002","speaker":"각청","text":"더 알릴 일이 있어? 직접 본 일이든 전해 들은 말이든, 어디서 나온 얘기인지 알려 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_desk_003","options":[{"label":"...확실하지 않은 얘기도 해도 돼요?","id":"PRO_L01K_desk_004","items":[{"k":"line","id":"PRO_L01K_desk_005","speaker":"각청","text":"확실하지 않다고 말하면 돼. 확인할 수 있는지는 듣고 나서 판단할게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_006","speaker":"나","text":"...그럼, 좀 이상하게 들려도 끝까지 들어 주세요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_007","speaker":"각청","text":"듣고 있어. 천천히 말해.","map":"MAP_LIYUE_PLAINS"}]},{"label":"잠깐만요. 어디서부터 말해야 할지...","id":"PRO_L01K_desk_008","items":[{"k":"line","id":"PRO_L01K_desk_009","speaker":"각청","text":"급하게 맞춰 말하지 않아도 돼. 생각나는 것부터 하나씩.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_010","speaker":"","text":"각청은 펜을 내려놓고 뒤에 선 사람을 옆 접수대로 안내했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_011","speaker":"나","text":"...네. 잠깐만 생각 좀 할게요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_desk_012","speaker":"","text":"입을 열려다 어젯밤의 경고가 떠올랐다. 내 주위에 죽음의 냄새가 난다는 말... 옆에서는 짐꾼이 같은 포대의 끈을 다시 풀고 있었다. 교대한 병사가 또 그 포대를 세고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_001","options":[{"label":"...제 얘기부터 할게요. 어젯밤 소에게 경고를 들었어요.","keep":"ISK_L01_K_1_CHOOSE","items":[{"k":"line","id":"PRO_L01K_fork_002","speaker":"","text":"소의 이름을 듣자 각청이 고개를 들었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_003","speaker":"각청","text":"호법야차님을 만났다고? 어디서?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_004","speaker":"나","text":"망서 객잔이요. 제 주위에... 죽음과 생명의 냄새가 같이 난댔어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_005","speaker":"각청","text":"....죽음과 생명의 냄새가 함께 난다고?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_006","speaker":"","text":"각청은 줄 선 사람들을 돌아본 뒤, 접수대 옆으로 자리를 옮겼다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_007","speaker":"각청","text":"이쪽에서 이야기하자. 그분이 네 몸에서 난다고 하셨어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_008","speaker":"나","text":"그건... 모르겠어요. 마신을 미워하는 기척도 있다는데, 전 그런 생각 안 해요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_009","speaker":"각청","text":"알겠어. 그 말만으로 네가 누굴 해치려 했다고 볼 순 없어. 다만 그분의 경고를 그냥 넘길 수도 없고.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_010","options":[{"label":"저도... 저 병사처럼 기억을 잃게 될까요?","id":"PRO_L01K_fork_011","items":[{"k":"line","id":"PRO_L01K_fork_012","speaker":"각청","text":"아직 그렇게 볼 근거는 없어. 같은 일인지부터 확인해야 해. 오늘 온 길은 기억나?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_013","speaker":"나","text":"네. 길은 기억나요. 다만 어젯밤에... 잠을 거의 못 잤어요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"...말 안 하면 더 불안할 것 같았어요.","id":"PRO_L01K_fork_014","items":[{"k":"line","id":"PRO_L01K_fork_015","speaker":"각청","text":"잘 말해 줬어. 그 뒤에 네가 직접 느낀 건 있어? 기억이 빠졌거나 몸이 불편했다든가.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_016","speaker":"나","text":"길도 기억하고, 몸은 괜찮아요. 잠을 좀... 설쳤어요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_017","speaker":"각청","text":"잠을 설친 건 그렇게 적을게. 다른 증상으로 바꿔 적지는 않아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_018","speaker":"","text":"각청은 들은 경고와 지금 대답을 줄을 나눠 적었다. 종이를 이쪽으로 돌려 빠진 말이 없는지 짚어 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_019","speaker":"나","text":"...이상한 사람 취급할 줄 알았는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_020","speaker":"각청","text":"불안해서 찾아온 사람한테, 확인도 안 한 말로 겁을 더 줄 순 없잖아. 다른 일도 있었으면 계속 말해 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_021","speaker":"","text":"그때 차단선 쪽에서 쇠 부딪히는 소리가 났다. 교대한 병사가 수레를 통과시키려 차단봉을 올리고 있었다. 봉 아래에는 아직 짐꾼이 포대를 묶고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_022","options":[{"label":"잠깐만요! 아래에 아직 사람 있어요! 통과하라는 말 취소예요!","keep":"REV02_K1_REPEAT_C1","items":[{"k":"line","id":"PRO_L01K_fork_023","speaker":"","text":"내 목소리에 수레가 멈췄다. 병사는 봉을 올린 손을 내려다보더니, 왜 올렸는지 모르겠다는 얼굴로 굳었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_024","speaker":"각청","text":"봉 내려. 천천히. 그대로 두고 물러서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_025","speaker":"짐꾼","text":"……자네 목소리 큰 줄은 몰랐네. 덕분에 머리가 붙어 있소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_026","speaker":"나","text":"저도 몰랐어요. 목이 좀 아프네요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"방금 하신 것부터 같이 봐요. 수레가 지나가기 전에 봉을 올리셨어요. 기억 맞추라는 게 아니라, 지금 손부터 빼요.","keep":"REV02_K1_REPEAT_C2","items":[{"k":"line","id":"PRO_L01K_fork_027","speaker":"","text":"병사는 내 말을 듣고서야 자기 손을 보았다. 봉이 천천히 내려왔고, 수레는 그 앞에 섰다. 짐꾼은 그제야 머리 위에 무엇이 있었는지 알았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_028","speaker":"각청","text":"지금 네가 본 걸 그대로 말해 줘. 병사가 봉을 올린 게 먼저야, 수레가 움직인 게 먼저야?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_029","speaker":"나","text":"봉이 먼저였어요. 통과하라는 말은 없었고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_030","speaker":"각청","text":"그걸 적을게. 네가 본 순서대로.","map":"MAP_LIYUE_PLAINS"}]},{"label":"이거부터 올리면 되잖아! 잠깐, 왜 더 내려가—각청, 나 이거 잘못 잡았어!","keep":"REV02_K1_REPEAT_C3","items":[{"k":"line","id":"PRO_L01K_fork_031","speaker":"","text":"봉을 붙잡았는데 반대쪽이 올라갔다. 각청이 뛰어와 내 손 위에 손을 얹었다. 봉이 제자리에 멈췄다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_032","speaker":"각청","text":"손 떼지 말고 그대로. 됐어. 이제 떼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_033","speaker":"짐꾼","text":"구해 주려던 건 알겠는데, 다음엔 소리만 지르시오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_034","speaker":"나","text":"……네. 죄송해요. 손이 먼저 나갔어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_035","speaker":"각청","text":"사과는 나중에. 다친 사람이 없다는 걸 먼저 확인하자.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_036","speaker":"","text":"병사는 자기가 봉을 올렸다는 사실을 끝까지 떠올리지 못했다. 짧은 빈틈. 각청이 말한 것이 이거였다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_120","text":"각청은 말을 끊어 범인을 묻지 않았다. 대신 어느 대목에 다른 사람이 함께 있었는지 물었다. 소의 경고, 그리고 방금 본 일. 내 이름 옆에 두 줄이 적혔다. 함께 확인하지 못한 부분은 그 아래에 적히지 않았다."},{"k":"line","id":"PRO_L01K_fork_037","speaker":"각청","text":"네 자리는 저쪽 그늘이야. 바깥쪽 별도 대기 자리. 이동할 때는 옆 병사에게 방향만 알려 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_038","speaker":"나","text":"입구는 열어 둬요. 물 한 잔 마시러 가는데 허락까지 받으면 저부터 이상해질 것 같으니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_039","speaker":"각청","text":"그 정도는 당연하지. 다음 교대 때 같은 질문을 다시 할 거야. 그전에 몸이 이상하면 먼저 말해. 해가 지도록 아무 말 없이 기다리게 두지는 않겠어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_040","speaker":"","text":"각청은 자리를 뜨기 전에 물을 놓아 주었다. 붙잡혔다고 하기에는 친절했고, 안심하기에는 모르는 것이 너무 많았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_1_END","text":"리월항 밖 별도 대기 자리. 각청에게 소의 경고와 드발린의 죽음·부활을 보았다는 사실을 알렸다. 통행은 닫혀 있고, 옥경대로 가는 별도 길은 안내만 받았다."}]},{"label":"저 포대부터 봐 주세요. 아까 풀려 있던 끈을 봤어요.","keep":"ISK_L01_K_2_CHOOSE","items":[{"k":"line","id":"PRO_L01K_fork_041","speaker":"각청","text":"어느 포대? 짐은 건드리지 말고, 본 자리부터 보여 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_042","speaker":"","text":"색이 다른 끈을 가리키자 각청이 수레 앞에 멈췄다. 짐꾼이 접힌 표를 내밀었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_043","speaker":"짐꾼","text":"아까 여기서 풀고 다시 묶었습니다. 또 풀라니... 이 포대만 몇 번째인지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_044","speaker":"천암군 병사","text":"표시는 있습니다. 하지만 제가 안을 본 기억이 없어서...","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_045","speaker":"나","text":"저 끈이 바닥에 풀린 건 봤어요. 밟을 뻔했거든요. 안쪽까지 본 건 아니고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_046","speaker":"각청","text":"그 정도면 됐어. 끈이 풀렸다는 것과 검사를 마쳤다는 건 나눠서 확인할게.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_047","options":[{"label":"제가 서 있던 곳에서 보여 드릴까요?","id":"PRO_L01K_fork_048","items":[{"k":"line","id":"PRO_L01K_fork_049","speaker":"각청","text":"좋아. 너는 그대로 서 있어. 내가 움직이면서 어느 끈인지 확인할게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_050","speaker":"","text":"각청이 수레 옆으로 돌아서자, 아까 발을 피했던 자리를 가리켰다.","map":"MAP_LIYUE_PLAINS"}]},{"label":"포대는 그대로 두고, 표부터 같이 봐요.","id":"PRO_L01K_fork_051","items":[{"k":"line","id":"PRO_L01K_fork_052","speaker":"각청","text":"그렇게 하자. 짐을 또 풀면 지금 남은 흔적도 바뀔 수 있어. 어떤 표찰을 봤는지 짚어 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_053","speaker":"","text":"각청이 건네받은 표를 펼쳤다. 짐꾼은 풀려던 끈에서 손을 뗐다.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_054","speaker":"각청","text":"봤던 위치와 표찰은 따로 남겨 둘게. 다음 짐은 잠깐 세워 줘. 옆 수레 것과 섞이면 다시 확인해야 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_055","speaker":"천암군 병사","text":"예. 수레를 비켜 두겠습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_056","speaker":"","text":"병사가 수레를 비키려 손잡이를 잡았다. 그 순간 수레가 비탈 쪽으로 미끄러졌다. 짐꾼의 손은 아직 포대 끈 사이에 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_057","options":[{"label":"짧은 손잡이부터 잠글게요. 쐐기는 그다음! 제 손 들어가 있으면 수레 움직이지 마요!","keep":"REV02_K2_BRAKE_C1","items":[{"k":"line","id":"PRO_L01K_fork_058","speaker":"","text":"손잡이 옆 쇠고리를 당기자 바퀴가 잠겼다. 수레는 반 바퀴 돌고 멈췄다. 쐐기는 각청이 발로 밀어 넣었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_059","speaker":"짐꾼","text":"……어제는 사람 받침목, 오늘은 수레 받침목이구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_060","speaker":"각청","text":"손잡이 잠그는 법은 어디서 배웠어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_061","speaker":"나","text":"어제 객잔 승강기에서요. 한 번 보면 잊기 어렵더라고요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"설명은 들었는데 제가 하면 하나는 틀릴 것 같아요. 직접 잠가 주세요. 저는 받침 가져올게요!","keep":"REV02_K2_BRAKE_C2","items":[{"k":"line","id":"PRO_L01K_fork_062","speaker":"","text":"각청이 두 걸음에 수레를 잡고 손잡이를 잠갔다. 내가 받침을 끌어와 바퀴 앞에 끼울 때쯤 수레는 이미 멈춰 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_063","speaker":"각청","text":"모르는 걸 모른다고 말하는 건 빠른 편이네. 받침은 잘 끼웠어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_064","speaker":"짐꾼","text":"둘이 그렇게 척척 맞으면 내 손은 어디다 쓰나.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_065","speaker":"나","text":"아저씨 손은 포대 끈에서 빼는 데 쓰세요. 아직 안 뺐잖아요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"긴 줄을 느슨하게 하면 빠지지 않을까? …아니네, 이거 풀면 전부 쏟아지겠네!","keep":"REV02_K2_BRAKE_C3","items":[{"k":"line","id":"PRO_L01K_fork_066","speaker":"","text":"줄을 잡은 손을 급히 멈췄다. 그 사이 각청이 손잡이를 잠갔다. 포대 하나가 기울었지만 떨어지진 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_067","speaker":"각청","text":"손 멈춘 게 잘한 거야. 그 줄은 짐 전체를 묶는 줄이었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_068","speaker":"나","text":"……네. 하나 더 풀었으면 큰일 났겠네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_069","speaker":"짐꾼","text":"큰일은 내 허리가 났겠지. 그래도 멈춘 사람은 자네니까 됐소.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_070","speaker":"","text":"짐꾼이 끈 사이에서 손을 빼고 길게 숨을 내쉬었다. 각청은 포대를 봉하고 운송 기록을 따로 챙겼다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_153","text":"세 사람은 서로 다른 자리에서 같은 포대를 보았다. 병사의 기억이 돌아온 것은 아니었다. 표에 적힌 글씨가 빠진 기억을 설명해 주는 것도 아니었다. 그래도 새로 움직인 물건이 없다는 사실만은 그 자리에서 함께 확인할 수 있었다."},{"k":"line","id":"PRO_L01K_fork_071","speaker":"각청","text":"네 증언은 네가 본 범위만 적었어. 더 넓히지 않았고, 줄이지도 않았어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_072","speaker":"나","text":"그 정도면 충분해요. 저도 제가 본 것만 말했으니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_073","speaker":"짐꾼","text":"이 포대는 당분간 못 들어가겠지. 나도, 자네도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_074","speaker":"각청","text":"물자 대기 구역에 자리를 마련할게요. 품삯 문제는 제가 확인하겠습니다. 당신이 두 번 일했다는 말로 끝나게 두지는 않을게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_075","speaker":"","text":"각청이 짐꾼에게는 말을 높였다. 짐꾼은 처음으로 허리가 아닌 다른 이유로 고개를 숙였다. 어젯밤의 경고는 아직 말하지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_2_END","text":"리월항 밖 물자 대기 줄. 직접 본 인계의 흔적만 각청에게 증언하고 확인을 기다린다. 소의 경고는 아직 말하지 않았다. 항구는 봉쇄 상태다."}]}]}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_2","text":"나도 뭐든 할게! 구경만 하다가 사람 떨어지는 걸 볼 생각은 없어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_3","text":"그럼 아래를 맡아 줘. 난 행추야. 저 친구는 중운. 소개가 좀 흔들리네!"},{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_4","text":"둘은 익숙하게 자리를 나눴다. 나는 팽팽한 줄을 피해 승강기 아래로 들어갔다. 받침목을 끼울 자리에 부서진 상자가 박혀 있었다."},{"k":"text","id":"V141_AFTER_ISK_L01_K_016_3","text":"소개는 잘 들었어. 두 사람 평소에도 이래? 대답은 저분 내려온 다음에 해 줘!"},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_0","text":"잠깐. 본인이 검사했다는 표식은 있는데, 검사한 기억은 없다? 내가 잘못 들었으면 지금 끊어 줘."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_1","text":"어제 그 친구군! 하루 만에 다시 보다니. 그리고 저 짐꾼 아저씨도. 사라진 기억과 남겨진 화물이라… 흥미로운 사건이네."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_2","text":"책 제목은 사건 끝난 뒤에 지어. 지금 저 병사는 잘못한 게 없어도 일자리를 잃을 수 있고, 저 아저씨는 품삯을 못 받아."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_3","text":"…그건 내가 가벼웠네. 비운 상회 쪽 인계 장소는 내가 안내할 수 있어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_4","text":"행추. 어제는 고마웠어. 이쪽은… 처음 보는데, 연비 맞지? 이름은 들어 봤어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_5","text":"응, 법률 자문을 하고 있어. 지금은 비용보다 현장이 사라지는 게 더 급해. 저 짐이 어디서 인계됐는지, 귀리 평원의 짐터부터 같이 보자."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_0","text":"증거를 모으면 단번에 풀릴 줄 알았는데, 물어볼 사람이 늘었군."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_1","text":"그래서 결말을 먼저 쓰면 안 된다는 거야. 짐은 한 번 옮겨졌고, 표는 두 장이야. 이건 내가 맡아 둘게. 넌 아까 그 병사에게 해고된 건 아니라고 전해 줘."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_2","text":"그 말은 내가 할게. 기다리는 입장이 얼마나 피곤한지 조금 알 것 같아서."}]},{"id":"ISK_L02_K1","entry":"ISK_L02_K1_001","items":[{"k":"keep","id":"ISK_L02_K1_001","text":"별도로 마련된 대기 자리는 생각보다 사람들의 왕래와 가까웠다. 소에게 들은 말을 각청에게 전한 것은 나였다. 그런데 말을 마친 뒤부터는 낯선 사람에게서 이상을 찾기보다 내 몸에서 먼저 이상을 찾게 되었다. 그 아침, 공고를 든 채 멍하니 앉아 있는 나에게 누군가 다가왔다."},{"k":"line","id":"PRO_L02K1_wait_001","speaker":"","text":"첫날 오후, 각청이 돌아왔을 때 나는 두 손가락을 손목 안쪽에 대고 있었다. 처음에는 맥박을 재려던 행동이었는데, 어느 순간부터 뛰고 있다는 사실을 계속 확인해야만 손을 뗄 수 있었다. 각청은 준비해 온 질문을 바로 읽지 않고 그 손을 먼저 보았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_1","text":"어제 소리쳐 사람들을 멈춰 세운 뒤로 목 안쪽이 조금 거칠었다. 적어도 그때 내가 외쳤다는 것은 기억했다. 손목에서 확인하려는 것은 그보다 더 단순한 사실이었다."},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_2","text":"어제 차단봉 앞에서 병사에게 손을 빼라고 말해 준 일을 떠올렸다. 이제는 내 손목을 놓아도 된다고 누군가 말해 줬으면 했다. 남의 불안을 짚어 주는 일은 내 손을 멈추는 것보다 쉬웠다."},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_3","text":"어제 각청이 잘못 잡은 봉에서 내 손을 떼어 놓던 순간이 떠올랐다. 위험한 건 내 몸 안에서만 벌어지는 일이 아니었다. 그래도 모르면 모른다고 외친 것만큼은 잘한 일이었다."},{"k":"line","id":"PRO_L02K1_wait_002","speaker":"각청","text":"몸이 불편해졌어? 아까와 다른 증상이 생겼으면 먼저 말해. 내가 물어본 항목에 없다고 참을 필요는 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_003","speaker":"나","text":"몸은 멀쩡해요. 문제는 멀쩡한지 확인하는 일을 자꾸 하게 된다는 거예요. 자기 맥박에 출석을 부르고 있으면… 좀 피곤하잖아요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_004","speaker":"각청","text":"그 선인이 말한 건 네 주변에서 느낀 기척이지, 네가 죽었다는 판정이 아니야. 네가 전한 말에서도 그 둘은 달랐어. 확인하지 않은 결론을 네 몸에 먼저 붙이지 마.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_005","speaker":"나","text":"머리로는 알아요. 그런데 주변이라고 하면 어디까지가 주변인지 모르겠어요. 옆 사람이 뭘 잊기라도 하면, 내가 너무 가까이 앉았나부터 생각하게 돼요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_006","speaker":"각청","text":"그래서 네가 도착하기 전의 일과 이후의 일을 따로 확인하는 거야. 네가 지나간 자리만 모아서 보면 네가 원인이라는 이야기밖에 못 만들어. 그건 조사가 아니라 결론에 사람을 맞추는 일이야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_007","speaker":"","text":"각청은 천막의 접힌 부분을 올려 바깥길이 보이게 했다. 밖을 볼 수 있자, 바깥에서 나를 볼 수 있다는 생각이 덜 무서워졌다. 숨겨진 사람처럼 앉아 있을 필요가 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_wait_008","options":[{"label":"하루 종일 앉아 있으면 없는 증상도 만들어 낼 것 같아요. 사람 없는 데서 움직일 수는 있죠?","id":"PRO_L02K1_wait_009","items":[{"k":"line","id":"PRO_L02K1_wait_010","speaker":"각청","text":"걸어도 돼. 대기 구역을 벗어날 땐 어디로 가는지만 알려 줘. 너를 붙잡아 두려고 만든 자리가 아니야. 돌아와서는 네가 실제로 겪은 일만 말하면 돼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_011","speaker":"나","text":"그 정도면 충분해요. 갇힌 게 아니라는 말이 듣고 싶었나 봐요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"확인할 때마다 저한테도 결과를 알려 주세요. 뭘 적는지 모르고 앉아 있으면, 괜찮다는 말도 격리 절차처럼 들려요.","id":"PRO_L02K1_wait_012","items":[{"k":"line","id":"PRO_L02K1_wait_013","speaker":"각청","text":"그건 요구할 수 있어. 오늘 네게 확인한 내용은 네 앞에서 정리할게. 다른 병사의 사적인 사정까지 공개할 수는 없지만, 네 상태에 관한 설명은 빼놓지 않겠어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_014","speaker":"나","text":"고마워요. 그거면 돼요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_rain_001","speaker":"","text":"둘째 날에는 비가 들이쳤다. 내가 앉던 천막 끝으로 물이 몰리자, 각청은 옆자리의 빈 받침을 직접 옮겨 천을 들어 올렸다. 내가 손을 보태려 일어서자 그녀는 손가락부터 가리켰다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_002","speaker":"각청","text":"줄 당기는 사람과 받침 미는 사람을 나눠. 둘이 동시에 힘을 주면 기둥만 넘어가.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_rain_003","options":[{"label":"리월 칠성하고 천막 물 빼는 일을 같이 하네요. 나중에 누가 대접 잘 받았냐고 물으면 뭐라고 하죠?","id":"PRO_L02K1_rain_004","items":[{"k":"line","id":"PRO_L02K1_rain_005","speaker":"각청","text":"따뜻한 곳에 앉히려고 했더니 물길을 잘못 잡았다고 해. 네가 젖으면 확인할 증상만 하나 더 늘어. 왼쪽을 조금만 더 당겨. 그렇게 세게 잡으면 천이 찢어져.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_006","speaker":"나","text":"알았어요. 제가 도움을 받는 쪽인지 작업 지시를 받는 쪽인지 잠깐 헷갈렸을 뿐이에요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_007","speaker":"각청","text":"둘 다야. 지금 네 손에 걸린 부분부터 빼고 항의해.","map":"MAP_LIYUE_PLAINS"}]},{"label":"왼쪽 천을 조금씩 당길게요. 어느 정도가 맞는지 보는 쪽에서 말해 줘요.","id":"PRO_L02K1_rain_008","items":[{"k":"line","id":"PRO_L02K1_rain_009","speaker":"각청","text":"천막을 지킬 생각이라면 그 속도가 낫겠어. 손에 힘을 준 만큼 물이 빨리 빠지는 건 아니니까. 거기. 멈춰.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_010","speaker":"나","text":"리월 칠성이 천막 물 빼는 걸 직접 가르쳐 주는 날이 올 줄은 몰랐어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_011","speaker":"각청","text":"나도 네가 이렇게 말 잘 듣는 사람일 줄은 몰랐어.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_rain_012","speaker":"","text":"물이 한꺼번에 빠지며 두 사람의 신발 앞을 적셨다. 각청의 신발도 젖은 것을 보고 참던 웃음이 터졌다. 각청은 이유를 알아차렸지만 설명을 요구하지 않았다. 대신 마른 자리를 발끝으로 확인한 뒤 의자를 그쪽으로 옮겼다. 그날 저녁부터, 천막 안의 나를 실험대 위의 물건처럼 상상하는 횟수가 조금 줄었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_001","speaker":"","text":"셋째 날과 넷째 날에도 병사들의 기억 이상은 풀리지 않았다. 내가 있는 곳에서 멀리 떨어진 자리의 보고가 들어오기도 했고, 곁에서 대화를 나눈 사람이 그 대화를 기억하고 돌아오기도 했다. 내가 무관하다고 확정할 수는 없었다. 다만 내가 입을 열면 누군가 반드시 잊는다는 두려움에는 맞지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_002","speaker":"각청","text":"네가 설산에서 발견했다는 구슬은 지금 가지고 있지 않은 거지? 지난 대답을 의심해서 묻는 게 아니야. 물건을 가진 사람과 발견한 사람을 구분해 적어야 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_003","speaker":"나","text":"없어요. 봤다는 말이 어느새 꺼내 줄 수 있다는 말로 바뀌면 곤란하잖아요. 제 짐을 전부 뒤져도 그건 안 나와요. 솔직히… 없어서 다행인지 아닌지도 모르겠어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_004","speaker":"각청","text":"그럼 발견한 사람으로만 남겨 둘게. 몬드의 확인도 아직 도착하지 않았어. 진이 함께 보았다는 네 증언과, 우리가 진에게 직접 들은 말은 구별해야 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_005","speaker":"","text":"그녀는 모르는 것을 모른다고 말했다. 이전 같았으면 답답했을 태도였다. 그러나 내 주변에 죽음의 냄새가 난다는 말을 들은 뒤로는, 섣불리 안심시키지 않는 쪽이 오히려 믿을 만했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_006","speaker":"나","text":"의례 때는 저도 올라갈 수 있는 거죠? 여기까지 왔는데 항구 밖에서 지붕만 보다가 돌아갈 수는 없잖아요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_007","speaker":"각청","text":"행사 통로는 예정대로 열어. 일반 거리가 개방되는 건 아니고, 옥경대로 올라갔다가 같은 길로 내려오는 거야. 네가 별도로 대기했다는 이유로 참관을 막을 계획은 없어. 다만 그 자리에서 원하는 사람을 마음대로 만날 수 있다는 뜻도 아니야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_008","speaker":"","text":"그 말에서 앞부분만 고르고 싶었다. 내가 기억하는 이야기에서는 신이 하늘에서 떨어지고, 그 뒤는 살아 있는 신의 계획으로 이어졌다. 공고의 송신의례라는 이름은 여전히 기억과 맞지 않았다. 드발린의 죽음 뒤로 나는 게임의 순서를 확신할 수 없었다. 그래도 미리 안다고 믿는 부분이 하나 있다는 사실에 자꾸 기대고 싶었다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_029","text":"닷새가 지난 아침, 천막 사이로 사람들의 발걸음이 일찍부터 이어졌다. 바깥 생활에 익숙해질 만큼 시간이 흘렀지만, 누구도 이곳을 자기 집이라 부르지는 않았다. 내가 앉던 자리의 천을 정리하고 나섰다. 돌아오면 다시 그 자리에 앉을 것이라는 생각은 아주 자연스러웠다."},{"k":"keep","id":"ISK_L02_K1_030","text":"옥경대로 향하는 길 앞에서 안내 병사가 사람들을 나누어 보냈다. 길목 옆의 거리는 여전히 막혀 있었고, 상점 쪽으로 빠지려던 사람이 제지당했다. 내게 허용된 것은 도시 입장이 아니라 의례 참관이었다."},{"k":"line","id":"PRO_L02K1_rite_001","speaker":"안내 병사","text":"앞사람과 너무 붙지 마십시오. 올라갈 때는 오른쪽으로, 내려올 때는 맞은편 줄을 이용합니다. 길을 벗어나시면 다시 바깥 대기 구역으로 안내합니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rite_002","speaker":"나","text":"알겠어요. 이 길로만 올라갔다가 이 길로만 내려오겠습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_033","text":"줄을 따라 올라가는 동안 항구의 소리는 가까워졌다가 벽 뒤로 멀어졌다. 나들이처럼 옷깃을 정리하는 사람도 있었고, 의례라도 열리면 혼란이 가라앉지 않겠느냐고 기대하는 사람도 있었다. 기억을 잃은 병사들의 이야기는 낮은 목소리로 오갔다."},{"k":"line","id":"PRO_L02K1_rite_003","speaker":"","text":"옥경대에 도착하자 나는 가장 먼저 내려가는 길의 위치를 확인했다. 도망칠 생각이라기보다, 모르는 군중 속에 들어왔을 때 몸이 먼저 하는 일이었다. 각청은 통로가 꺾이는 곳에서 병사에게 지시를 내리고 있었다. 눈이 마주치자 그녀는 짧게 고개를 끄덕였다. 닷새 동안의 대화가 그 작은 반응 안에 남아 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_004","speaker":"각청","text":"올라오는 데 문제는 없었어? 도중에 불편해진 건 없고?","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K1_rite_005","options":[{"label":"이번에는 제 몸 말고 의례 쪽을 먼저 봐요. 저도 가끔은 구경 온 사람처럼 서 있고 싶어요.","id":"PRO_L02K1_rite_006","items":[{"k":"line","id":"PRO_L02K1_rite_007","speaker":"각청","text":"좋아. 줄이 움직이면 가운데로 밀리지 말고 이쪽 가장자리를 따라와. 혼자 빠져나가려다 되돌아오는 사람들과 부딪히지 말고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"괜찮아요. 몸이 이상해지면 바로 말할게요. 그러니까 오늘은 묻기 전에 제가 먼저 말하는 걸로 해요.","id":"PRO_L02K1_rite_008","items":[{"k":"line","id":"PRO_L02K1_rite_009","speaker":"각청","text":"그 정도면 됐어. 네가 먼저 말해 주면 나도 다른 쪽을 살필 수 있으니까. 줄이 움직이면 이쪽 가장자리를 따라와.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L02_K1_038","text":"의례가 시작되었다. 시선들이 한꺼번에 높은 곳으로 향했다. 나도 고개를 들었다가, 하늘을 가르며 내려오는 거대한 몸을 보았다. 예상하고 있었다는 말은 충돌음 앞에서 아무 쓸모가 없었다. 돌이 울리고 먼지가 솟았다. 모락스의 시신이 의례 한복판에 떨어져 있었다."},{"k":"line","id":"PRO_L02K1_rite_010","speaker":"","text":"아무 말도 하지 못하는 순간 뒤에 질문들이 한꺼번에 터졌다. 제군에게 무슨 일이 생긴 것인지, 누가 손을 댄 것인지. 원작을 떠올리려 했지만 눈앞의 먼지와 떨리는 목소리들이 그 기억 위를 덮었다. 화면 속 장면에는 나를 밀치는 사람의 팔꿈치가 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_011","speaker":"응광","text":"뒤쪽 통로를 비워. 쓰러진 사람이 있으면 먼저 확인하고, 단상으로 접근하는 사람은 막아. 추측을 사실처럼 전하지 마. 지금 필요한 건 각자가 직접 본 일이야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_012","speaker":"","text":"응광의 목소리는 군중 위로 또렷하게 지나갔다. 각청은 앞으로 밀려오는 줄을 멈추고, 넘어진 사람이 일어설 공간을 만들었다. 나에게도 자리를 지키라고 손짓했다. 그러나 나는 알고 있었다. 이 뒤에 무엇이 오는지. 응광에게 말해야 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_013","speaker":"나","text":"각청, 응광하고 따로 이야기하게 해 줘요. 여기서 다 같이 들을 얘기는 아닌데, 지금 꼭 전해야 할 말이 있어요. 잠깐이면 돼요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_014","speaker":"각청","text":"지금은 안 돼. 네가 의심받을 말이라서 막는 게 아니야. 현장을 확보하는 사람을 개인 면담으로 뺄 수 없어. 급한 내용이면 내게 말해. 전달할 수 있는 건 내가 전달할게.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K1_rite_015","options":[{"label":"모락스의 죽음이 사람들이 생각하는 그대로가 아닐 수도 있어요. 모두가 같은 결론을 내리게 두면 안 돼요.","id":"PRO_L02K1_rite_016","items":[{"k":"line","id":"PRO_L02K1_rite_017","speaker":"각청","text":"그래서 아직 결론을 발표하지 않았어. 네가 아는 것이 있다면 무엇을 보고 알았는지부터 말해. 누구를 따로 만나느냐가 먼저가 아니야. 지금 군중 앞에서 그 말을 더 크게 하지는 마.","map":"MAP_LIYUE_HARBOR"}]},{"label":"기억을 잃는 일하고 이번 일이 겹쳤잖아요. 제가 몬드에서 본 것도 죽었다가 다시 움직이는 일이었어요.","id":"PRO_L02K1_rite_018","items":[{"k":"line","id":"PRO_L02K1_rite_019","speaker":"각청","text":"네가 전한 내용은 기억하고 있어. 하지만 드발린에게 일어난 일을 여기 그대로 대입할 수는 없어. 네 증언을 빼놓겠다는 뜻이 아니야. 먼저 사람들이 다치지 않게 길을 비켜 줘.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L02K1_rite_020","speaker":"","text":"다시 응광을 찾았다. 그녀는 이미 다른 쪽으로 이동하고 있었다. 옷자락이 잠깐 보였고, 곧 시야에서 사라졌다. 이름을 외치면 그 다음 말을 군중 앞에서 해야 했다. 각청 쪽으로 몸을 돌렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_021","speaker":"나","text":"가 버렸잖아요. 나중에 전해 준다는 말이 얼마나 나중인지도 모르는데… 이번에는 저도 기다리면 안 될 것 같은데요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_022","speaker":"각청","text":"나도 네가 답답해하는 건 알아. 그래도 이 선을 넘게 할 수는 없어. 내가 계속 여기서 네 말을 듣고 있잖아. 다른 사람에게만 말할 수 있다고 버티지 말고, 지금 위험한 게 무엇인지부터—","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_001","speaker":"","text":"각청의 말이 중간에서 끊겼다. 숨을 고르려는 멈춤과는 달랐다. 그녀의 손이 공중에 남은 채 힘을 잃었고, 발을 고쳐 디디기도 전에 몸이 무너졌다. 내가 손을 뻗는 동안 옆의 병사도 쓰러졌다. 뒤쪽에서 부딪치는 소리가 이어졌다. 비명을 지르던 사람의 입이 열린 그대로 조용해졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_002","speaker":"","text":"각청의 어깨를 받치려다 함께 주저앉았다. 그녀는 눈을 감으라는 말도, 놓으라는 말도 하지 않았다. 조금 전까지 좁기만 하던 곳에서 사람의 움직임이 한꺼번에 사라졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_003","speaker":"나","text":"각청, 장난할 상황 아니잖아. 눈 좀 떠 봐. 아까 하던 말부터 끝내. 내가 듣고 있으니까, 일단 숨부터 쉬어. 제발.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_056","text":"손목을 더듬었다. 닷새 내내 내 손목에서 찾았던 박동이 이번에는 없었다. 잡는 위치를 틀렸다고 생각해 손가락을 옮겼다. 얼굴을 가까이 대어도 숨이 닿지 않았다. 옆 병사도 같았다. 무릎을 세워 앉아 있던 사람도, 돌바닥에 팔을 짚던 사람도 이미 죽어 있었다. 이곳에서 살아 움직이는 것은 나뿐이었다."},{"k":"line","id":"PRO_L02K1_death_004","speaker":"","text":"살았다는 사실을 확인하자 안심해야 했다. 그런데 내 가슴이 뛰는 것이 견디기 어려웠다. 누군가를 일으키지도 못하는 손이 혼자 따뜻했다. 천막에서 각청에게 했던 말이 돌아왔다. 내가 가까이 앉아서 누군가 잊으면 어쩌느냐던 말. 이번에는 잊은 것이 아니었다. 내가 팔을 받치고 있는 사람이 죽었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_005","speaker":"나","text":"누구든 대답해 봐요. 아무나, 내 말 들리면 소리 좀 내 줘요. 여기 사람들 쓰러졌어요. 도와주세요!","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_059","text":"대답 대신 바닥에 떨어진 물건이 굴러와 발끝에 닿았다. 그것을 밟지 않으려 발을 옮기다가 뒤로 물러섰다. 각청을 놓고 일어나 버렸다는 것을 알아차렸지만 다시 앉지 못했다. 더 가까이 가면 안 될 것 같았다. 어디에도 근거가 없는 생각이었으나, 그 순간에는 도망가는 방향을 정하기에 충분했다."},{"k":"line","id":"PRO_L02K1_death_006","speaker":"","text":"비명을 삼키지 못한 채 계단을 내려갔다. 사람을 밟을까 봐 발을 고르다가 벽에 부딪쳤고, 충격을 느낀 뒤에도 멈추지 않았다. 등 뒤에서 누가 붙잡아 주기를 바라면서도 뒤를 볼 수 없었다. 나를 부를 목소리가 이제 없다는 사실을 돌아보아 확인하고 싶지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_061","text":"올라올 때 확인해 둔 길이 몸을 이끌었다. 행사 통로를 벗어나 외곽의 흙길을 밟았을 때에도 한참 더 달렸다. 사람을 만날 가능성이 있는 길목이 보이면 옆으로 피했다. 갈 곳을 정한 것이 아니라, 다른 사람 옆에 멈추는 일을 미루고 있었다."},{"k":"line","id":"PRO_L02K1_death_007","speaker":"","text":"발이 더 나가지 않는 곳에서 길가의 낮은 바위에 기대었다. 손바닥에 묻은 흙이 보였다. 각청의 어깨를 받칠 때 묻었는지, 계단에서 넘어졌을 때 묻었는지 구별할 수 없었다. 숨을 잘못 삼켜 기침이 났다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_008","speaker":"","text":"몬드로 돌아가 진에게 알리는 길이 떠올랐다. 진은 드발린의 죽음도 함께 확인한 사람이었다. 그러나 그곳까지 가는 동안 또 다른 일이 생기면. 그리고 이번에는 내 주변에 머무른 사람들만 죽었다면. 그 가정을 지울 근거를 나는 가지고 있지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_009","speaker":"나","text":"……선인을 만나자. 내가 무서워서 산으로 숨는 거여도, 찾아가서 말할 사람은 있어야 하잖아. 류운차풍진군. 그분이라면 적어도 내가 본 걸 설명할 때까지는 들어 주겠지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_010","speaker":"","text":"말로 목적지를 정하자 흩어지던 생각들이 한 방향으로 모였다. 소를 찾아 되돌아갈 수도 있었지만, 그가 지금 어디에 있는지는 몰랐다. 류운차풍진군에게는 찾아갈 거처가 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_066","text":"평야에서 산으로 빠지는 갈림길을 한 번 지나쳤다. 되돌아왔을 때 해의 위치가 바뀌어 있었다. 머릿속 지도에는 여행자의 체력도, 내 가쁜 숨도 표시되어 있지 않았다. 바위 위로 곧장 오르면 빠를 것 같았지만, 손을 뻗어 본 높이 앞에서 결국 돌아가는 길을 택했다."},{"k":"line","id":"PRO_L02K1_mountain_001","speaker":"","text":"한쪽으로 몸을 기울여 통과해야 하는 구간에서 벽을 등지고 오래 서 있었다. 발밑을 보지 않으려 고개를 들면 구름이 움직였고, 구름이 움직이면 내가 선 바위도 흔들리는 듯했다. 추락하면 누군가 살아 돌아오는 기적이 내게도 일어날지. 그 생각이 스친 것만으로 속이 울렁거렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_002","speaker":"나","text":"……죽었다가 살아나는 걸 두 번 기대하는 건 염치없지. 살아서 올라가는 쪽으로 하자.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_003","speaker":"","text":"쉬는 동안 눈을 감으면 각청이 말을 끝내지 못하던 입 모양이 떠올라서, 눈을 뜬 채 발끝만 보았다. 산의 고요는 의례장의 고요와 달랐다. 새가 날고 바람이 나뭇잎을 흔들었다. 그 소리를 확인할 때마다 다시 걸을 수 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_004","speaker":"","text":"거처에 이르렀을 때 나는 문이 닫혀 있다는 사실에 먼저 주저앉을 뻔했다. 산을 올라오기만 하면 다음 장면이 시작될 줄 알았다. 문은 사람의 도착을 알아서 헤아려 주지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_mountain_005","options":[{"label":"류운차풍진군을 뵈러 왔습니다. 아래에서 큰일이 났어요. 예를 잘 갖추지는 못했는데, 일부러 그런 건 아닙니다.","id":"PRO_L02K1_mountain_006","items":[{"k":"line","id":"PRO_L02K1_mountain_007","speaker":"","text":"대답은 없었다. 기억 속 공양 절차를 떠올렸다가 손을 내려다보았다. 갖추지도 못한 음식을 있다고 할 수는 없었다. 문을 두드리면 무례일까 고민하다가, 무례가 두려워 돌아갈 상황이 아니라는 생각에 손을 들었다. 손끝이 닿기 전에 안쪽에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_008","speaker":"류운차풍진군","text":"문을 부술 생각으로 손을 드는 것이라면 내려놓게. 열리지 않는 문 앞에서는 먼저 주인이 들었는지부터 기다리는 법이니. 자네가 이곳까지 허둥지둥 올라온 사정은 무엇인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_009","speaker":"나","text":"들으셨으면 대답을 조금만 빨리 해 주시지 그랬어요. ……죄송합니다. 투정 부릴 때가 아닌 건 알아요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"(문 옆에 서서 기다린다.)","id":"PRO_L02K1_mountain_010","items":[{"k":"line","id":"PRO_L02K1_mountain_011","speaker":"","text":"문 옆으로 비켜서서 숨을 골랐다. 안에 아무도 없다면 기다려도 소용없고, 안에 있는데 예를 모르니 돌려보낸 것일 수도 있었다. 어느 쪽도 확인할 수 없어 그대로 서 있었다. 한참 뒤 안쪽에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_012","speaker":"류운차풍진군","text":"문을 두드리지도, 돌아가지도 않는군. 그 정도 참을성이면 들을 만하겠지. 자네가 이곳까지 허둥지둥 올라온 사정은 무엇인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_013","speaker":"나","text":"기다리는 건 닷새 동안 연습했거든요. ……죄송합니다. 농담할 때가 아닌데.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_mountain_014","speaker":"나","text":"아래에서 모락스의 시신이 떨어졌습니다. 그리고 사람들이 죽었어요. 제가 있던 곳에서, 저만 빼고 전부요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_015","speaker":"","text":"안쪽의 기척이 멈췄다. 더 말하려다 숨이 목에 걸렸다. 내가 방금 한 말을 다시 들으면 나라도 받아들이지 못할 것 같았다. 그러나 내가 문밖에서 순서를 다듬는 동안에도 아래에 두고 온 사람들의 몸은 그대로일 것이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_016","speaker":"류운차풍진군","text":"제군의 일과 사람들의 죽음을 한숨에 묶어 말하지 말게. 언제, 어디서, 무엇을 보았는지 차례로 답할 수 있겠나. 이 몸이 듣고 있으니 목소리부터 낮추고 호흡을 고르게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_017","speaker":"나","text":"차례대로 말할 수 있어요. 대신 문밖에서 소리치는 건 여기까지 했으면 합니다. 또 사람 앞에서 이상한 일을 일으킬까 봐 도망쳐 온 건데, 문에 대고 말하니까 정말 혼자 남은 것 같아서요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_018","speaker":"","text":"문이 열렸다. 나는 곧장 들어가지 못했다. 안쪽에 모습을 드러낸 학이 나를 바라보았다. 그림으로 기억하던 자태와 달리, 눈앞의 존재는 가만히 서 있는 것만으로 내가 걸어온 거리를 작게 만들었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_019","speaker":"류운차풍진군","text":"들어오게. 다만 자네가 무엇인지 이 몸이 벌써 판단한 것은 아니니, 그 표정으로 스스로 판결을 내리지는 말거라. 저 돌턱은 낮아 보이지만 발이 걸리기 쉽다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_audience_001","speaker":"","text":"지정받은 자리에 앉았다. 무릎이 굽혀지자 올라오는 동안 참았던 통증이 한꺼번에 느껴졌다. 류운차풍진군은 내가 허리를 펴기도 전에 질문을 이어가지 않았다. 그 짧은 기다림 때문에 나는 오히려 먼저 입을 열 수 있었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_002","speaker":"나","text":"리월항은 며칠 전부터 막혀 있었어요. 천암군 일부가 조금 전 일을 기억하지 못해서요. 저는 항구 밖에서 닷새를 기다렸고, 오늘 의례 길이 열려서 옥경대로 올라갔습니다. 시작하자마자 모락스의 몸이 떨어졌어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_003","speaker":"류운차풍진군","text":"떨어진 것을 직접 보았고, 그 몸을 제군의 시신이라 여겼다는 말이군. 자네가 그 자리에서 죽음을 확인한 사람들은 또 누구인가? 제군의 몸과 같은 방식으로 판단했는지 묻는 게야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_004","speaker":"나","text":"각청은 바로 앞에 있었어요. 말을 하다가 쓰러져서 제가 받쳤습니다. 숨이 없었고 맥박도 없었어요. 다른 사람도 확인했는데 같았고요. 계속 불렀는데, 아무도 돌아오지 않았습니다. 그 사람들은 죽었어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_005","speaker":"","text":"말을 끝내자 처음으로 각청의 이름을 부르는 일이 견딜 만해졌다. 그녀를 업고 도망치지 못했다는 생각은 여전히 남아 있었다. 류운차풍진군은 곧바로 위로하지 않았다. 대신 내가 직접 확인한 범위와, 볼 수 없었던 범위를 하나씩 짚었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_006","speaker":"류운차풍진군","text":"응광은 그 전에 자리를 떠났고, 자네는 그 뒤의 행방을 보지 못했다. 그렇다면 그 사람의 생사까지 같은 말로 묶지는 않겠네. 어디까지 알며 어디서부터 모르는지가 분명해야, 이 몸도 움직일 방향을 정할 수 있지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_007","speaker":"","text":"맞는 말이었다. 내가 못 본 사람까지 죽었다고 할 수는 없었다. 누군가는 밖에 있었을 것이다. 그리고 내가 이곳까지 온 이유가 하나 더 있었다. 숨을 고르고 고개를 들었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K1_audience_008","options":[{"label":"믿기 힘드실 텐데, 이건 모락스의 계략이에요. 리월이 스스로 버틸 수 있는지 보려는 계획. 오셀이 나올 수 있으니 막을 준비를 하셔야 해요.","keep":"ISK_L02_K1_086","items":[]}]},{"k":"line","id":"PRO_L02K1_audience_009","speaker":"","text":"류운차풍진군의 시선이 달라졌다. 놀라서 물러나는 반응이 아니었다. 내가 해서는 안 될 이름을 우연히 입에 담았는지, 아니면 그 말의 무게를 알고 있는지 가늠하는 침묵이었다. 그 침묵을 견디면서 손가락을 무릎 위에 펼쳤다. 다시 맥박을 찾기 시작하면 말을 이어가지 못할 것 같았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_010","speaker":"류운차풍진군","text":"자네가 말하는 계략에 방금 죽었다는 사람들까지 포함되어 있나? 제군의 이름을 앞에 붙인다고 서로 다른 일이 하나의 이유가 되는 것은 아닐세. 그리고 오셀이라는 이름은 어디에서 들었지?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_011","speaker":"나","text":"아니요. 사람들까지 죽는 건 제가 알던 일에 없었어요. 그 부분은 모르겠습니다. ……제가 살던 곳에서 이곳의 일을 이야기로 알고 있었어요. 당신이 계신 곳도 그래서 떠올렸고요. 그런데 여기서는 드발린이 진짜로 죽었다가 살아났고, 오늘은 제 눈앞에서 사람들이 죽었습니다. 제가 알던 이야기만 믿고 괜찮을 거라 말할 수는 없어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_012","speaker":"류운차풍진군","text":"그렇다면 먼저 그 두 가지를 나누게. 자네가 가지고 온 옛 지식과, 오늘 자기 눈으로 본 일이야. 앞의 것이 얼마나 맞는지 확인하는 동안 뒤의 것을 버릴 필요는 없지. 하지만 앞의 것을 핑계로 뒤의 일을 설명했다고 여겨서도 안 되네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K1_audience_013","options":[{"label":"제 말을 전부 믿지 않으셔도 돼요. 바다 쪽을 확인하고 대비만 해 주세요. 제가 틀리면 민망한 걸로 끝나지만, 맞는데 준비가 없으면 사람이 더 죽잖아요.","id":"PRO_L02K1_audience_014","items":[{"k":"line","id":"PRO_L02K1_audience_015","speaker":"류운차풍진군","text":"민망함의 크기를 비교하려는 자리가 아니니 그 허세는 내려놓게. 다만 위험의 이름을 구체적으로 말했고 현장의 사정을 함께 가져온 점은 가볍게 듣지 않았네. 자네가 경고했다는 사실은 남을 것이야.","map":"MAP_LIYUE_MOUNTAINS"}]},{"label":"다 맞힐 자신은 없어요. 그래도 모르는 척하고 내려가면 각청 앞에서 하던 일을 또 하는 것 같아서요. 중요한 얘기가 있다고만 하고 끝까지 말하지 못했거든요.","id":"PRO_L02K1_audience_016","items":[{"k":"line","id":"PRO_L02K1_audience_017","speaker":"류운차풍진군","text":"이미 끝난 대화를 이 자리에서 다시 이기려 하지 말게. 자네가 지금 해야 할 일은 그 사람에게 하지 못한 말로 자신을 벌주는 것이 아니라, 아직 전할 수 있는 말을 빠뜨리지 않는 것이야. 계속해 보게.","map":"MAP_LIYUE_MOUNTAINS"}]}]},{"k":"line","id":"PRO_L02K1_audience_018","speaker":"","text":"더 전할 것이 있는지 생각하자 망서 객잔의 소가 떠올랐다. 각청에게 말했던 일을 여기서도 다시 꺼내야 했다. 그러면 내가 원인일지 모른다는 두려움까지 드러나겠지만, 거기까지 감춘 채 판단을 구하고 싶지는 않았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_019","speaker":"나","text":"망서 객잔에서 소를 만났어요. 제 주변에 죽음과 생명의 냄새가 함께 나고, 마신을 향한 강한 혐오도 느껴진다고 했습니다. 그분도 기척의 주인이나 원인은 확정하지 않았어요. 그래서 사람이 없는 길로 왔습니다. 혹시 제가 원인이면… 올라오다 보니 당신도 만나면 안 되는 건가 싶었는데, 그럼 저는 어디 가서 누구한테 말해야 하죠?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_020","speaker":"류운차풍진군","text":"자네 혼자 살아남았다는 것과 자네가 죽였다는 것은 같은 말이 아니네. 이 몸 앞에서 자네가 벌을 달라고 해도 그 빈칸을 대신 채워 줄 생각은 없어. 소가 한 말 역시 들었네. 허나 지금 들은 말만으로 자네 곁에 선 존재는 모두 죽는다고 결론 내릴 수는 없지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_021","speaker":"","text":"아무 일도 없을 것이라는 약속이 아니었다. 그것을 알아들었다. 나를 안전한 사람이라 선언해 달라고 요구할 근거가 없듯, 위험한 사람이라 선언해 달라고 요구할 근거도 없었다. 어깨가 내려가자 의례장을 나온 뒤 처음으로 숨이 끝까지 들어왔다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_022","speaker":"나","text":"제가 여기서 잠깐 쉬어도 될까요? 대답은 다 했다고 생각했는데, 일어서려고 하니까 다리가 말을 안 듣네요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_023","speaker":"류운차풍진군","text":"앉아 있으라 했으면 쉬어도 된다는 뜻이지. 발목을 그런 식으로 비틀고 있으면 일어날 때 더 아플 테니 곧게 놓게. 인간의 몸은 쓰러지기 직전까지 버틴다고 더 오래 가는 물건이 아니야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_024","speaker":"","text":"자세를 고쳐 앉자 그녀는 한 차례 더 발목을 살피고서야 눈을 돌렸다. 웃을 여유가 있었다면 잔소리를 들었다고 생각했을 것이다. 지금은 누군가 내 다음 걸음을 실제로 걱정한다는 사실만 남았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_025","speaker":"류운차풍진군","text":"이 몸도 항구 쪽 사정을 확인하겠네. 자네의 이야기를 그대로 받아 적고 끝낼 일은 아니니. 경계를 늦춰도 된다고 말할 근거가 없는 만큼 필요한 대비도 살펴보지. 그렇다고 자네가 산을 내려가는 동안 모든 길이 안전해진다고 생각하지는 말게.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_026","speaker":"나","text":"알겠습니다. 내려가면 제가 도망친 길부터 다시 볼게요. 사람을 만나면 피하지 않고, 살아 있는 사람이 있으면 어디서 왔는지 물어보겠습니다. 다만 지금 바로 뛰어 내려가라고는 하지 말아 주세요. 의욕 문제가 아니라 다리 문제예요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_027","speaker":"류운차풍진군","text":"이제야 두 가지를 제대로 나누는군. 마음이 급한 것과 발이 움직일 수 있는 것은 별개지. 쉬었다 가게. 자네가 가져온 이야기는 이 몸이 들었으니, 문밖에서 다시 외칠 필요도 없네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_return_001","speaker":"","text":"몸을 추스르고 밖으로 나왔을 때 산의 빛은 이미 낮과 달랐다. 어둠이 깊어지는 구간에서는 바람을 피할 만한 곳에서 기다렸다. 눈을 감는 일은 여전히 어려웠지만, 한 번도 쉬지 않은 몸으로 비탈을 내려가는 일이 용기라는 생각은 하지 않기로 했다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"keep","id":"ISK_L02_K1_108","text":"밤이 지나 길의 모양이 다시 보이자 산 아래로 향했다. 오를 때 지나친 갈림길에서 한동안 멈췄다. 도망칠 때의 나는 리월에서 멀어지기만 하면 된다고 생각했다. 돌아가는 지금의 나에게는 확인할 곳이 있었다. 각청을 놓고 일어난 자리였다."},{"k":"line","id":"PRO_L02K1_return_002","speaker":"","text":"리월항 외곽의 길에는 사람의 소리가 있었다. 화물 때문에 다투는 목소리, 길을 비켜 달라는 말, 바퀴가 돌을 넘는 소리. 눈앞의 움직임 하나하나가 별개의 소식으로 다가왔다. 그러나 그것들이 옥경대에 두고 온 사람들을 설명해 주지는 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_110","text":"봉쇄선은 남아 있었다. 병사들은 오가는 사람을 확인했고, 옆길로 들어서려는 행렬을 바깥으로 돌렸다. 사람들 사이에서 각청의 목소리를 들었다. 처음에는 비슷한 음성이라고 생각했다. 얼굴을 본 뒤에는 그 생각조차 할 수 없었다."},{"k":"line","id":"PRO_L02K1_return_003","speaker":"","text":"각청은 서 있었다. 어깨를 곧게 펴고 상대의 설명을 들으며, 필요한 대목에서 질문하고 있었다. 내 손 안에서 무게만 남았던 몸이 스스로 움직였다. 그녀가 고개를 돌렸을 때 나도 모르게 앞으로 나섰다가 멈췄다. 반가워해야 하는지, 달아나야 하는지, 결정할 수 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_return_004","speaker":"나","text":"각청… 너 어떻게 살아 있어? 내가 바로 앞에서 봤는데. 네 손을 잡고, 숨도 확인했는데. 나한테 지금 위험한 게 뭐냐고 묻다가 쓰러졌잖아. 그 말, 아직 끝내지도 못했잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_113","text":"각청은 내 얼굴을 바라보았다. 닷새 동안 상태를 묻고, 비 새는 천막을 함께 들어 올리고, 의례장 가장자리를 알려 주었던 사람이었다. 그러나 그 얼굴에, 알아본 사람에게만 잠깐 생기는 반응이 없었다. 시선은 낯선 이의 다친 손과 흐트러진 차림을 살핀 뒤 다시 눈으로 돌아왔다."},{"k":"line","id":"PRO_L02K1_return_005","speaker":"각청","text":"잠깐. 내 이름을 부르는 건 알겠는데, 우리는 어디서 만났지? 너, 나를 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_END","text":"리월항 외곽 봉쇄선. 이야기는 살아 있는 각청의 질문 앞에서 멈춘다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_0","text":"송신의례라는 공고를 보여 주자 그녀는 답 대신 반송된 보고통을 꺼냈다. 고운각의 경계대가 보낸 통이었다. 안에는 종이가 없었다."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_1","text":"처음 뵙겠습니다. 월해정 비서 감우입니다. 각청 님께 말씀은 들었어요. 그 공고를 들고 저를 찾아오신 분은 당신이 처음이네요."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_4","text":"저도 가겠습니다. 아는 이야기가 맞는지 입으로만 떠들고 있었잖아요. 이번엔 지금 일어난 일을 보러 가고 싶어요."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_6","text":"그 말은 보고통 찾아온 다음에 해. 네가 밤새 혼자 찾는 동안 우리 둘이 멀쩡히 쉬고 있기도 어렵거든. 이 사람은 대기 자리에서 벗어난다고 병사한테 말해 두면 돼."},{"k":"text","id":"V141_AFTER_ISK_L02_K1_001_3","text":"해안 경계를 바꾸고, 배를 확인하고. 좋아. 이제 저도 할 수 있는 말이 생겼네요. 불길하다는 말 말고요."}]},{"id":"ISK_L02_K2","entry":"ISK_L02_K2_001","items":[{"k":"keep","id":"ISK_L02_K2_001","text":"다음 날에도 짐은 봉쇄선 밖에 남아 있었다. 나는 눈앞에서 본 사고를 다시 설명해야 했다. 한 번 이야기하면 집에 갈 수 있을 줄 알았던 짐꾼은 내 옆에 쪼그려 앉아 손바닥의 굳은살을 문질렀다. 같은 아침을 또 시작한 것 같았다. 그때 아는 얼굴이 수레 사이로 나타났다."},{"k":"line","id":"PRO_L02K2_wait_001","speaker":"짐꾼","text":"당신은 갈 데 있으면 가도 되오. 눈으로 본 것까지 말해 줬는데, 여기 붙들어 놓으면 내가 미안해지지. 나는 어차피 이 짐 두고는 못 가니까.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_1","text":"짐꾼은 쪼그려 앉기 전에 받침 수레의 짧은 손잡이를 한 번 더 눌렀다. 어제 내가 잠갔던 것과 같은 장치였다. 이제 확인표에 체크가 있어도 손으로 확인하지 않고는 떠나지 못하는 모양이었다."},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_2","text":"어제 내가 끌어온 받침은 병사가 다시 정리해 두었다. 짐꾼이 나를 붙잡아 두기 미안해하는 것과, 어제 일을 고마워하는 것은 다른 일이었다. 둘을 굳이 빚으로 묶고 싶지는 않았다."},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_3","text":"나는 긴 짐끈에 손대지 않고 받침 수레의 잠금부터 살폈다. 어제 한 번 식은땀을 흘렸다고 전문가가 되지는 않았다. 대신 자신 없는 장치는 먼저 묻게 됐다."},{"k":"line","id":"PRO_L02K2_wait_002","speaker":"나","text":"갈 데가 있으면 이 포대 옆에서 먼지를 털고 있겠어요? 그렇다고 제가 짐 주인은 아닙니다. 나중에 손해 났다고 반씩 책임지자는 말만 안 하시면, 조금 더 같이 있어 드릴게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_003","speaker":"짐꾼","text":"반씩 낼 사람이 있었으면 당신부터 안 골랐을 거요. 얼굴에 돈 아깝다는 소리가 아주 잘 쓰여 있으니까. 밧줄 잘못 밟아서 짐이나 넘어뜨리지 마시오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_004","speaker":"","text":"내가 발밑을 확인하자 짐꾼은 그제야 조금 웃었다. 웃음이 사라진 뒤에는 다시 짐을 보았다. 넘겼다고 주장할 수도, 넘기지 않았다고 확답할 수도 없는 일 사이에서 그는 포대의 무게를 계속 자기 어깨에 얹고 있는 사람처럼 앉아 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_001","speaker":"","text":"해가 기울 무렵, 각청이 대기 자리로 돌아왔다. 짐꾼이 일어서자 그녀가 앉아 계시라는 손짓을 했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_002","speaker":"각청","text":"짐부터 볼게요. 아까 제가 확인한 뒤에 옮기지는 않으셨죠?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_003","speaker":"짐꾼","text":"그대로 뒀소. 풀지도 않았고. 다음 사람이 오면 또 풀자고 하겠지만...","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_004","speaker":"","text":"각청은 포대의 묶인 부분을 살핀 뒤 병사를 불렀다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_005","speaker":"각청","text":"이 짐은 따로 맡아 줘. 다음 담당자가 와도 다시 풀기 전에 이 표부터 보여 주고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_006","speaker":"천암군 병사","text":"예. 두 분도 여기서 기다리시게 할까요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_007","speaker":"각청","text":"아니. 짐을 지키는 건 우리 일이야. 계속 옆에 붙어 있게 할 필요는 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_008","speaker":"짐꾼","text":"그럼 오늘은 어디까지 된 거요? 같은 설명만 하다가 해가 졌소. 나도 내일 할 일이 있는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_009","speaker":"각청","text":"오늘 안에 끝난다고 약속할 수는 없어요. 대신 담당자가 바뀔 때마다 처음부터 다시 확인하는 일은 막을게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_010","speaker":"나","text":"저도 끈이 풀린 것밖에는... 더 말씀드릴 게 없어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_011","speaker":"각청","text":"그건 적어 뒀어. 기다리는 동안 새로 본 게 없다면 같은 말을 반복할 필요는 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_evening_012","options":[{"label":"...제가 괜히 끼어들어서 더 늦어진 건 아니죠?","id":"PRO_L02K2_evening_013","items":[{"k":"line","id":"PRO_L02K2_evening_014","speaker":"각청","text":"아니. 덕분에 짐을 더 섞기 전에 멈췄잖아. 뒷일은 내가 맡을게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_015","speaker":"나","text":"...다행이네요. 일만 벌여 놓고 가는 것 같아서.","map":"MAP_LIYUE_PLAINS"}]},{"label":"다음에도 처음부터 설명해야 하나요?","id":"PRO_L02K2_evening_016","items":[{"k":"line","id":"PRO_L02K2_evening_017","speaker":"각청","text":"같은 말은 반복하지 않아도 돼. 더 물을 게 생기면, 어느 부분인지 내가 짚어서 물어볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_018","speaker":"","text":"각청은 병사가 받아 든 표의 아래쪽을 짚어, 이미 확인한 내용을 구분해 주었다.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_evening_019","speaker":"각청","text":"잠깐 자리를 비우실 땐 이 병사에게 말씀해 주세요. 짐은 그대로 두고 다녀오셔도 됩니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_020","speaker":"짐꾼","text":"그 말이면 됐소. 어디까지 자리를 비워도 되는지 몰라서 꼼짝을 못 했지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_021","speaker":"","text":"짐꾼이 굳은 허리를 폈다. 각청은 그가 수레 사이로 나갈 수 있도록 옆으로 비켜섰다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_022","speaker":"나","text":"...이제 좀 살겠네요. 각청 씨도 쉬러 가요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_023","speaker":"각청","text":"다음 교대에 할 말을 전하고. 돌아왔을 때 같은 질문부터 듣게 할 순 없잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_024","speaker":"나","text":"그럼... 고맙습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_025","speaker":"각청","text":"......","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_026","speaker":"각청","text":"인사는 들었으니까, 이제 정말 가서 쉬어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_027","speaker":"","text":"각청은 병사와 함께 접수대로 돌아갔다. 대기 중인 수레의 순서를 짚어 주는 목소리가 잠시 더 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_001","speaker":"","text":"이튿날에는 짐꾼이 자리를 비웠다가 해가 기울기 전에 돌아왔다. 그동안 나는 내가 짐을 맡은 것은 아니라고 병사에게 다시 확인해 두고 한쪽에 앉아 있었다. 짐꾼이 돌아와 가장 먼저 확인한 것은 짐의 수가 아니라 내가 아직 거기 있다는 사실이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_002","speaker":"짐꾼","text":"설마 내가 도망쳤다고 생각한 건 아니겠지? 볼일이 길어져서 늦었소. 기다리다 먼저 갔을 줄 알았는데.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_days_003","options":[{"label":"도망칠 거면 짐부터 두고 간다고 친절하게 말하지는 않았겠죠. 모르는 사람들 틈에 앉느니, 이미 제 형편을 낮게 평가한 사람 옆이 편해서요.","id":"PRO_L02K2_days_004","items":[{"k":"line","id":"PRO_L02K2_days_005","speaker":"짐꾼","text":"높게 평가해 달라는 말로 들리는군. 그렇다고 허리 쓰는 일을 맡기기엔 걸어오는 꼴부터 불안하오. 오늘은 짐을 들어 주겠다는 말은 하지 마시오. 나중에 당신까지 들고 가야 하면 정말 곤란하니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_006","speaker":"","text":"입을 열었다가 닫았다. 실제로 무거운 일을 거들겠다고 할 생각이었으므로, 들킨 기분이 들었다.","map":"MAP_LIYUE_PLAINS"}]},{"label":"무거운 짐은 안 맡을게요. 대신 옆에서 눈으로 확인할 일이 있으면 해 보죠.","id":"PRO_L02K2_days_007","items":[{"k":"line","id":"PRO_L02K2_days_008","speaker":"짐꾼","text":"자기 상태를 알고 말한다면 다행이오. 도와주겠다는 사람까지 눕혀야 하는 일은 피하고 싶으니.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_009","speaker":"나","text":"어제 승강기에서 딸려 올라간 사람한테 그 말은 좀 아프네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_010","speaker":"짐꾼","text":"그러니까 하는 말이오.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_days_011","speaker":"","text":"짐꾼이 앉을 자리를 비워 주었다. 두 사람의 대화는 인계가 어디에서 막혔는지에서 오늘 바람이 어느 쪽으로 부는지로, 다시 어디까지 걸어가면 줄이 덜 붐비는지로 옮겨 갔다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_012","speaker":"","text":"셋째 날, 같은 병사가 익숙한 글씨를 앞에 놓고 한동안 말을 하지 못했다. 자기가 적은 것은 알겠는데 그때 했던 일이 떠오르지 않는다고 했다. 정답을 알려 주듯 끼어들려다 멈췄다. 다른 사람이 알려 준 장면을 따라 말하는 것과 자기 기억을 되찾는 것은 다르다는 걸, 이 자리에서 조금씩 배우고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_013","speaker":"나","text":"생각 안 나면 거기까지만 말해도 돼요. 제가 본 것도 끈 풀린 것뿐이에요. 두 사람이 반쪽씩 안다고 붙여 놓으면 하나의 완벽한 기억이 되는 건 아니잖아요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_014","speaker":"검수 병사","text":"그렇게 말해 주시는 건 고맙습니다. 그런데 제가 모른다고 하면 다른 사람이 또 멈추게 되니까요. 일을 하러 나왔는데, 제가 일의 제일 큰 걸림돌이 된 기분입니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_015","speaker":"짐꾼","text":"당신이 오늘 새로 멈춘 건 아니오. 멈춰야 할 곳을 이제 알게 된 거겠지. 모르는 걸 안다고 해서 안으로 넘겼다가 나중에 사라졌다고 하면, 그땐 셋 다 거짓말쟁이가 되지 않겠소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_016","speaker":"","text":"짐꾼을 보았다. 첫날에는 한시라도 빨리 일을 끝내려고 병사의 대답을 재촉하던 사람이었다. 그는 여전히 기다리는 시간을 아까워했고, 짐의 끈을 볼 때마다 한숨을 쉬었다. 다만 그 시간을 누구에게 화를 내서 되찾을 수 있는지에 대해서는 생각이 달라진 듯했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_017","speaker":"","text":"넷째 날에는 의례가 열리는 날의 동선 안내가 다시 돌았다. 물자를 들여보내는 길과 참관객이 올라가는 길은 다르다는 설명에, 짐꾼은 한동안 먼 곳을 바라보았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_018","speaker":"짐꾼","text":"짐은 병사에게 위치를 확인받고 그대로 둘 거요. 나도 잠깐 올라갔다 오려고. 신 앞에서 이러고 기다리는 사람 있다는 얘기라도 해 볼까 해서. 당신도 갈 거면 같이 가겠소?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_019","speaker":"나","text":"가죠. 제가 대신 사정해 준다고 일이 풀리는 건 아니겠지만, 줄 서 있다가 옆 사람한테 투덜댈 필요는 있잖아요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_020","speaker":"짐꾼","text":"말만 들으면 아주 큰 선행을 하는 것 같군. 올라가는 길에서 힘들다고 먼저 주저앉지만 마시오. 당신은 별것도 없는 짐을 들고 와 놓고 걸핏하면 어깨를 주무르더구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_021","speaker":"","text":"빈정대는 말에 웃었다. 상대가 내일도 나를 같은 사람으로 기억할 것이라고 당연히 믿을 수 있는 대화였다. 그 당연함이 얼마나 드문 일인지, 나는 얼마 뒤에야 알게 된다. 소가 했던 말은 여전히 각청에게 전하지 않은 채였다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_033","text":"닷새가 지난 아침, 두 사람은 짐의 위치가 확인되는 것을 지켜본 뒤 행사 길 쪽으로 향했다. 내가 짐을 인수한 것도, 짐꾼의 일이 끝난 것도 아니었다. 그래서 짐꾼은 돌아왔을 때 어느 자리에서 다시 만나면 되는지까지 정해 두었다."},{"k":"keep","id":"ISK_L02_K2_034","text":"행사 통로가 열려 있었다. 짐꾼은 평소라면 짐을 싣고 향했을 길을 한 번 보고 돌아섰다. 그 길에는 아직 막대와 병사들이 남아 있었다."},{"k":"line","id":"PRO_L02K2_rite_001","speaker":"안내 병사","text":"의례가 끝나면 이 길로 돌아오십시오. 일반 거리는 아직 통제 중입니다. 동행하신 분과 떨어져도 옆길로 찾으러 가시면 안 됩니다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_rite_002","options":[{"label":"이분 잃어버리면 화물 있는 곳에서 찾으면 되겠네요. 그 자리는 잊고 싶어도 못 잊을 것 같아서요.","id":"PRO_L02K2_rite_003","items":[{"k":"line","id":"PRO_L02K2_rite_004","speaker":"짐꾼","text":"잃어버린다니, 내가 당신 짐이오? 나야 먼저 내려가도 내 할 일을 찾아갈 수 있지. 걱정되면 당신이 뒤처지지 말고 잘 따라오시오.","map":"MAP_LIYUE_PLAINS"}]},{"label":"서로 놓치면 화물 있는 쪽에서 다시 만나요. 제가 뒤처지면 한 번만 불러 주세요.","id":"PRO_L02K2_rite_005","items":[{"k":"line","id":"PRO_L02K2_rite_006","speaker":"짐꾼","text":"찾을 곳을 정하는 건 좋소. 다만 부르는 소리가 들릴 만큼은 따라와야겠지.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L02_K2_038","text":"두 사람은 앞서거니 뒤서거니 하며 올라갔다. 며칠 함께 기다렸다고 해서 가까운 친구가 되는 것은 아니었다. 그래도 나는 짐꾼이 사람들 사이에서 한쪽 어깨를 낮추고 걷는 버릇을 알게 되었다. 짐이 없을 때도 몸은 무거운 것을 피해서 지나갈 틈부터 찾았다."},{"k":"line","id":"PRO_L02K2_rite_007","speaker":"","text":"옥경대에서는 시선이 자연스럽게 한곳으로 모였다. 사람들의 기대에 섞여 서면서도 공고의 의례 이름과 내 기억 사이의 어긋남을 생각했다. 이름만 바뀐 것인지, 실제 일이 다른 순서로 일어나는 것인지, 누구에게 물어야 할지도 분명하지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_008","speaker":"짐꾼","text":"고개를 그렇게 내밀면 앞사람과 부딪히오. 보고 싶은 게 있으면 차라리 이쪽에 서시오. 나는 저 위까지 훤히 보이지 않아도 괜찮으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_009","speaker":"나","text":"오늘은 제가 가리는 쪽이네요. 고마워요. 구경 잘하고 내려가면 될 줄 알았는데, 막상 오니까 물어보고 싶은 게 더 많아져서요.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_042","text":"말이 끝나고 얼마 지나지 않아 의례가 시작되었다. 하늘로 향하던 시선 앞에서 거대한 몸이 떨어졌다. 짐꾼이 본능적으로 내 팔을 잡아당겼다. 충격이 발바닥을 타고 올라왔고, 모여 있던 사람들이 뒤로 밀렸다. 먼지가 가라앉는 자리에는 모락스의 시신이 놓여 있었다."},{"k":"line","id":"PRO_L02K2_rite_010","speaker":"","text":"짐꾼이 잡은 팔을 바로 빼지 못했다. 두 사람 모두 시신에서 눈을 떼지 못했다. 기억을 잃은 병사들이 모자라 신마저 죽었다는 말이 가까이에서 튀어나왔다. 누군가는 자리를 뜨려 했고, 누군가는 앞으로 나아가 직접 보려 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_011","speaker":"응광","text":"그 자리에서 서로 밀지 마. 앞을 보겠다고 움직이면 뒤의 사람이 넘어져. 천암군은 통로를 확보하고, 현장을 벗어난 사람의 이야기는 따로 확인해. 지금 들리는 말들을 그대로 옮기지 마라.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_012","speaker":"","text":"각청이 통로 가장자리로 와서 사람들을 물렸다. 짐꾼은 앞에 넘어진 사람을 일으켜 주었고, 나도 손을 뻗어 설 자리를 만들었다. 잠깐 생긴 틈 사이로 응광이 보였다. 나는 알고 있었다. 이 뒤에 무엇이 오는지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_013","speaker":"나","text":"각청, 저 응광하고 따로 이야기해야겠어요. 지금 본 것 말고도 전할 게 있어요. 여기서 소리 내면 더 혼란스러워질 테니까, 잠깐만 따로 만나게 해 줘요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_014","speaker":"각청","text":"지금 개인 면담은 안 돼. 네가 물자 일에 협조해 준 건 알아. 하지만 그 일로 의례 현장까지 자유롭게 다닐 수 있는 건 아니야. 급한 내용이면 내가 들을게. 저쪽으로 밀고 나가지는 마.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K2_rite_015","options":[{"label":"그 자격을 써먹겠다는 게 아니에요. 다른 사람이 아직 모르는 일이 있어서 그래요. 제군에 관한 일이고, 그 다음에 벌어질 일에 관한 얘기예요.","id":"PRO_L02K2_rite_016","items":[{"k":"line","id":"PRO_L02K2_rite_017","speaker":"각청","text":"그렇다면 더더욱 네가 어떻게 아는지부터 들어야겠지. 다음 일을 안다는 말만으로 현장 책임자를 데려올 수는 없어. 조금 전 네 옆에서 넘어진 사람부터 길을 비켜 줘. 설명은 그 뒤에도 들을 수 있어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 최소한 제 얘기가 있다는 건 전해 줘요. 출처를 지금 설명하려면 오래 걸려요.","id":"PRO_L02K2_rite_018","items":[{"k":"line","id":"PRO_L02K2_rite_019","speaker":"각청","text":"전할 내용이 있다는 건 알겠어. 하지만 출처를 설명하기 어렵다는 말이 출처 확인을 생략해도 된다는 뜻은 아니야. 네가 본 일부터 듣고, 나머지는 나눠서 이야기하자.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L02K2_rite_020","speaker":"","text":"다시 고개를 돌렸을 때 응광은 현장을 떠나고 있었다. 옷자락이 보였다가 다른 통로 너머로 사라졌다. 각청의 거절에는 이유가 있었다. 그 이유를 이해한다고 해서 사라지는 초조함도 아니었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_021","speaker":"짐꾼","text":"아는 게 있으면 지금 이분한테 먼저 말하시오. 사람을 가려 가며 할 때가 아닌 것 같은데. 당신은 본 것과 안 본 것을 잘 나누더니, 오늘은 말 앞에서 자꾸 머뭇거리는군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_022","speaker":"나","text":"……맞아요. 이상하게 들릴까 봐 순서를 찾고 있었어요. 각청, 조금만 들어 줘요. 이건 제가 전에—","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_001","speaker":"","text":"짐꾼의 손이 내 팔에서 떨어졌다. 한 발을 헛디딘 것처럼 보여 반사적으로 옷깃을 잡았다. 각청도 동시에 무릎이 꺾였다. 옆에 서 있던 병사가 창을 놓쳤고, 군중의 소리가 중간에서 뚝 끊겼다. 서로 떨어져 있던 사람들까지 아무 힘 없이 무너졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_002","speaker":"","text":"짐꾼을 끌어안은 채 바닥에 주저앉았다. 가벼울 거라던 몸이 갑자기 움직일 수 없는 무게가 되었다. 어깨를 흔들고 이름 대신 아는 호칭을 불렀다. 닷새를 같이 있었는데도 이름보다 먼저 짐꾼이라는 말이 떠올랐다는 사실이 뒤늦게 나를 찔렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_003","speaker":"나","text":"일어나요. 조금 전까지 나한테 할 말 하라고 했잖아요. 알았으니까, 내가 말할 테니까 들어 줘요. 이렇게 누워 있으면 다시 일하러 가야 한다고 투덜댈 사람도 없잖아요.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_062","text":"몸을 돌려 각청에게 손을 뻗었다. 도움을 요청하려고 이름을 부르다가 그녀도 같은 상태라는 것을 깨달았다. 손목에도, 목 가까이에도 뛰는 것이 없었다. 짐꾼도 병사도 같았다. 아무리 가까운 사람을 바꿔 확인해도 답은 달라지지 않았다. 현장의 사람들은 모두 죽었다. 그 가운데 나만 살아 있었다."},{"k":"line","id":"PRO_L02K2_death_004","speaker":"","text":"짐꾼의 몸을 다시 당겼다. 내려가는 길까지 끌고 갈 수 있을지 가늠하려 했지만, 몸을 조금 옮기는 것만으로 손이 미끄러졌다. 가까운 병사에게 도와 달라고 말하려 고개를 들었다가 그 말마저 삼켰다. 바로 앞에 사람들이 가득한데, 도움을 청할 상대는 하나도 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_005","speaker":"나","text":"왜 아무도… 아까 다들 살아 있었잖아. 나한테 말을 했잖아요. 누가 좀, 제발 누가 오라고 해 줘요. 여기에 혼자 두지 말아요.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_065","text":"짐꾼을 바닥에 눕히고 한 발 뒤로 물러났다. 다시 들면 될 것 같아서 손을 뻗었지만, 닿기 전에 팔이 굳었다. 시신이 무서운 것인지 다음 순간 내게 무슨 일이 생길지가 무서운 것인지 구분할 수 없었다. 계단이 있는 쪽으로 몸을 돌렸을 때 비명이 터졌다."},{"k":"line","id":"PRO_L02K2_death_006","speaker":"","text":"아래로 내려가는 길에서 몇 번이나 돌아서려 했다. 물건을 두고 온 것처럼, 돌아가면 해야 할 일이 있을 것 같았다. 그러나 돌아갈 곳에 무엇이 있는지 떠올릴 때마다 다리가 먼저 달렸다. 닷새 동안 직접 본 것만 말하겠다고 고집하던 내가, 지금은 눈으로 확인한 장면에서 한 걸음이라도 더 멀어지려 하고 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_067","text":"행사 통로 밖으로 빠져나온 뒤에도 길을 고를 여유가 없었다. 내 발소리가 겹쳐 들릴 때마다 누가 따라오는 줄 알았다. 물자 구역으로 향하던 발은 중간에 멈췄다. 그곳에 가면 짐꾼이 돌아올 자리가 보일 것이었다."},{"k":"line","id":"PRO_L02K2_death_007","speaker":"","text":"길가에 엎드리듯 앉았다. 내가 아직 짐꾼의 소매를 쥐고 있는 줄 알고 손을 폈다. 아무것도 없었다. 살아 나왔다는 말에 붙일 수 있는 증거가 내 기억뿐이라는 사실은, 기억 때문에 봉쇄된 도시 앞에서 특히 막막했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_008","speaker":"나","text":"……내가 본 건 내가 말해야지. 저 사람들은 이제 자기 일을 말할 수 없잖아. 그러니까 사람 있는 데로 가야 해. 이번에는 무슨 말을 해야 할지 고민하다가 또 놓치지 말자.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_009","speaker":"","text":"말을 알아들어 줄 사람을 생각하자 선인들이 떠올랐다. 소도 있었지만, 지금 그를 어디에서 만날 수 있을지는 몰랐다. 원작에서 알던 이름들 가운데 정해진 거처와 산의 모습을 가장 선명하게 기억하는 이를 붙들었다. 류운차풍진군이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_001","speaker":"","text":"머릿속에서는 간단했다. 절운간 쪽으로 가서 오장산에 오르고, 거처를 찾아 소식을 전한다. 실제로는 어느 길이 산을 돌아 올라가고 어느 길이 절벽 아래에서 끊기는지부터 알아내야 했다. 처음 택한 오르막은 능선에 닿지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_002","speaker":"나","text":"길을 안다고 한 적은 없지. 있는 장소를 안다고만 했지. ……여기까지 왔는데 산한테 면담 거절당하고 끝낼 수는 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_073","text":"산으로 들어가는 길을 다시 골랐다. 짐꾼이 무거운 것을 든 몸으로 사람 사이의 틈을 찾던 모습이 떠올랐다. 곧장 가는 길이 항상 몸을 가장 적게 쓰는 길은 아니라는 것을, 그의 걸음에서 조금 배웠던 것 같다. 손을 써서 올라야 하는 바위 앞에서 억지로 오르지 않고 경사가 풀리는 쪽을 찾았다."},{"k":"line","id":"PRO_L02K2_mountain_003","speaker":"","text":"높이 오를수록 사람 소리가 멀어졌다. 이렇게 멀리 왔는데도 조금 전 의례장의 소리를 떠올릴 수 있다는 것이 이상했다. 머릿속에서 짐꾼은 여전히 나에게 본 것과 안 본 것을 나누라고 말하고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_004","speaker":"","text":"거처 앞에 도착했을 때 문을 향해 곧장 걸어갔다가 제자리로 돌아왔다. 숨이 거칠어 첫마디를 끝내지 못할 것 같았다. 급한 일이다, 제군의 몸이 떨어졌다, 사람들이 죽었다. 이 셋을 말하기 전에 길을 잘못 들었느냐는 질문을 받고 싶지는 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_005","speaker":"나","text":"류운차풍진군, 리월항에서 왔습니다. 제군의 시신이 떨어진 것을 봤고, 그 뒤 현장에 있던 사람들이 죽었습니다. 저는 살아 나왔어요. 문을 여실 수 없으면 여기서라도 듣고 계신지만 알려 주십시오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_006","speaker":"","text":"대답이 없었다. 다시 부르고 싶은 마음을 누르며 문 옆으로 비켜섰다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_mountain_007","options":[{"label":"제가 모르는 절차가 있으면 말씀해 주세요. 음식을 갖추라고 하셔도 지금은 가져온 게 없습니다. 가지고 온 척할 수는 없잖아요.","id":"PRO_L02K2_mountain_008","items":[{"k":"line","id":"PRO_L02K2_mountain_009","speaker":"류운차풍진군","text":"갖추지 못한 예물을 핑계로 들어 달라고 하는 것인지, 들은 뒤에 예물을 요구하지 말라는 것인지. 인간의 말은 참으로 돌아가는 길이 많군. 이 몸의 문전까지 왔다면 먼저 이름을 밝히고 용건을 말하는 것이 순서지.","map":"MAP_LIYUE_PLAINS"}]},{"label":"급한 소식을 전하러 왔지만, 문 앞에서 지켜야 할 예절까지 안다고 할 수는 없습니다. 이름과 용건부터 말씀드려도 될까요?","id":"PRO_L02K2_mountain_010","items":[{"k":"line","id":"PRO_L02K2_mountain_011","speaker":"류운차풍진군","text":"모르는 순서를 묻는 것은 허물이 아니지. 다만 급하다는 말로 다른 설명을 덮지는 말게. 이름을 밝히고 용건을 말하게.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_mountain_012","speaker":"나","text":"(자신의 이름을 밝힌다.) 몬드에서 왔습니다. 리월항 밖에서 기다리다가 오늘 의례를 보러 올라갔고요. 이름을 들어도 아시는 사람은 아닐 거예요. 그래도 제 이름을 걸고 말씀드리겠습니다. 제가 본 일을 다른 사람에게 떠넘길 수는 없으니까요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_013","speaker":"류운차풍진군","text":"의례를 보러 간 사람이 제군의 시신을 보고 돌아왔다. 그 뒤 사람들이 죽었다는 말은, 모두가 흩어져 보이지 않았다는 뜻이 아니겠지? 자네가 직접 본 일과 남에게 들은 일을 뒤섞지 않도록 하게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_014","speaker":"나","text":"사람들이 없어진 게 아니에요. 제 앞에 남아 있었어요. 같이 올라간 사람을 잡고 있었는데 몸에서 힘이 빠졌고, 제가 불러도 대답하지 않았습니다. 각청도 바로 거기서 죽었어요. 제가 정말 본 것을 말하고 있습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_015","speaker":"","text":"문이 열렸다. 학의 눈이 내 차림보다 얼굴에 오래 머물렀다. 게임에서 알던 선인을 만났다는 감탄은 나중 일이었다. 지금은 마침내 내 증언이 살아 있는 상대에게 도착했다는 사실이 먼저였다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_016","speaker":"류운차풍진군","text":"발부터 들이밀 생각은 접고 잠깐 서 있게. 바닥의 높이가 달라 몸이 앞으로 쏠릴 것이야. 들으려 문을 열었으니, 넘어지며 서두를 필요는 없네.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_017","speaker":"나","text":"알겠습니다. 제가 아무 데서나 넘어지는 사람이 된 건 오늘만 그런 겁니다. 손님이 들어오자마자 쓰러지면 서로 곤란하겠죠.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_audience_001","speaker":"","text":"말한 것만큼 조심해서 들어갔다. 마지막 말끝에서 목소리가 갈라졌다. 류운차풍진군은 웃음거리로 삼지 않고 나를 앉혔다. 문밖에서 정리한 순서는 앉는 순간 다시 흐트러졌고, 나는 손등을 내려다보며 첫 질문을 기다렸다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_002","speaker":"류운차풍진군","text":"함께 올라갔다는 이는 자네의 오랜 벗인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_003","speaker":"나","text":"아니요. 닷새 정도 같이 기다린 사람이에요. 화물이 막혀서 못 들어가는 짐꾼이었고… 망서 객잔 승강기에서 떨어질 뻔한 걸 같이 끌어올린 사람이기도 해요. 이름도 못 물어봤어요. 그런데 오늘 의례는 같이 보러 갔습니다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_004","speaker":"류운차풍진군","text":"그 사람이 죽은 뒤 자네는 무엇을 했나. 이 몸에게 잘 보일 일을 골라 말하라는 뜻이 아니야. 어떤 상태를 확인했는지 알아야 하네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_005","speaker":"나","text":"깨우려고 했고, 끌고 가려고 했어요. 혼자서는 잘 안 됐습니다. 각청한테 도와 달라고 하려다가 그 사람도 죽었다는 걸 확인했어요. 숨도 맥박도 없었습니다. 다른 사람들도 같았어요. 그러고는… 놔두고 도망쳤습니다. 누굴 업고 왔다고 말하면 좋겠지만 못 했어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_006","speaker":"","text":"마지막 대답을 할 때 나는 고개를 들었다. 짐꾼에게 본 것만 말하겠다고 했던 사람이, 그를 두고 나온 장면만 다른 모양으로 바꿀 수는 없었다. 류운차풍진군은 내가 말을 마친 뒤에도 잠깐 기다렸다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_007","speaker":"류운차풍진군","text":"구할 수 있었는데 하지 않았다는 것과, 구하려 했으나 손이 닿지 않았다는 것은 다르지. 이 몸이 그 자리에 없었으니 어느 쪽이라고 대신 판정하지는 않겠네. 다만 그 사람을 업고 오지 못했다고 해서 지금 가져온 소식까지 버릴 이유는 없네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_008","speaker":"","text":"그분이 여기 있었다면 내 말이 길다고 했을 것이다. 자꾸 아는 게 있다고만 하지 말고 그냥 말하라고. 그래서 이번에는 먼저 말했다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K2_audience_009","options":[{"label":"모락스의 계략입니다. 자신의 죽음을 계기로 리월이 스스로 위기를 넘기는지 보려는 거예요. 오셀이 나올 수 있으니, 막을 준비를 하셔야 합니다.","keep":"ISK_L02_K2_094","items":[]}]},{"k":"line","id":"PRO_L02K2_audience_010","speaker":"류운차풍진군","text":"자네가 방금 붙인 이름이 얼마나 무거운지 알고 하는 말인가. 사람의 죽음을 전한 입으로 제군의 뜻까지 단언했군. 누구에게 들었는가? 그 말을 전한 사람이 오늘 그곳에 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_011","speaker":"나","text":"이곳 사람한테 들은 이야기가 아닙니다. 제가 살던 곳에서, 이곳의 일을 이야기처럼 알고 있었어요. 제가 여기 왔다는 사실부터 설명이 안 된다는 건 알아요. 그런데 오셀 이름을 아는 이유도, 당신을 찾아올 생각을 한 이유도 그겁니다. 거짓말을 덧대서 더 그럴듯한 출처를 만들 수는 없어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_012","speaker":"","text":"류운차풍진군은 날개를 접은 채 나를 바라보았다. 대답을 돌려받지 못하자 내가 믿고 있던 이야기의 바닥이 얇아 보였다. 그것이 맞는 이야기라면 내가 떠나온 현장은 대체 무엇이란 말인가.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_013","speaker":"류운차풍진군","text":"자네가 알고 있었다는 이야기에는 오늘 함께 갔던 이의 죽음도 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_014","speaker":"나","text":"없었어요. 천암군이 기억을 잃는 일도, 제 눈앞에서 모두가 죽는 일도요. 드발린이 정말 죽었다가 살아나는 일도 없었습니다. 그러니까 계략이라는 건 제가 아는 원래 이야기의 설명이고, 오늘 이 죽음의 이유까지 안다는 뜻은 아니에요. ……말을 너무 한꺼번에 했네요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_015","speaker":"류운차풍진군","text":"한꺼번에 말한 것만이 문제는 아니네. 아는 이야기가 있으니 모르는 일이 벌어져도 그 안에 들어갈 것이라고 기대하고 있지 않은가. 이미 자네는 그 이야기에 없던 죽음을 두 번 보았다고 했네. 그런데도 그중 더 오래 알고 있던 쪽에 모든 판단을 맡길 셈인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_016","speaker":"","text":"반박할 이유는 많아 보였다. 미리 알던 이름들이 실제로 존재한다는 것, 여기까지 오는 데 그 지식이 도움이 되었다는 것. 그러나 어느 반박도 짐꾼을 다시 일으켜 세우지는 못했다. 무릎 위에 놓았던 손을 풀었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K2_audience_017","options":[{"label":"그래도 경고는 하겠습니다. 미래를 다 안다는 말은 거둘게요. 오셀에 대비해 달라는 말은 거두지 않겠습니다.","id":"PRO_L02K2_audience_018","items":[{"k":"line","id":"PRO_L02K2_audience_019","speaker":"류운차풍진군","text":"그 두 말을 구분할 수 있다면 이 몸도 다르게 듣겠네. 자네의 확신을 증거로 삼지는 않겠으나, 구체적인 위협을 경계할 이유로는 검토할 수 있지.","map":"MAP_LIYUE_MOUNTAINS"}]},{"label":"제가 안다고 생각했던 부분에 매달린 건 맞아요. 아무것도 모르겠다고 인정하면 도망갈 곳도 없어질 것 같았거든요. 그래도 직접 확인하러 가 주시면 안 될까요?","id":"PRO_L02K2_audience_020","items":[{"k":"line","id":"PRO_L02K2_audience_021","speaker":"류운차풍진군","text":"확인할 필요는 충분히 들었네. 자네를 달래기 위해 나서는 것이 아니라 리월에 일어난 일을 살피러 가는 것이야. 그 차이가 서운하더라도 받아들이게.","map":"MAP_LIYUE_MOUNTAINS"}]}]},{"k":"line","id":"PRO_L02K2_audience_022","speaker":"","text":"아직 말하지 않은 것이 남아 있었다. 망서 객잔에서 소에게 들었던 말. 각청에게는 물자 일에 대한 증언만 남겼다. 그때는 내 이야기를 더 보태면 이미 혼란스러운 일이 꼬일 것 같았다. 지금 와서 그 판단이 참사를 막을 기회를 놓친 것인지 따져도 답은 나오지 않았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_023","speaker":"나","text":"한 가지 더 있어요. 소를 만났을 때 제 주변에 죽음과 생명의 냄새가 같이 난다고 했습니다. 마신에 대한 강한 혐오도 느껴진다고요. 저는 그런 마음이 없다고 했고, 그분도 그게 누구 건지까지 말하지는 않았습니다. 각청에게는… 아직 전하지 못했어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_024","speaker":"류운차풍진군","text":"소에게서 직접 들었다는 말이지. 그 말을 듣고 난 뒤 자네에게 달라진 점이 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_025","speaker":"나","text":"딱 잘라 말할 변화는 없어요. 오늘 일을 전부 그 말에 붙이면 설명한 것 같을 텐데, 그렇게 할 근거는 없잖아요. 제가 가까이 있어서 죽었다는 걸 본 것도 아니고요. 그냥 저만 남았습니다. 그게 지금 제일 무섭습니다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_026","speaker":"류운차풍진군","text":"이 몸은 소가 전한 말을 가볍게 여기지 않네. 그렇다고 들은 말 하나로 지금의 모든 죽음에 주인을 정해 주지도 않을 것이야. 자네가 모르는 것을 견디지 못해 아무 답이나 붙잡는다면, 다음에 보는 것도 그 답에 맞춰 바꾸게 되겠지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_027","speaker":"나","text":"닷새 동안 남한테는 모르면 모른다고 해도 된다고 해 놓고, 정작 제가 모르겠다는 건 이렇게 못 견디네요. 말로 남을 도와주는 건 참 편했어요. 제가 그 자리에 서기 전까지는요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_028","speaker":"류운차풍진군","text":"누군가에게 해 준 말이 이제 자네에게도 필요한 때가 온 것이겠지. 그 말이 거짓이 되는 건 아니네. 허나 자네를 위로하는 일만 하고 있을 수는 없어. 이 몸은 항구 쪽 사정을 살피겠네. 제군의 일에 관한 말도, 바다의 위험을 경계하라는 말도 들었으니 확인할 것을 확인하겠어.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_029","speaker":"","text":"그녀는 자신이 무엇을 이미 알고 있는지 풀어놓지 않았다. 대신 지금 들은 이야기에서 무엇을 확인할지 스스로 정했다. 원작의 장면을 맞혀 보이는 손님이 아니라, 실제 현장에서 소식을 가져온 사람으로 대우받고 있다는 것을 느꼈다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_030","speaker":"나","text":"저도 내려가겠습니다. 그분 짐이 있던 곳으로요. 집이 어디인지, 기다리는 사람이 누군지는 모르지만… 무슨 일이 있었는지 물을 사람이 있으면 제가 대답해야죠. 아까는 너무 무서워서 아무것도 못 했어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_031","speaker":"류운차풍진군","text":"지금 내려가겠다고 벌떡 일어나지는 말게. 산길은 자네가 후회하는 만큼 짧아지는 것이 아니야. 빛이 남은 구간만 움직이게. 사람을 대신해 소식을 전하려거든 소식을 가진 몸부터 무사히 데려가야 하네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_032","speaker":"나","text":"들을수록 제가 되게 관리가 안 된 짐짝 같네요. 그래도 내려가는 길에서는 떨어뜨리지 않도록 해 보겠습니다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_033","speaker":"류운차풍진군","text":"떨어뜨리지 않도록 해 보겠다는 말은 장담이 아니니 마음에 드는군. 다만 이 몸의 충고를 전부 짐짝에 빗대어야 알아듣는 버릇은 고치는 편이 좋겠네. 앉아 있을 수 있을 때는 더 앉아 있게.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_return_001","speaker":"","text":"조금 더 앉아 있었다. 무언가를 해야 한다는 마음과 몸이 움직일 수 있다는 사실을 처음으로 따로 생각했다. 나를 재촉할 짐꾼은 없었다. 그 빈자리를 당장 메우지 못해도, 살아서 돌아가 본 일을 말하는 것까지 포기할 필요는 없었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"keep","id":"ISK_L02_K2_123","text":"해가 진 뒤에는 길을 확인할 수 없는 비탈을 포기하고 바위 아래에 머물렀다. 눈을 감으면 짐꾼의 몸을 놓는 순간이 떠올랐다. 몇 번을 다시 보아도 다음 장면은 달라지지 않았다. 다시 밝아진 뒤에야 외곽으로 발걸음을 이었다."},{"k":"line","id":"PRO_L02K2_return_002","speaker":"","text":"항구로 향하는 길에서 먼 곳의 수레를 먼저 보았다. 사람이 끌고 있었다. 살아 있는 사람이 일하고 있었다. 이것을 다행이라고 생각하는 순간, 두고 온 사람들만 다시 떠올리는 것이 미안해졌다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_125","text":"도시는 여전히 통제되어 있었다. 물자를 기다리는 사람들이 병사 앞에서 설명하고 있었고, 병사는 길을 나누어 안내했다. 그 가운데 익숙한 옷차림을 보았다. 각청이었다. 그녀가 걸음을 옮기자 주변 사람들이 자연스럽게 길을 비켜 주었다."},{"k":"line","id":"PRO_L02K2_return_003","speaker":"","text":"사람을 잘못 보았다고 생각하려 했다. 그러나 눈앞의 각청은 자기 이름을 부르는 사람에게 돌아보았고, 질문을 끝낸 사람에게 필요한 대답을 했다. 살아 있었다. 의례장에서 확인한 손목의 침묵과 이곳에서 움직이는 손이 한 사람의 것이었다. 그 사이에 들어갈 설명을 나는 하나도 가지고 있지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_return_004","speaker":"나","text":"각청, 너 어떻게 살아 있어? 나야. 포대 끈이 풀린 걸 봤다고 했던 사람. 의례에서 응광하고 이야기하게 해 달라고 했잖아. 네가 안 된다고 했고, 그 뒤에… 너도 죽었는데. 내가 확인했는데.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_128","text":"각청은 즉시 대답하지 않았다. 그녀가 잠깐 멈춘 것을 나는 알아보았다는 신호로 받아들이려 했다. 그러나 다음 시선은 알고 있는 사람의 말을 기다리는 시선이 아니었다. 혼란스러운 말을 늘어놓는 낯선 사람이 자신을 어디에서 보았을지 살피는 눈이었다."},{"k":"line","id":"PRO_L02K2_return_005","speaker":"각청","text":"내가 죽었다고? 진정하고 처음부터 말해 봐. 그 전에 확인할 게 있어. 너는 누구지? 나를 알고 있어?","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_END","text":"리월항 외곽 봉쇄선. 이야기는 살아 있는 각청의 질문 앞에서 멈춘다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L02_K2_001_0","text":"짐꾼은 같은 일을 두 번 했다는 확인 때문에 품삯을 받지 못했다. 그런데 행추가 들고 온 인계표를 보니, 그가 옮긴 자루에는 서로 다른 두 항구의 번호가 붙어 있었다."},{"k":"text","id":"V141_BEFORE_ISK_L02_K2_001_6","text":"둘이 밥 맡으면 나는 짐표 맡을게. 아저씨, 다녀와서 또 세라고 하면 그땐 제가 화낼 거예요."},{"k":"text","id":"V141_AFTER_ISK_L02_K2_001_2","text":"고마워. 이건 내가 전할게. 행추, 나중에 저 아저씨를 못 찾게 되면… 이번에는 짐 말고 사람부터 찾아 줘."}]},{"id":"ISK_L03_K1","entry":"ISK_L03_K1_001","items":[{"k":"keep","id":"ISK_L03_K1_001","text":"각청이 누구냐고 묻자 나는 대답 대신 그녀의 손목을 보았다. 살아 있다는 사실은 눈앞에 있는데도 손끝으로 다시 확인해야 할 것 같았다. 각청은 그 시선을 따라 자신의 팔을 한 번 보더니, 뒤에서 다가오던 병사에게 기다리라고 손짓했다. 익숙한 동작이었다. 내가 아는 각청은 그렇게 다른 사람의 말을 들을 자리를 만들어 주곤 했다."},{"k":"line","id":"PRO_L03K1_stranger_001","speaker":"나","text":"알아. 닷새 동안 저쪽 천막에서 같이 있었어. 내가 자꾸 맥박을 재니까 네가 내 몸에 결론부터 붙이지 말라고 했고, 비 오던 날에는 둘이 천막 물도 뺐어. 세게 당기니까 천 찢어진다고 잔소리했잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_002","speaker":"각청","text":"……그 천막이 어딘지는 알아. 그런데 네가 말한 일은 기억나지 않아. 내가 너를 조사했다면 담당 병사도 있었겠지. 그 사람부터 찾아보자. 손을 다쳤는데, 그건 언제 생긴 상처야?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_003","speaker":"","text":"손바닥을 뒤집었다. 산을 오르다 긁힌 자국과 말라붙은 흙. 그녀를 붙들던 손이었고, 놓고 도망쳤던 손이었다. 각청은 손을 잡아 검사하지 않았다. 대신 병사에게 씻을 물이 있는 곳을 묻고, 나에게 길옆의 낮은 자리를 가리켰다. 그 배려마저 익숙해서 나는 앉을 수 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_004","speaker":"나","text":"상처는 나중에. 의례에서 무슨 일이 있었는지부터 말해 줘. 모락스의 시신이 떨어졌잖아. 네가 사람들 물리고 응광이 지시하던 거, 설마 그것도 기억 안 나?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_005","speaker":"각청","text":"제군의 시신이라고? 의례에 다녀온 건 기억해. 하지만 그런 일이 있었다면 지금 이 봉쇄선에 서서 물자 통행을 정리하고 있을 리 없잖아. 천천히 말해. 네가 무엇을 봤는지부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_006","speaker":"","text":"뒤의 병사도 고개를 들었다. 그는 그날 안내를 맡았다고 했지만 하늘에서 떨어진 거대한 몸은 기억하지 못했다. 다른 참관객을 불러도 답은 다르지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_007","speaker":"참관객","text":"사람이 많아서 앞은 잘 보이지 않았어요. 그렇지만 그런 일이 났으면 소리라도 들었겠죠. 저는 그냥… 잠깐 정신이 없었던 것 같은데, 그게 무슨 일이었는지는 모르겠네요. 왜 그런 표정으로 보세요? 제가 숨기는 건 없어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_008","speaker":"나","text":"숨겼다고 안 했어요. 탓하는 게 아니에요. 그런데 다들 그 부분만 없다고 하니까, 나는 대체 어디에다 대고 말해야 하나 싶어서.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K1_stranger_009","options":[{"label":"나를 못 믿어도 좋아. 대신 내가 가리키는 자리까지 같이 가 줘. 없는 일을 우겼다면 돌아오는 길에 나한테 화내도 되잖아.","id":"PRO_L03K1_stranger_010","items":[{"k":"line","id":"PRO_L03K1_stranger_011","speaker":"각청","text":"없는 일인지 판단하려고 가는 거야. 먼저 화낼 이유를 만들 생각은 없어. 다만 혼자 통제선을 넘으면 네가 말하는 자리에 가기도 전에 붙잡혀. 내 옆에서 움직여.","map":"MAP_LIYUE_PLAINS"}]},{"label":"네가 나를 기억 못 하는 건 억지로 받아들여 볼게. 그래도 의례 현장까지 없어지진 않았잖아. 거기서부터 보자.","id":"PRO_L03K1_stranger_012","items":[{"k":"line","id":"PRO_L03K1_stranger_013","speaker":"각청","text":"현장을 다시 확인하자는 데는 동의해. 네가 말한 담당자도 그쪽에서 찾아볼 수 있어. 걷는 동안 물은 마셔. 목소리만 높여서는 네 다리가 더 버티지 못해.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L03_K1_016","text":"각청은 신뢰한다는 선언 대신 길을 열었다. 그 뒤를 따르다 천막 끝을 보았다. 비를 빼던 날 접어 둔 천이 여전히 같은 방향으로 말려 있었다. 사소한 흔적은 남았는데 사람을 알아보던 눈길만 사라져 있었다."},{"k":"keep","id":"ISK_L03_K1_017","text":"두 사람은 행사 때 이용했던 계단을 다시 올랐다. 각청이 앞서가다 돌아볼 때마다 그녀가 쓰러졌던 순간이 지금의 몸에 겹쳤다. 계단 중간에서 한 번 멈춰 숨을 골랐고, 각청은 재촉하는 대신 사람들이 돌아갈 쪽을 바꾸었다."},{"k":"line","id":"PRO_L03K1_empty_001","speaker":"","text":"사람이 쓰러졌던 곳을 먼저 보았다. 바닥에는 제례에 사용한 물건이 정리되어 있었고, 통행을 막는 줄이 한쪽으로 걷혀 있었다. 각청을 받쳤던 자리를 찾아 멈췄다가, 시선을 더 안으로 옮겼다. 가장 큰 것이 없었다. 모락스의 시신이 사라져 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_002","speaker":"나","text":"여기 있었잖아. 저기서 떨어져서 이쪽으로 몸이 놓였어. 사람들을 물릴 때 네가 이 앞에 섰고. 저만한 몸을 어디로 옮긴 거야?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_003","speaker":"현장 병사","text":"저희가 넘겨받을 때는 그런 시신이 없었습니다. 큰 물건을 옮겼다는 인계도 없고요. 응광 님께도 전달했습니다만, 제군께 그런 일이 있었다는 기억이 없다고 답하셨습니다. 직접 보낸 전갈입니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_004","speaker":"","text":"응광까지 기억하지 못했다. 그 거대한 몸을 앞에 두고 냉정하게 사람을 움직이던 여자가, 이제는 시신을 옮기라고 했는지조차 말해 줄 수 없었다. 사라진 자리를 둘러싼 사람들은 모두 살아 움직이고 있었지만 누구도 그 자리에 무엇이 놓였는지 기억하지 못했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_005","speaker":"나","text":"그럼 끝이야? 기억이 없고 넘겨받은 것도 없으니까 원래 없었던 걸로 치자고? 저게 주머니에 넣고 갈 물건이야? 사람이 죽고, 너도 죽고, 지금은 시신까지 없어졌는데 왜 나만 그걸 찾고 있냐고!","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_006","speaker":"","text":"마지막 말은 각청을 향해 튀어나왔다. 소리를 지른 뒤에야 그녀가 한 발도 피하지 않았다는 것을 보았다. 병사가 말리려고 팔을 내밀자 각청이 그 앞을 막았고, 나는 더 화를 낼 대상을 잃었다. 살아 돌아온 사람에게 왜 죽었느냐고 따지고 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_007","speaker":"각청","text":"네 말이 맞다면 내가 모르는 사이에 죽었다가 지금 여기 서 있는 거겠지. 그걸 네게 설명해 주지 못하는 건 사실이야. 하지만 내 기억이 비어 있다는 이유로 나까지 아무것도 하려 하지 않는 사람으로 만들지는 마. 지금 네 옆에 서 있잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_008","speaker":"나","text":"……알아. 머리로는 아는데, 네가 너무 멀쩡해서 화가 나. 살아 있어서 다행인데, 살아 있는 네 앞에서 죽었다고 소리치는 내가 미친 것 같고. 미안해. 그래도 시신은 찾아야 해. 아무도 기억 못 하면 가져간 사람은 너무 편하잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_009","speaker":"각청","text":"그 말부터 같이 확인하자. 시신이 없어졌다면 옮긴 길이 있을 수 있어. 기억이 없다고 길까지 없어지는 건 아니니까. 넌 네가 있던 자리를 짚어 줘. 나는 옮길 수 있는 출구와 그쪽에 있던 사람을 찾을게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_010","speaker":"","text":"각청은 곧장 병사 둘을 나누어 보냈다. 큰 몸을 숨길 수 있는 장소, 제군의 힘을 노리고 접근할 사람, 다른 이들이 혼란한 동안 먼저 움직였을 자. 이름 하나가 머릿속을 차갑게 가로질렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_011","speaker":"나","text":"타르탈리아. 우인단 집행관, 그 사람이 리월에 와 있지? 황금옥부터 확인해야 해.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_012","speaker":"각청","text":"그 이름은 알아. 하지만 네가 지금 어떤 관계로 연결한 건지는 모르겠어. 그가 가져갔다는 목격이 있어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_013","speaker":"나","text":"본 건 아니야. 내가 알고 있던 이야기에서는 그가 황금옥으로 가고, 제군의 신의 심장을 얻으려 해. 거기서 뜻대로 안 되면 일이 바다까지 번져. 지금까지 겪은 일을 전부 그 사람 짓이라고 하려는 게 아니야. 더 큰 사고가 날 곳을 하나 알고 있다는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_031","text":"각청은 황금옥이라는 말에서 옆에 있던 병사를 불렀다. 그때 계단 쪽에서 숨이 찬 목소리가 올라왔다. 감우와 연비였다. 두 사람은 의례장에 없었다. 그러니 기억도 그대로였다."},{"k":"line","id":"PRO_L03K1_adepti_001","speaker":"","text":"그때 돌바닥 위로 긴 그림자가 드리웠다. 바람이 제례용 천을 뒤집었고, 병사들의 시선이 한꺼번에 하늘로 올라갔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_002","speaker":"류운차풍진군","text":"이 몸이 항구의 사정을 살피겠다고 한 것이 그저 자네를 돌려보내려는 말로 들렸나? 돌아오자마자 목이 쉬도록 외쳐 대고 있으니 산에서 쉬게 한 보람이 없군. 자네가 말한 각청이 바로 이 사람인가?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_003","speaker":"","text":"류운차풍진군이 내려앉는 동안 먼 지붕 위로 또 다른 선인의 형체가 멈췄다. 홀로 찾아온 것이 아니었다. 내가 밤을 넘겨 산을 내려오는 동안 그녀는 다른 선인들에게 경고를 전하고 항구로 향한 것이다. 소는 소란의 가운데로 들어오지 않은 채 각청과 나 사이에 시선을 멈췄다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_004","speaker":"나","text":"맞아요. 분명 제 앞에서 죽었는데 지금은 살아 있어요. 모락스의 시신도 없어졌고, 각청도 응광도 그 일이 기억나지 않는답니다. 제가 거짓말한 거라고 생각하실까 봐… 아니, 지금 그걸 걱정할 때가 아니네요. 타르탈리아가 황금옥으로 갔을 수 있어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_005","speaker":"류운차풍진군","text":"산에서 들은 말을 이 몸이 잊지 않았네. 자네가 지금 눈앞의 사람을 보고 말을 바꾼 것이 아니라는 뜻이지. 다만 시신이 사라진 일은 별개로 살펴야겠군. 칠성이 제군의 일을 모른다 하니, 이 몸도 당사자에게 직접 물을 말이 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_006","speaker":"각청","text":"응광에게 자리를 마련하라고 전하겠습니다. 하지만 이 사람의 증언만으로 리월의 조사가 끝난 것은 아닙니다. 선인께서 함께 들으신다는 것과, 제가 현장을 확인할 책임은 같이 갈 수 있어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_007","speaker":"류운차풍진군","text":"이 몸이 자네에게 손을 놓으라 하였나? 움직일 마음이 있다면 길부터 열게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_008","speaker":"","text":"각청의 눈썹이 움직였지만 그녀는 돌아서서 길을 지시했다. 나를 믿게 하려고 선인을 데려온 것은 아니었는데, 지금 나를 응광에게 데려갈 수 있는 힘은 그녀들이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_adepti_009","options":[{"label":"오셨으니까 말씀드리는데, 이 사람은 제 말이 안 믿겨도 현장까지 같이 와 줬어요. 저 때문에 처음부터 서로 화내실 필요는 없어요.","id":"PRO_L03K1_adepti_010","items":[{"k":"line","id":"PRO_L03K1_adepti_011","speaker":"류운차풍진군","text":"자네가 목을 아끼라는 충고를 들을 생각은 없으면서 다른 이들의 언성을 걱정하는군. 좋네. 이 몸도 따질 말은 당사자 앞에서 하겠어. 그때는 자네도 본 것을 빠뜨리지 말게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"같이 가 주셔야겠어요. 제가 혼자 모락스의 계획이라는 말을 꺼내면 의자에 앉기도 전에 끌려나올 것 같습니다.","id":"PRO_L03K1_adepti_012","items":[{"k":"line","id":"PRO_L03K1_adepti_013","speaker":"류운차풍진군","text":"산에서는 문밖에 앉을 자리라도 있었지. 여기서는 서서 고함만 지를 작정이었나 보군. 이 몸이 함께 듣겠네. 자네의 설명이 틀리면 틀렸다고 할 사람도 필요할 테니.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_adepti_014","speaker":"소","text":"네가 서 있던 곳은 내가 보겠다. 바다 쪽에도 움직임이 있다면 놓치지 않겠어. 너는 살아 있는 사람을 붙들고 죽었던 순간만 묻지 마. 그다음에 무엇을 할지도 들어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_015","speaker":"나","text":"……알겠어요. 그런데 망서 객잔에서 하셨던 말이 아직 걸려요. 제 주변에 느껴진다는 것. 지금도 제가 사람들하고 같이 있어도 되는 겁니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_016","speaker":"소","text":"네 질문에 답할 단서는 아직 없다. 그래서 보고 있는 거야. 두려워서 혼자 움직이다 죽을 이유도 없다. 길을 안내받아라.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_017","speaker":"","text":"소는 더 설명하지 않고 현장 바깥으로 움직였다. 나를 무해하다고 선언한 것이 아님을 알았다. 그래도 혼자 사라지지 말라는 말은 들었다. 각청이 돌아와 군옥각에서 만나겠다는 응광의 답을 전했을 때, 나는 이번에는 제대로 고개를 끄덕일 수 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_049","text":"군옥각으로 향하는 동안 각청은 먼저 보낸 병사들의 보고를 받았다. 황금옥 쪽에 우인단 인원이 드나든 흔적이 있고, 안쪽과 연락이 원활하지 않다는 소식이었다. 정해진 경로와 인솔을 따라 군옥각에 오른 뒤, 나는 아래로 멀어지는 거리보다 문 안에서 기다리는 사람을 먼저 보았다."},{"k":"line","id":"PRO_L03K1_palace_001","speaker":"","text":"응광은 창가가 아니라 길게 놓인 탁자 곁에 서 있었다. 손님을 위한 잔과 항구 지도가 함께 준비되어 있었다. 그녀의 눈길은 내 흙 묻은 신발, 갈라진 입술, 선인들 앞에서도 물러서지 않는 각청을 차례로 훑었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_002","speaker":"응광","text":"며칠 동안 바깥에서 기다리던 손님이 선인들과 함께 올라올 줄은 몰랐네. 내게 개인적으로 하고 싶었던 말이 있다지? 이번에는 들을 사람이 모두 모였으니, 가장 급한 것부터 말해 봐.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_003","speaker":"나","text":"먼저 당신도 기억 못 한다는 게 맞는지 직접 듣고 싶어요. 의례가 시작되자 모락스의 시신이 떨어졌고, 당신은 사람들을 물린 다음 현장을 떠났어요. 저는 각청한테 당신을 만나게 해 달라고 했고요. 그 장면 중에 기억나는 게 하나도 없어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_004","speaker":"응광","text":"의례를 준비하고 올라간 일은 기억해. 네가 말하는 제군의 죽음은 기억에 없어. 자리를 떠난 뒤 누구에게 무엇을 맡겼는지 물으면, 그 사이에 분명하지 않은 부분이 있어. 마음에 들지 않는 대답이겠지만 내게 없는 기억을 만들어 줄 수는 없겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_005","speaker":"","text":"응광은 웃지 않았다. 자신이 모르는 일을 인정하면서도 그 자리를 나에게 넘기지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_006","speaker":"류운차풍진군","text":"제군께 일이 생겼다는 증언을 이 몸이 들었고, 다른 선인들에게도 전했네. 그런데 이곳에 오니 제군의 몸은 없고, 칠성마저 당시를 기억하지 못한다 하는군. 이 일을 인간들의 장부 한 장이 빠진 정도로 취급할 수는 없어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_007","speaker":"응광","text":"가볍게 보았다면 이 자리에 항구 지도를 펴 두지 않았겠죠. 다만 기억나지 않는다는 말과 아무것도 하지 않았다는 말은 달라요. 지금도 이동로와 황금옥을 확인하고 있어요. 선인들께서는 바다와 항구 밖을 살펴 주실 수 있겠죠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_008","speaker":"나","text":"그 시간 때문에 말씀드려요. 제가 알고 있던 이야기에서는 이건 모락스의 계획이었어요. 죽은 모습을 보이고, 자신이 없는 리월이 어떻게 버티는지 보려는 계획. 타르탈리아가 신의 심장을 찾아 황금옥으로 가고, 결국 오셀이 나타납니다. 그래서 류운차풍진군에게도 미리 바다를 경계해 달라고 했어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_009","speaker":"","text":"잔을 옮기던 사람이 손을 멈췄다. 각청은 내 쪽으로 몸을 돌렸고, 응광은 탁자 위의 손가락을 천천히 거두었다. 이름 하나가 방의 무게를 바꾸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_010","speaker":"응광","text":"제군의 계획을 안다는 말은 가벼운 패가 아니야. 그분이 직접 알려 줬어? 아니면 네가 본다는 그 이야기에서, 지금 이 방에 있는 사람들의 결정까지 정해져 있었던 거니?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_011","speaker":"나","text":"직접 들은 적은 없어요. 다른 세계에서 이곳의 일을 이야기로 봤습니다. 그래서 알고 있다고 생각했는데, 이번에는 사람들까지 죽었어요. 드발린도 정말 죽었고 다시 살아났고요. 제가 알던 계획에는 그런 일이 없었습니다. 사람들 죽은 것까지 모락스가 했다고 우기는 게 아니라, 제가 알고 있는 다음 위험을 말하는 거예요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_012","speaker":"각청","text":"그럼 앞에서 맞는 일이 있었다고 뒤의 일을 전부 믿어서는 안 돼. 하지만 대비하지 않을 이유도 없어. 바다의 위험을 막을 방법, 타르탈리아를 막을 방법. 네가 아는 건 그 두 가지에 도움이 돼?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_013","speaker":"","text":"군옥각의 안쪽을 보았다. 멀리서 올려다보았을 때는 거대한 이야기 속 무대였지만 지금은 누군가 오래 모은 물건들이 놓인 집이었다. 그것을 잃으라고 말할 차례가 다가오자, 머릿속에서 쉬웠던 공략이 갑자기 남의 삶을 처분하는 말이 되었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_014","speaker":"나","text":"오셀이 정말 나오고, 제가 아는 흐름대로 흘러가면… 이 군옥각을 포기해야 합니다. 바다에 떨어뜨려서 막는 거예요. 당신이 이걸 얼마나 아끼는지도 알아요. 그래서 돌려 말하고 싶지 않아요. 당신 집을 잃게 되는 이야기입니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_015","speaker":"응광","text":"내 집을 얼마나 아끼는지 안다고 말한 손님이, 처음 올라온 자리에서 버리라고 권하는군. 흥미로운 방문이야. 그런데 넌 지금 내 결정을 알려 주는 거니, 아니면 그렇게 될 상황을 막아 달라는 거니? 둘은 값이 많이 달라.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_palace_016","options":[{"label":"막을 수 있다면 막고 싶어요. 그래서 황금옥으로 가겠다는 거고요. 다만 제가 못 막으면, 당신한테 아무 준비도 없이 그 순간을 맞게 하고 싶지 않아요.","id":"PRO_L03K1_palace_017","items":[{"k":"line","id":"PRO_L03K1_palace_018","speaker":"응광","text":"그렇다면 순서가 바뀌었네. 나는 지금 군옥각을 버리기로 결정하지 않겠어. 먼저 바다의 위험을 늦추고, 해안의 사람을 물리고, 이곳을 어떻게 쓸지 계산할 거야. 마지막에 리월을 위해 내놓아야 한다면 그때 내가 결정해. 네가 기억하는 장면에 맞추려고 미리 지붕을 떼어 버릴 생각은 없어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"제가 기억하는 결말은 경고로만 받아 주세요. 재현하자는 게 아니에요. 황금옥을 막는 동안, 해안의 사람들을 먼저 옮길 수 있는지 검토해 주세요.","id":"PRO_L03K1_palace_019","items":[{"k":"line","id":"PRO_L03K1_palace_020","speaker":"응광","text":"경고와 결정은 구분하겠어. 네가 알려 준 위험을 지금 이곳의 조건으로 다시 계산할 거야. 군옥각을 어떻게 쓸지, 언제 포기할지는 내가 판단해. 누구의 이야기 속 장면을 완성하려고 버리지는 않겠어.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_palace_021","speaker":"류운차풍진군","text":"그 판단에 선인들의 힘도 계산해 넣게. 인간의 건물 하나를 떨어뜨릴 때까지 구경만 할 셈으로 온 것이 아니니. 다만 오셀의 이름을 가볍게 여기지도 말아야 하네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_022","speaker":"각청","text":"해안부터 움직이겠습니다. 겁을 먹은 사람들이 한 길에 몰리지 않게 바깥 대기 구역도 다시 나눠야 해요. 선인들이 바다를 맡아 주시면 안쪽 통로는 제가 열겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_023","speaker":"","text":"논쟁이 끝났다는 선언은 없었지만 해야 할 일이 갈라졌다. 바다를 향할 선인들, 해안을 비울 칠성의 사람들, 황금옥을 확인할 병사들. 내 말이 받아들여지면 홀가분할 줄 알았다. 실제로는 내 말 때문에 사람들이 움직이기 시작한 것이 더 무거웠다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_palace_024","options":[{"label":"한 가지만 부탁할게요. 제가 안 돌아오더라도 황금옥 쪽은 꼭 한 번 더 봐 주세요. 소식 끊긴 사람이 또 생기면, 이번에도 저 혼자 기억하는 일로 끝날 것 같아서요.","id":"PRO_L03K1_palace_025","items":[{"k":"line","id":"PRO_L03K1_palace_026","speaker":"응광","text":"안 돌아올 생각부터 하고 나가는 손님은 대접하기 어렵지. 황금옥 바깥 연락선은 남겨 둘게. 네가 그 선을 끊지 않도록 움직여. 돌아와서 직접 보고하는 편이 나에게도 훨씬 값진 일이야.","map":"MAP_LIYUE_HARBOR"}]},{"label":"군옥각을 지키면 저는 나중에 여기서 밥 한 번 먹어도 됩니까? 돌아올 핑계가 하나쯤 있으면 좋겠어요.","id":"PRO_L03K1_palace_027","items":[{"k":"line","id":"PRO_L03K1_palace_028","speaker":"응광","text":"이 방까지 와서 밥값부터 걱정하는 사람은 드문 편이야. 돌아와서 오늘 한 말이 얼마나 맞았는지 설명해 봐. 식탁을 차릴 만큼 시간이 남도록 만드는 게 먼저겠지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_palace_029","speaker":"나","text":"그럼 저는 타르탈리아를 막으러 황금옥으로 갈게요. 제군의 시신이 정말 거기에 있는지도 보겠습니다. 적어도 제가 알고 있던 다음 장면이 그대로 시작되도록 내버려 두지는 않을 겁니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_030","speaker":"응광","text":"병사들이 바깥까지 안내할 거야. 네가 알고 있던 상대만 만나리라고 기대하지 마. 지금 네 이야기에서 가장 확실해 보이는 것조차 이미 여러 번 달라졌으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_078","text":"그 말은 내가 나 자신에게 해 주지 못했던 충고였다. 잔에 남은 물을 다 마셨다. 군옥각을 희생해야 한다는 말을 들은 직후에도 응광의 손은 흔들리지 않았다. 대신 창밖을 보는 시간이 아주 잠깐 길어졌다."},{"k":"keep","id":"ISK_L03_K1_079","text":"군옥각을 내려와 길을 나누는 곳에서 각청이 나를 잠깐 세웠다. 앞서 보낸 병사가 황금옥의 안쪽 출입문이 제대로 열리지 않는다고 보고하고 있었다. 서둘러 걸음을 옮기려다 각청이 내민 물통을 보고 멈췄다."},{"k":"line","id":"PRO_L03K1_water_001","speaker":"각청","text":"마시고 돌려줘. 가는 길에 쓰러지면 네가 하겠다는 일을 아무도 대신 이어받지 못해. 병사들도 네 머릿속에 있는 길을 아는 게 아니니까, 들어가기 전에 어느 쪽으로 갈지 말해 두고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_002","speaker":"나","text":"……말하는 건 진짜 그대로네. 기억만 없다는 게 이렇게 사람을 서운하게 할 줄 몰랐다. 나중에 생각나면 내가 천막 당기던 힘 조절은 좀 나아졌다고 해 줘. 못 떠올리면… 그건 됐고, 오늘 물 챙겨 준 건 내가 기억할게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_003","speaker":"각청","text":"기억나지 않는 일을 기억한다고 약속할 수는 없어. 오늘 네가 돌아오길 기다리는 건 할 수 있어. 네가 봤다는 나와 지금의 나를 자꾸 경쟁시키지는 마. 나도 지금 할 수 있는 일을 하고 있으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_004","speaker":"","text":"물통을 돌려주며 처음으로 그녀의 얼굴을 제대로 보았다. 죽어 있던 얼굴과 살아 있는 얼굴을 겹쳐 확인하지 않고, 지금 나에게 화를 내지 않으려 애쓰는 사람을 보았다. 각청은 할 말을 마치자 곧 해안 쪽으로 돌아섰다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_084","text":"황금옥 방면 통행은 별도로 허가되었다. 호위 병사들은 길목의 수레를 다른 곳으로 돌리고, 안쪽에 남은 일꾼을 데리고 나오기 위해 연락을 이어 갔다. 나에게 열린 길은 위험이 보고된 건물로 가는 길 하나였고, 그 사실이 이상할 만큼 마음을 단순하게 만들었다."},{"k":"keep","id":"ISK_L03_K1_085","text":"언덕 쪽으로 오르는 동안 손가락을 펴고 오므렸다. 무기를 쥘 때 갈라진 곳이 당겼지만 손목은 움직였다. 황금빛 건물이 가까워질수록 안에서는 아무 소리도 들리지 않았다. 그 고요를 의례장의 고요와 같은 것으로 만들지 않으려고, 나는 의식적으로 발밑의 자갈 소리에 귀를 기울였다."},{"k":"line","id":"PRO_L03K1_golden_001","speaker":"","text":"황금옥 외부에서는 마지막 일꾼 둘이 병사의 부축을 받아 나오고 있었다. 안쪽 통로에서 큰 소리를 들은 뒤 문짝 하나가 비틀렸고, 관리 구역을 거쳐 돌아 나왔다는 설명이었다. 안쪽으로 이어지는 틈은 아직 열려 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_002","speaker":"나","text":"저는 저 통로로 들어갈게요. 안에 있는 사람이 나오면 붙잡으려고 몰려들지 마세요. 타르탈리아면 여러분이 출구를 막고 서는 쪽이 더 위험해요. 사람들 먼저 멀리 보내고, 제가 나오면 이쪽이 비어 있게 해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_003","speaker":"호위 병사","text":"무작정 안쪽으로 쫓아가지는 않겠습니다. 대신 방향을 바꾸시면 소리를 내십시오. 저희가 출구를 비우는 것과 당신이 어디 있는지도 모르게 되는 건 다른 일입니다. 돌아나올 길을 보면서 가십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_089","text":"틈을 지나 안으로 들어갔다. 천장과 기둥 사이의 먼지가 아주 가늘게 떠 있었다. 모락스의 시신은 보이지 않았다. 그보다 먼저, 넓은 공간 한가운데 서 있는 붉은 머리의 남자가 눈에 들어왔다. 타르탈리아였다. 적어도 내가 기억하는 얼굴과 옷차림은 그 이름에 맞았다."},{"k":"line","id":"PRO_L03K1_golden_004","speaker":"타르탈리아","text":"오는 데 시간이 걸렸네. 길을 찾지 못한 건 아닐 테고, 만나고 싶은 사람이 많았나 봐. 여기까지 왔으니 할 말은 있겠지?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_005","speaker":"","text":"말투는 가볍게 들렸다. 그 가벼움 뒤에서 당연히 나타날 것 같은 호기심을 기다렸다. 어디서 왔는지, 얼마나 싸울 수 있는지. 그러나 타르탈리아의 시선은 내 얼굴에 머물다 손, 문, 다시 얼굴 순으로 움직였다. 사람을 반기는 눈길인지 무언가가 도착했는지 살피는 눈길인지 구별하기 어려웠다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K1_golden_006","options":[{"label":"일단 시신부터 내놔. 네가 가져갔다면 어디 있는지 말하고, 아니라면 뭘 하러 여기 왔는지 말해.","id":"PRO_L03K1_golden_007","items":[{"k":"line","id":"PRO_L03K1_golden_008","speaker":"타르탈리아","text":"빈자리를 보고 바로 나를 찾아왔군. 네가 찾는 것이 원래 여기에 있었는지는 확인했어? 아니면 내가 여기 있어야 한다고 생각해서 온 건가?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"네가 여기에 있다는 사실과 네가 시신을 옮겼다는 건 따로 묻겠어. 무엇을 찾으러 왔고, 도착했을 때 여기에는 뭐가 있었지?","id":"PRO_L03K1_golden_009","items":[{"k":"line","id":"PRO_L03K1_golden_010","speaker":"타르탈리아","text":"내가 여기 있다는 이유만으로 모든 빈칸을 채우지는 않겠다는 건가. 그럼 네가 확인한 것부터 따져 보자고. 내가 여기 있어야 한다고 생각해서 온 거잖아?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K1_golden_011","speaker":"나","text":"대답을 질문으로 돌리는 솜씨는 알겠는데, 지금 그걸 칭찬해 줄 여유는 없어. 신의 심장을 찾으러 왔다면 그만둬. 원하는 걸 못 얻었다고 바다 쪽으로 일을 벌릴 생각도 하지 말고.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_012","speaker":"","text":"타르탈리아의 입가에 엷은 웃음이 걸렸다. 예상한 말을 들은 사람처럼 놀라지 않는 반응이 내 등을 서늘하게 했다. 눈앞의 남자는 신의 심장이라는 말보다 내가 어디까지 다가왔는지에 더 관심이 있는 것처럼 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_013","speaker":"타르탈리아","text":"내가 무엇을 할지 많이 생각했구나. 그러고도 혼자 이 앞까지 들어왔어. 바깥 사람들을 물린 건 잘했어. 여기서 벌어지는 일을 그들이 감당할 수 있을지는 나도 궁금하지 않거든.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_014","speaker":"나","text":"보통 그런 말은 부하들 상태부터 보고 하지 않나? 안쪽 문이 망가져서 일꾼들이 돌아 나왔어. 네 사람들이 안에 남아 있는지 궁금하지도 않아?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_015","speaker":"타르탈리아","text":"지금 내 앞에 있는 건 너잖아. 다른 사람을 이야기한다고 네가 할 일이 바뀌어? 싸우러 왔으면 움직여. 네가 어디서 멈추는지 보고 싶네.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_016","speaker":"","text":"무기를 고쳐 쥐었다. 기억 속 타르탈리아라면 그 말에 자신이 먼저 들떠 있을 것 같았다. 눈앞의 남자는 웃고 있었지만 재촉하지 않았다. 시작하는 순간보다 끝나는 순간에 관심이 있는 사람처럼 기다렸다. 내가 알던 모습과 다르다는 느낌은 분명했지만 그것으로 무엇을 알아냈다고 할 수는 없었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K1_golden_017","options":[{"label":"어디서 멈추는지 궁금하면 네 발부터 움직여. 밖에서 기다리는 사람들 있으니까 오래 끌 생각은 없어.","id":"PRO_L03K1_golden_018","items":[{"k":"line","id":"PRO_L03K1_golden_019","speaker":"타르탈리아","text":"기다리는 사람. 그래, 네가 돌아가야 할 이유가 있겠지. 그 이유만큼 움직여 봐. 여기서는 말보다 네 손이 더 많은 것을 보여 줄 테니까.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"내가 알고 있는 너는 싸움을 앞두고 그렇게 심심한 얼굴을 하지 않았어. 기분이 나쁜 건지 원래 이랬던 건지 모르겠지만, 지금은 확인할 시간도 없네.","id":"PRO_L03K1_golden_020","items":[{"k":"line","id":"PRO_L03K1_golden_021","speaker":"타르탈리아","text":"사람을 안다는 자신감은 편리하지. 처음 보는 내 표정보다 네 기억을 먼저 믿게 해 주니까. 가까이 와서 확인하면 더 빨리 끝나겠네.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K1_golden_022","speaker":"","text":"물이 칼날의 모양으로 빛났다. 반사적으로 몸을 옆으로 던졌고, 뒤의 돌에 날카로운 자국이 생겼다. 첫 공격은 대화를 이어 갈 틈을 잘라 냈다. 이제는 기억 속 전투가 아니라 눈앞에서 다가오는 공격을 막아야 했다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_107","text":"황금옥 내부에서 타르탈리아와의 전투가 시작된다."},{"k":"line","id":"PRO_L03K1_golden_023","speaker":"","text":"공격을 피하려 기둥 뒤로 물러났을 때 발밑의 돌판이 내려앉았다. 타르탈리아가 따라 들어오다 자세를 낮췄다. 내가 힘으로 밀어붙인 것이 아니었다. 손아귀가 풀려 무기를 놓칠 뻔했다. 그래도 밖으로 이어지는 길을 그냥 내줄 수는 없었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_024","speaker":"나","text":"여기서 끝내. 더는 바다도, 밖의 사람들도 건드리지 마. 내가 아는 일이 틀렸다면 틀린 채로 끝내도 되니까, 지금 네가 하려는 것부터 멈춰.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_025","speaker":"","text":"타르탈리아가 고개를 들었다. 다음 공격을 준비하는 대신 내 어깨 너머를 보았다. 그 시선이 어디에 닿았는지 확인하지 못했다. 승기를 붙잡았다고 생각한 바로 그 순간, 발밑에서 낮은 파열음이 났다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_026","speaker":"","text":"바닥의 금이 발끝을 지나 기둥 아래로 달렸다. 위에서 먼저 먼지가 쏟아지고, 이어 돌을 잇던 구조물이 굉음과 함께 어긋났다. 출구 쪽으로 몸을 틀었다. 늦었다. 무너져 내리는 들보가 시야를 가렸고, 틈 너머로 보이던 타르탈리아의 모습도 먼지 속에 사라졌다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_027","speaker":"나","text":"밖으로 물러나요! 문 앞에 서 있지 말고, 멀리—!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_113","text":"외침은 건물이 내려앉는 소리에 묻혔다. 충격이 어깨와 등을 차례로 때렸다. 쏟아진 돌과 들보가 몸을 눌렀다. 누군가의 손목에서 맥박을 찾던 손가락이 이제 내 몸을 빼낼 틈을 더듬었다. 빛이 가늘어졌다. 황금옥이 무너졌고, 나는 그 아래에 깔렸다."},{"k":"keep","id":"ISK_L03_K1_END","text":"황금옥 잔해가 나를 덮친 순간에서 멈춘다. 구조 여부와 부상 상태는 아직 밝혀지지 않는다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_0","text":"각청 님, 고운각에서 가져온 보고와 같은 배가 다시 보였답니다. 경계대를 더 보내고 있어요. 그리고… 이분. 공고를 들고 저를 찾아오셨던 분이에요. 며칠 전에 저와 함께 고운각에 가셨어요."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_1","text":"……네가 이 사람을 알아? 감우, 그 보고를 찾은 게 언제야. 황금옥 확인과 해안 경계를 같이 진행해. 둘 중 하나가 끝날 때까지 기다리지 말고."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_2","text":"회수한 원본은 여기 있어. 이 사람 이름도 같이 적혀 있지. 각청, 네가 기억 못 하는 건 네 잘못이 아니지만, 이 사람이 거짓말을 한 것도 아니야. 이번에는 어느 시각부터 말이 달라졌는지 먼저 남기자."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_3","text":"……두 사람이 기억하고 있을 줄은 몰랐어. 그 보고를 못 찾았으면 또 나만 아는 얘기로 끝났겠네. 고마워. 정말로."}]},{"id":"ISK_L03_K2","entry":"ISK_L03_K2_001","items":[{"k":"keep","id":"ISK_L03_K2_001","text":"각청이 누구냐고 묻는 동안 나는 그녀의 등 뒤로 시선을 보냈다. 포대를 올려 두던 자리, 손바닥으로 허리를 두드리던 짐꾼의 모습이 차례로 떠올랐다. 각청이 살아 있다면 그 사람도 있을 수 있었다. 반가움이 생기기도 전에 그 자리를 확인하고 싶어 몸이 먼저 움직였다."},{"k":"line","id":"PRO_L03K2_stranger_001","speaker":"나","text":"...각청? 너... 살아 있었어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_002","speaker":"각청","text":"네가 누군지는 모르겠지만, 다짜고짜 살아 있었냐니... 칠성에게 할 인사치곤 꽤 무례한걸?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_003","speaker":"나","text":"나... 정말 기억 안 나? 끈 풀린 포대, 같이 확인했잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_004","speaker":"각청","text":"그 포대 일은 알아. 그런데 너랑 같이 있었다고? ...우선 무슨 일인지부터 말해 봐.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_005","speaker":"","text":"낯선 사람을 보는 눈빛에, 다가가던 발이 멎었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_006","speaker":"나","text":"...그럼 그 짐꾼은? 허리 아프다고 하던 분. 나랑 같이 있었잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_007","speaker":"각청","text":"진정해 봐. 허리가 아픈 짐꾼이라고? 지금 이 근처에선 본 기억이 없는데... 그 사람을 찾는 거야?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_008","speaker":"나","text":"응... 이름은 못 들었어. 그래도 얼굴은 알아. 보면 알아볼 수 있어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_009","speaker":"각청","text":"그럼 마지막으로 본 곳부터 말해 줘. 거기서 무슨 일이 있었는지도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_010","speaker":"나","text":"의례장에 같이 갔어. 그런데 모락스의 시신이 떨어지고... 사람들이 전부 쓰러졌어. 너도, 그 사람도...","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_011","speaker":"각청","text":"...제군의 시신이 떨어졌다고? 그런 일은 기억에 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_012","speaker":"나","text":"데리고 나오려고 했는데... 못 했어. 네가 살아 있으니까, 그분도 혹시...","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K2_stranger_013","options":[{"label":"그분이 돌아왔는지... 같이 찾아봐 줘.","id":"PRO_L03K2_stranger_014","items":[{"k":"line","id":"PRO_L03K2_stranger_015","speaker":"각청","text":"알겠어. 짐을 맡아 둔 곳으로 가자. 거기 있는 병사라면 알 수도 있어.","map":"MAP_LIYUE_PLAINS"}]},{"label":"...나부터 기억해 달라는 게 아니야. 그분만 찾아주면 돼.","id":"PRO_L03K2_stranger_016","items":[{"k":"line","id":"PRO_L03K2_stranger_017","speaker":"각청","text":"널 기억 못 한다고 찾지 않겠다는 뜻은 아니야. 나도 같이 확인할게.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L03K2_stranger_018","speaker":"","text":"각청이 앞장서 수레 사이로 길을 잡았다. 맡겨 둔 짐은 그대로였지만, 그 곁에 짐꾼은 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_019","speaker":"각청","text":"이 사람과 같이 왔던 짐꾼, 어디 있는지 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_020","speaker":"검수 병사","text":"아, 그때 그분이군요. 두 분이 함께 계셨던 건 기억합니다. 짐도 아직 여기 있고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_021","speaker":"나","text":"그럼... 그분은요? 돌아온 건 봤어요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_022","speaker":"검수 병사","text":"자리를 비우신 건 아는데... 돌아오셨는지는 기억이 안 납니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_023","speaker":"각청","text":"의례장에 다녀온 사람도 불러 줘. 제군의 시신이 떨어졌다는 말을 들은 적 있는지 물어보고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_024","speaker":"","text":"병사가 불러온 두 사람도 고개를 저었다. 의례장에 다녀왔다면서도, 모락스가 떨어졌다는 말에는 되묻기만 했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_025","speaker":"나","text":"...짐은 여기 있는데. 사람만 어디로 간 거야...","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_026","speaker":"각청","text":"아직 마지막으로 본 자리가 남았잖아. 내가 같이 갈게. 어디인지 알려 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K2_stranger_027","options":[{"label":"그분 짐을 잠깐 맡아 달라고만 해 줘. 돌아올 사람이 살아 있다면 남의 짐까지 없어져 있으면 안 되잖아.","id":"PRO_L03K2_stranger_028","items":[{"k":"line","id":"PRO_L03K2_stranger_029","speaker":"각청","text":"원래도 인계가 끝나지 않은 물건이야. 주인 확인 없이 옮기지 않도록 해 둘게. 이제 움직이자.","map":"MAP_LIYUE_PLAINS"}]},{"label":"그분이 오면 내가 찾았다고 말해 줘. 이름도 모르면서 아는 척하는 사람 있었다고.","id":"PRO_L03K2_stranger_030","items":[{"k":"line","id":"PRO_L03K2_stranger_031","speaker":"각청","text":"그렇게는 전하지 않을 거야. 함께 의례에 갔던 사람이 돌아와 찾고 있다고 하겠어. 널 설명하는 데 굳이 네가 싫어할 말을 보탤 필요는 없어.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L03_K2_017","text":"짐이 놓인 곳을 마지막으로 보았다. 남겨 둔 물건이 기다리는 사람을 증명해 주지는 않았지만, 돌아와 다시 일할 자리가 있다는 것만은 지우고 싶지 않았다. 각청은 수레 사이에서 비켜서 길을 내주었다. 돌아갈 곳은 그 사람을 두고 온 의례장이었다."},{"k":"keep","id":"ISK_L03_K2_018","text":"옥경대로 올라가는 동안 각청에게 온 전갈은 상황을 더 이상하게 만들었다. 응광도 제군의 죽음을 기억하지 못했다. 전갈을 전하는 병사의 말을 끊지 않으려고 턱에 힘을 주었다. 그 힘이 풀리면 다시 소리를 지르게 될 것 같았다."},{"k":"line","id":"PRO_L03K2_empty_001","speaker":"","text":"도착하자마자 짐꾼이 쓰러졌던 곳으로 갔다. 짐꾼도, 모락스의 거대한 몸도 보이지 않았다. 빈자리를 보자 숨이 턱 막혔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_002","speaker":"나","text":"...없어? 분명히 저기에 있었잖아. 누가 옮긴 거야?!","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_003","speaker":"현장 병사","text":"옮기라는 명령도, 인계받은 곳도 찾지 못했습니다. 여기 남은 사람들도 본 적이 없다고 합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_004","speaker":"각청","text":"남아 있는 사람들만 물어본 거야? 그날 일하고 돌아간 사람들도 찾아봐.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_005","speaker":"현장 병사","text":"아직 확인 중입니다. 알아내는 대로 보고드리겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_006","speaker":"나","text":"그 짐꾼도... 없어. 부두엔 짐만 남아 있고. 여기엔 있을 줄 알았는데...","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_007","speaker":"","text":"짐꾼을 끌어안았던 팔이 떨렸다. 각청이 병사에게 잠시 기다리라는 손짓을 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_008","speaker":"나","text":"내가... 그 사람을 여기 두고 갔어. 조금만 더 끌어 봤으면 됐을지도 모르는데...","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_009","speaker":"각청","text":"그건 아직 모르는 일이잖아. 어디까지 옮겼는지 보여 줘. 거기서부터 찾아보자.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_010","speaker":"나","text":"...여기. 돌아오면 같이 짐 확인하자고 했는데...","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_011","speaker":"","text":"발치를 가리키자 각청이 몸을 낮춰 살폈다. 끌고 왔다는 방향까지 확인하고 병사를 불렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_012","speaker":"각청","text":"부두의 검수 병사에게 사람을 보내. 맡겨 둔 짐으로 신원을 알아보고, 함께 일한 사람들도 찾아. 부상자를 옮긴 곳도 확인해 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_013","speaker":"나","text":"이름도... 못 들었어. 얼굴은 알아. 보면 알아볼 수 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_014","speaker":"각청","text":"그럼 넌 얼굴을 확인해 줘. 이름은 검수 병사에게 물어보면 되잖아. 찾을 방법이 없는 건 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_015","speaker":"","text":"병사를 보낸 각청은 내 곁에 남아 다음 말을 기다렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_016","speaker":"나","text":"...도와주는 거야? 내 말이 맞는지도 모르면서...?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_017","speaker":"각청","text":"그러니까 확인하는 거야. 기억나지 않는다고 네가 틀렸다고 할 순 없지. 사람이 사라졌다는 말을 듣고 그냥 넘길 수도 없고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_018","speaker":"나","text":"찾으면... 꼭 알려 줘. 다쳤으면 내가 갈게. 부탁할게, 각청.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_019","speaker":"각청","text":"알았어. 소식이 오면 바로 알려 줄게. 그때까지는 내 옆에 있어. 지금 혼자 뛰어다닐 상태는 아니잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_020","speaker":"","text":"각청은 보폭을 늦춰 걸음을 맞추고, 남은 병사에게 의례장 밖을 가리켰다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_021","speaker":"각청","text":"제군의 몸을 옮긴 흔적도 찾아봐. 큰 짐을 실은 수레가 나갈 만한 길부터. 그쪽은 네가 맡아 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_022","speaker":"","text":"각청이 짚은 길을 보다가, 내가 알던 이야기에서 제군의 몸을 옮겨 두었던 곳이 떠올랐다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_empty_023","options":[{"label":"타르탈리아야. 저걸 가져갔다고 내가 본 건 아닌데… 그 사람이 황금옥으로 가. 제군의 신의 심장을 찾으러. 응광을 만나야겠어. 이번에는 정말 만나야 해.","id":"PRO_L03K2_empty_024","items":[{"k":"line","id":"PRO_L03K2_empty_025","speaker":"각청","text":"우인단 집행관 말이지. 황금옥을 살피게 하겠어. 하지만 네가 어떤 근거로 그 행동을 예상하는지 설명해야 해. 그 이름을 말하는 것만으로 널 응광 앞에 바로 세울 수는 없어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"황금옥부터 확인해 줬으면 해. 내가 아는 이야기대로라면 타르탈리아가 신의 심장을 찾으러 갈 수 있어. 시신을 옮긴 걸 봤다는 주장은 아니야.","id":"PRO_L03K2_empty_026","items":[{"k":"line","id":"PRO_L03K2_empty_027","speaker":"각청","text":"예상과 직접 목격을 나눠 말한 건 알겠어. 황금옥을 살피게 하겠어. 그래도 그 근거는 응광 앞에서 설명해야 해.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_empty_028","speaker":"나","text":"설명할게. 모락스의 계획하고, 그 뒤에 일어날 수 있는 일을 알아. 내가 산에 올라가서 류운차풍진군에게도 먼저 말했어. 그분한테 확인하면 돼. 이번에는 나만 한 말을 기억하는 게 아닐 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_030","text":"각청이 병사를 보내는 사이, 계단 아래에서 숨 가쁜 발소리가 올라왔다. 행추와 연비였다. 두 사람은 의례장에 없었다. 그러니 기억도 그대로였다."},{"k":"line","id":"PRO_L03K2_adepti_001","speaker":"","text":"그 순간 공기가 달라졌다. 병사들이 한꺼번에 자세를 바로잡았고, 의례장 바깥의 높은 곳에 선 그림자가 내려왔다. 류운차풍진군이었다. 뒤로는 다른 선인들의 기척이 이어졌다. 산의 문밖에서 목이 쉬도록 불렀던 상대가 이번에는 먼저 찾아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_002","speaker":"류운차풍진군","text":"이 몸에게 확인하면 된다더니, 정작 이 몸이 와도 인사할 숨은 남겨 두지 않았군. 산에서 그렇게 기진하더니 돌아와서는 또 목부터 쓰고 있는가. 자네가 말한 사람들 가운데 이 여인이 포함되어 있었지?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_003","speaker":"나","text":"네. 지금 살아 있어요. 그런데 저를 기억 못 하고, 응광도 모락스가 쓰러진 걸 기억 못 한답니다. 시신은 없어졌고요. 제가 같이 갔던 짐꾼은 아직 못 찾았어요. 각청이 살아 있다는 걸 보자마자 그 사람부터 찾게 됐습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_004","speaker":"류운차풍진군","text":"살아 있는 사람을 보고 다른 살아 있을 사람을 찾는 것이 잘못은 아니지. 다만 이 몸도 없는 사람을 이 자리에서 곧장 데려다줄 수는 없네. 자네의 말을 들은 뒤 다른 선인들에게 알렸고, 필요한 자들이 함께 왔어. 제군께 관한 일은 칠성과 직접 이야기하겠네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_005","speaker":"","text":"선인들을 보며 처음으로 산길에서 한 일이 헛되지 않았다는 것을 실감했다. 짐꾼을 데려오지 못했지만 이야기는 전달했다. 기록에 남긴다는 말보다 발소리가 더 분명한 답이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_006","speaker":"각청","text":"자리를 마련하겠습니다. 제군의 시신을 옮겼다는 명령이나 인수는 찾지 못했습니다. 황금옥에도 사람을 보냈고요. 확인되지 않은 일을 확인된 일처럼 말씀드릴 수는 없지만, 없는 기억을 핑계로 기다리고 있지는 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_007","speaker":"류운차풍진군","text":"그 마음가짐은 좋네. 그렇다면 길을 여는 일에 오래 걸릴 이유도 없겠지. 대답할 수 있는 사람 앞으로 안내하게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_008","speaker":"","text":"소는 선인들 뒤에서 나를 잠깐 살폈다. 망서 객잔에서 처음 만났을 때와 같은 간결한 눈길이었다. 그 앞에서 내가 그 냄새의 주인인지 설명하려 하지 않았다. 지금 필요한 질문을 골랐다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_009","speaker":"나","text":"황금옥에 가려면 우선 응광을 만나야겠어요. 바다 쪽 위험을 말씀드렸는데, 그것도 함께 봐 주실 수 있습니까? 제가 타르탈리아를 막는 동안 다른 쪽이 먼저 터지면 저 혼자 뛰어간 의미가 없어져요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_010","speaker":"소","text":"바다는 우리가 보겠다. 네가 안다는 상대에게만 눈을 두지 마. 도망칠 길이 막혔는지도 봐라. 사람 하나를 더 두고 돌아왔다고 후회할 필요는 없으니.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_adepti_011","options":[{"label":"사람 하나 더는 저 말씀이시죠? 다들 저를 어디 배달할 짐처럼 다루시는데, 솔직히 지금은 안내가 있는 쪽이 좋습니다.","id":"PRO_L03K2_adepti_012","items":[{"k":"line","id":"PRO_L03K2_adepti_013","speaker":"류운차풍진군","text":"자네가 짐짝이라는 비유를 좀처럼 놓지 못하는군. 그 짐은 말을 너무 많이 한다는 흠도 있겠어. 따라오게. 다리가 풀리면 허세부터 부리지 말고 멈췄다고 말하고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"제가 먼저 말을 꺼내겠습니다. 응광이 화를 내면 중간에서 들어만 주세요. 혼자 우기는 사람으로 끝내고 싶지 않습니다.","id":"PRO_L03K2_adepti_014","items":[{"k":"line","id":"PRO_L03K2_adepti_015","speaker":"류운차풍진군","text":"화를 내는 사람 하나 견디지 못하면서 제군의 계획을 논하러 갈 셈인가. 말할 것은 말하게. 이 몸이 들은 부분은 이 몸이 대답할 테니, 자네가 겪은 일까지 대신 맡기지는 말고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_adepti_016","speaker":"","text":"응광의 답이 도착할 때까지 오래 걸리지 않았다. 그사이 황금옥으로 보낸 병사가 되돌아와 안쪽 연락이 끊기고 우인단 인원이 드나들었다고 보고했다. 각청은 즉시 대피와 외곽 통제를 지시했다. 내가 짐작하던 장소가 실제로 문제가 벌어진 장소가 되어 가고 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_047","text":"군옥각으로 이동하는 동안 아래쪽의 물자 대기 구역을 찾았다. 멀리서는 수레도 포대도 구별되지 않았다. 누군가의 하루를 닷새나 묶어 둔 짐이 이 높이에서는 점 하나도 되지 않는다는 사실이 마음에 들지 않았다. 응광에게 말할 때 그 사람을 큰 계획의 작은 피해로 줄여 부르지 않기로 했다."},{"k":"line","id":"PRO_L03K2_palace_001","speaker":"","text":"응광은 내가 앉을 의자를 미리 비워 두었다. 흙 묻은 옷 때문에 망설이자 그녀는 의자를 새로 가져오라고 하지 않고 손으로 자리를 가리켰다. 귀한 물건을 더럽히는 걱정은 갑자기 아주 사소한 일이 되었지만, 응광이 그것을 사소하게 만들어 준 방식은 눈에 남았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_002","speaker":"응광","text":"내 앞에 오기 위해 먼저 산을 다녀온 손님이네. 평소라면 기다린 값이 얼마나 되는지부터 물었을 텐데, 오늘은 시간이 없겠지. 제군에 관한 일과 황금옥에 관한 일, 모두 네가 꺼낸 이야기라고 들었어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_003","speaker":"나","text":"그 전에 직접 물을게요. 의례에서 모락스의 시신이 떨어진 거, 정말 기억이 없습니까? 당신이 현장을 정리하고 떠나는 걸 봤어요. 당신이 떠난 뒤에 사람들이 죽었어요. 저하고 같이 온 짐꾼도요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_004","speaker":"응광","text":"기억에 없어. 당시 내렸다는 지시도 지금은 떠오르지 않고. 그 시간의 일이 매끄럽게 이어지지 않는다는 건 나도 알고 있어. 네가 그 사람을 두고 나왔다고 하던데, 함께 간 이의 행방은 찾았니?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_005","speaker":"나","text":"아직요. 짐만 그대로 있어요. 각청이 살아 있으니까 그분도 살아 있길 바라고 있는데, 그걸 확인할 때까지 아무 일도 못 하고 있을 수는 없잖아요. 그러니까 지금부터 하는 말이 맞든 틀리든, 그분 찾는 일도 계속해 주세요. 큰일 앞에서 작은 일 됐다고 넘어가지 말고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_006","speaker":"응광","text":"사람 하나를 찾는 일과 항구를 지키는 일은 서로 깎아야만 값을 맞출 수 있는 거래가 아니야. 각청이 이미 사람을 붙였다고 들었어. 그 보고는 계속 받겠어. 이제 네가 이곳까지 와서 말하려던 다음 일을 들어 보자.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_007","speaker":"","text":"찾았다는 약속도 살아 있다는 위로도 아니었다. 그러나 나는 처음으로 내 부탁을 손에서 놓을 수 있었다. 누군가가 계속 들고 있겠다고 말했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_008","speaker":"나","text":"제가 알고 있던 이야기에서는 모락스의 죽음은 계획이었습니다. 리월이 제군 없이 설 수 있는지 보기 위한 거였어요. 타르탈리아가 황금옥에서 신의 심장을 찾고, 뜻대로 되지 않으면 오셀을 불러오는 흐름으로 이어집니다. 저는 그걸 막으려고 해요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_009","speaker":"각청","text":"제군이 우리를 시험한다는 뜻이야? 우리에게는 기억이 끊겨서 당장 누구 말을 믿을지도 흔들리는 사람들이 있어. 그 고통까지 계획이라고 말하는 거라면 받아들일 수 없어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_010","speaker":"나","text":"그건 아니야. 내가 알던 이야기에는 병사들 기억상실도, 의례장에서 사람들이 죽는 일도 없었어. 그래서 나도 화가 나는 거야. 분명 아는 줄 알고 왔는데, 그 사이에서 사람이 죽었는데, 큰 계획이 있겠지 하고 기다릴 수는 없잖아. 내가 아는 위험이라도 먼저 막자는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_011","speaker":"류운차풍진군","text":"산에서도 그와 같이 말했네. 자네들이 잊은 일을 먼저 이 몸에게 전했고, 제군의 계획이라는 말과 자신이 설명하지 못하는 참사를 나누어 이야기했지. 이 몸이 그 해석을 모두 받아들였다는 뜻은 아니네. 허나 오셀을 경계하라는 말을 듣고도 손 놓고 있을 이유는 없었어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_012","speaker":"응광","text":"내가 먼저 궁금한 건 네가 왜 그 이야기의 다음 일을 믿느냐는 거야. 앞에서 틀린 부분이 이렇게 많았다면, 타르탈리아가 네 예상대로 움직이지 않을 수도 있겠지. 그를 막는 데 사람과 시간을 보내는 동안 바다가 먼저 움직이면?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_013","speaker":"나","text":"그래서 선인들에게 바다를 부탁한 겁니다. 저는 황금옥으로 가고요. 전부 제 말 한 줄에 걸라고는 못 해요. 하지만 저기서 위험을 막을 기회가 있는데, 어긋날 수도 있다는 이유로 여기서 기다리는 건 못 하겠습니다. 기다리는 동안에도 누군가는 일을 겪으니까요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_014","speaker":"","text":"응광은 지도의 해안선을 손끝으로 짚었다. 류운차풍진군은 바다 쪽을 맡을 선인들의 움직임을 짚었고, 각청은 사람을 빼낼 순서를 바꾸었다. 서로의 판단을 전부 좋아하지는 않아도, 손은 같은 지도 위에서 움직였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_015","speaker":"응광","text":"황금옥은 확인할 거야. 네가 가겠다는 것도 들었고. 그 전에, 네가 아는 이야기에서 오셀은 어떻게 막았니? 네 얼굴을 보니 그 답이 마음에 들지 않는 모양인데.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_016","speaker":"나","text":"군옥각입니다. 제가 아는 흐름대로 가면, 오셀을 막기 위해 이걸 포기해야 해요. 바다에 떨어뜨려야 합니다. 응광, 처음 온 사람이 집을 버리라는 말을 하는 게 얼마나 뻔뻔한지는 알아요. 그래도 말 안 하고 떠나면 더 비겁할 것 같아서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_017","speaker":"","text":"방의 소리가 멎었다. 짐꾼에게는 남의 짐을 함부로 맡을 수 없다고 말해 놓고, 지금은 더 큰 것을 잃어야 한다고 이야기하고 있었다. 응광은 바로 답하지 않았다. 창 너머로 항구가 펼쳐져 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_018","speaker":"응광","text":"네가 그 이야기를 알았다고 해서 내 군옥각에 대한 권리까지 얻은 건 아니야. 그렇지만 손해가 날 수 있다는 말을 듣기 싫어서 숨기는 사람도 아니지. 내가 알고 싶은 건 그 순간까지 무엇을 해 볼 수 있느냐는 거야. 떨어뜨리기 전까지는 아주 쓸모 있는 곳이거든.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_palace_019","options":[{"label":"마지막에 내놓을 수 있는 걸 알아서 다른 방법을 덜 찾으면 안 된다는 거죠. 그래서 타르탈리아 쪽을 먼저 끊고 싶어요. 그게 되면 여기서 무슨 차를 마실지도 고민할 수 있겠죠.","id":"PRO_L03K2_palace_020","items":[{"k":"line","id":"PRO_L03K2_palace_021","speaker":"응광","text":"차는 나중에 골라. 지금은 자리를 비울 사람과 남을 사람부터 정할 거야. 군옥각을 어떻게 쓸지, 언제 포기할지는 내가 판단해. 리월을 남길 수 있다면 내놓겠지만, 누구의 이야기 속 장면을 완성하려고 버리지는 않겠어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"다른 방법을 먼저 찾죠. 마지막 수단이 있다는 이유로 사람을 옮기거나 바다의 위험을 늦출 기회까지 줄이고 싶지는 않아요.","id":"PRO_L03K2_palace_022","items":[{"k":"line","id":"PRO_L03K2_palace_023","speaker":"응광","text":"그래. 할 수 있는 일을 다 세어 본 뒤에야 마지막이라는 말을 쓸 수 있겠지. 군옥각을 어떻게 쓸지, 언제 포기할지는 내가 판단해. 누구의 이야기 속 장면을 완성하려고 버리지는 않겠어.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_palace_024","speaker":"류운차풍진군","text":"좋은 건물은 쓰임이 많지. 바다의 경계는 맡겠네. 인간들의 준비가 늦어져 싸움터에 사람이 남는 일은 없도록 하게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_025","speaker":"각청","text":"그건 저희가 하겠습니다. 다만 대피 중인 길 위로 싸움이 밀려오면 즉시 알려 주세요. 선인들이 지킨다는 말만 믿고 사람을 같은 자리에 세워 두지는 않을 겁니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_026","speaker":"","text":"쉽고 다정한 합의는 아니었다. 선인에게는 오래 지켜 온 땅이었고 칠성에게는 지금 사람들을 먹이고 재우는 도시였다. 두 쪽이 그것을 설명하는 말은 달랐지만 지켜야 할 사람들의 위치는 같았다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_palace_027","options":[{"label":"그분을 찾으면 제가 도망친 얘기를 먼저 하셔도 됩니다. 변명 안 할게요. 대신 제가 다시 돌아와 찾았다는 것도 같이 전해 주세요.","id":"PRO_L03K2_palace_028","items":[{"k":"line","id":"PRO_L03K2_palace_029","speaker":"응광","text":"전할 수 있게 되면 함께 전하겠어. 다만 네가 지금도 살아 있다는 말까지 붙일 수 있도록 행동해. 상대에게 할 말을 남겨 두고 사라지는 건 거래를 끝내는 좋은 방법이 아니니까.","map":"MAP_LIYUE_HARBOR"}]},{"label":"나중에 일이 끝나면 이 방에서 아무 일 없는 얘기도 한 번 하고 싶어요. 밥 늦게 나왔다고 불평하는 정도로요. 지금은 그게 되게 사치스럽네요.","id":"PRO_L03K2_palace_030","items":[{"k":"line","id":"PRO_L03K2_palace_031","speaker":"응광","text":"그런 불평은 평소에도 충분히 들어. 그래도 네가 직접 돌아와서 말한다면 한 번쯤은 시간을 내 주지. 그때는 귀한 방에 들어왔다는 이유로 억지 칭찬부터 늘어놓지 말고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_palace_032","speaker":"나","text":"좋아요. 저는 타르탈리아를 막으러 황금옥으로 가겠습니다. 제군의 시신이 왜 사라졌는지도 거기서 단서를 찾을 수 있으면 찾을게요. 일이 제가 아는 것처럼 안 흘러가더라도, 지금 벌어지는 일 앞에서 도망치지는 않을 겁니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_033","speaker":"응광","text":"도망치지 않겠다는 말은 마음에 들지만, 돌아올 길까지 버리겠다는 뜻이면 동의하지 않아. 황금옥 바깥에 병사를 남겨 둘게. 네가 가져올 수 있는 답은 네가 돌아와야 내게 닿으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_079","text":"응광은 다음 지시를 내리기 전 내가 일어서는 모습을 지켜보았다. 다리에 힘이 늦게 들어가 잠깐 의자 끝을 붙잡았지만 넘어지지 않았다. 류운차풍진군이 무슨 말을 하려다 멈췄고, 나는 굳이 못 본 척하지 않았다. 아직 몸을 챙기라는 잔소리를 들을 사람이 있다는 사실이 나쁘지 않았다."},{"k":"keep","id":"ISK_L03_K2_080","text":"군옥각에서 내려온 뒤 각청은 황금옥으로 가는 호위 병사들에게 나를 인계했다. 물자 구역의 답도 하나 도착해 있었다. 짐꾼은 아직 찾지 못했고 그의 물건은 그대로 보관 중이었다. 새 소식이 없다는 사실이 다시 화를 불러오려 했지만, 이번에는 누가 실제로 찾고 있는지도 알고 있었다."},{"k":"line","id":"PRO_L03K2_water_001","speaker":"나","text":"고마워. 아직 못 찾았다는 말이 이렇게 아픈데, 그래도 아무 말 없이 잊히는 것보다는 낫네. 내가 돌아오면 먼저 그 얘기 물어볼 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_002","speaker":"각청","text":"물어봐. 내가 다른 일을 하고 있더라도 지나가지 말고. 네가 했던 증언을 기억하지 못하는 것과 지금 네가 부탁한 일을 놓치는 건 달라. 오늘 들은 일은 오늘부터 내가 맡는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_003","speaker":"","text":"그 말을 듣자 각청에게 예전 일을 다시 증명하려던 마음을 조금 내려놓았다. 그녀는 닷새를 돌려줄 수 없었지만 새로운 일을 맡을 수 있었다. 내 앞에서 살아 움직이며 자기 몫을 고르는 각청이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_004","speaker":"나","text":"그럼 나도 내 몫 하러 갈게. 남의 짐 대신 맡는 재주는 없는데, 남의 일에 끼어드는 재주만 자꾸 느네. 이번에는 끝까지 끼어들고 돌아올 테니까 저쪽 자리 하나는 비워 둬.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_005","speaker":"각청","text":"돌아와서 쉬려면 자리는 있어. 그리고 너한테도 할 일이 생겼다고 다치지 않을 몸이 생긴 건 아니야. 무리하면 물러서.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_086","text":"각청이 해안의 대피 상황을 보러 돌아서는 동안 황금옥 쪽 병사들이 앞장섰다. 길목은 제한된 조사 인원만 통과하도록 열렸다. 익숙한 포대와 수레들이 길옆으로 물러나 있었다. 이번에는 사람이 먼저 빠져나간 자리를 지나고 있다는 것을 확인했다."},{"k":"keep","id":"ISK_L03_K2_087","text":"황금옥으로 향하는 길은 생각보다 길었다. 어느 누구도 짐꾼처럼 걸음이 짧다고 놀리지 않았다. 그 침묵이 더 낯설어 나는 길의 모양을 외우기 시작했다. 돌아올 때 헤매지 않는 것부터 하기로 했다."},{"k":"line","id":"PRO_L03K2_golden_001","speaker":"","text":"황금옥 앞에서는 일꾼들이 밖으로 빠져나오고 있었다. 안쪽에서 충격이 난 뒤 주 출입문이 비틀려 관리 통로로 우회했다는 말이었다. 길목을 보았다. 큰 수레를 세우면 문을 가릴 위치였다. 닷새 동안 물자 구역에서 익힌 감각이 엉뚱한 곳에서 도움이 되었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_002","speaker":"나","text":"저 수레는 문 앞에서 옆으로 빼 주세요. 사람이 급하게 나오면 바퀴에 걸리겠어요. 저는 안으로 들어가겠습니다. 타르탈리아가 나오면 앞을 막고 싸우려 하지 말고 사람들 쪽으로 못 가게 떨어져 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_003","speaker":"호위 병사","text":"관리 통로로 들어가셨다고 전하겠습니다. 안에서 다시 길이 막히면 무리해서 넘어가지 마십시오. 돌아올 수 있는 틈이 있을 때 돌아오셔야 합니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_091","text":"주머니에 무엇이 있는지 무의식중에 확인하다 손을 뗐다. 설산에서 본 구슬은 여기 없었다. 꺼내서 앞길을 바꾸어 줄 물건도 없었다. 무기를 잡고 통로로 들어갔다."},{"k":"line","id":"PRO_L03K2_golden_004","speaker":"","text":"넓은 공간에 이르자 발소리가 길게 돌아왔다. 모락스의 시신은 보이지 않았다. 대신 타르탈리아가 서 있었다. 내가 상상한 상대는 무언가를 찾고 있거나 뜻대로 되지 않아 불쾌해하고 있을 것 같았다. 눈앞의 남자는 빈 공간에서 기다리는 데 익숙해 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_005","speaker":"타르탈리아","text":"들어오기 전에 바깥을 제법 정리했더군. 여기서 나갈 때도 그 길을 쓸 생각인가 봐. 준비성이 좋은 손님은 싫지 않아. 날 찾아온 거지?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K2_golden_006","options":[{"label":"그래. 제군의 시신을 찾으러 온 거면 헛걸음한 것 같네. 나도 없어서 여기까지 왔거든. 신의 심장을 찾겠다고 다른 일을 벌일 생각이면 그것부터 접고.","id":"PRO_L03K2_golden_007","items":[{"k":"line","id":"PRO_L03K2_golden_008","speaker":"타르탈리아","text":"찾으러 온 사람이 둘이라. 그럼 너는 나에게서 무엇을 얻으려고 싸울 셈이지? 이미 없다는 것을 확인한 물건? 아니면 네가 생각한 순서대로 흘러가지 않는 일의 답?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"나도 시신을 못 찾아서 왔어. 네가 가져갔다면 소재를 묻겠지만, 아니라면 여기서 무슨 계획을 세웠는지 말해.","id":"PRO_L03K2_golden_009","items":[{"k":"line","id":"PRO_L03K2_golden_010","speaker":"타르탈리아","text":"내 계획과 네가 찾는 답을 한꺼번에 묻는군. 그럼 너는 나에게서 무엇을 얻으려고 싸울 셈이지? 이미 없다는 것을 확인한 물건? 아니면 네가 생각한 순서대로 흘러가지 않는 일의 답?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K2_golden_011","speaker":"","text":"미간을 좁혔다. 타르탈리아는 자신을 아는지 묻지 않았다. 시신과 신의 심장을 동시에 들은 사람의 얼굴치고는 놀라움이 너무 적었다. 그는 이곳에 온 이유를 따지는 대신 내가 어디까지 버틸지 보고 있는 것처럼 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_012","speaker":"나","text":"질문 잘하네. 그럼 내 질문에도 답해 봐. 너, 지금 싸우고 싶어? 내가 아는 너라면 여기까지 온 상대를 보고 좀 더 들떠야 할 것 같은데. 아까부터 내가 뭘 할지만 기다리고 있잖아.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_013","speaker":"타르탈리아","text":"네가 아는 나라는 말이 재미있군. 나는 아직 네 이야기를 많이 듣지 못했는데. 서로 아는 양이 다른 만남도 있겠지. 네가 그렇게 확신한다면 먼저 보여 줘. 내가 어떤 반응을 할지도 알고 있을 테니까.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_014","speaker":"","text":"내가 먼저 한 발 움직이자 타르탈리아의 시선은 무기가 아니라 발이 놓인 곳으로 잠깐 내려갔다. 전투에서 위치를 보는 것은 이상할 일이 아니었다. 그런데 그 짧은 시선이 이상하게 오래 남았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_015","speaker":"나","text":"밖에 네 사람들이 있었어. 안쪽에서 연락이 끊겼다는데 찾으러 나갈 생각은 없어? 난 여기까지 오는 길에 남의 짐꾼 한 사람 못 찾았다는 얘기만 들었는데도 계속 걸렸거든.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_016","speaker":"타르탈리아","text":"그래서 네가 여기 온 건 아니잖아. 못 찾은 사람 이야기로 시간을 벌려고? 네가 막겠다고 한 일을 막아 봐. 다른 사람은 네가 돌아간 다음에 찾아도 늦지 않을지 모르지.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_017","speaker":"","text":"손에 힘이 들어갔다. 일부러 도발하고 흡족해하는 기색도 없었다. 그저 상대가 아파하는 지점을 짚고 다음 반응을 기다렸다. 지금 필요한 것은 낯선 이유를 맞히는 일이 아니었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K2_golden_018","options":[{"label":"그 사람을 못 찾은 건 네가 입에 올릴 농담거리가 아니야. 나도 내가 아는 너를 앞세워 방심할 생각은 접을게. 지금 내 앞에서 하는 짓만 보고 상대하겠어.","id":"PRO_L03K2_golden_019","items":[{"k":"line","id":"PRO_L03K2_golden_020","speaker":"타르탈리아","text":"그편이 너에게도 편하겠지. 기억해 둔 상대와 눈앞의 상대를 번갈아 보면 손이 늦어질 테니까. 이제 네가 멈추려는 일이 무엇인지 행동으로 보여 줘.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"그래, 돌아가서 찾아야지. 그러려면 여기서 너하고 말만 주고받을 수는 없겠네. 문 앞에 수레 치워 달라고 한 이유가 도망갈 때 걸리기 싫어서만은 아니거든.","id":"PRO_L03K2_golden_021","items":[{"k":"line","id":"PRO_L03K2_golden_022","speaker":"타르탈리아","text":"돌아갈 자리를 남겨 둔 건 좋은 생각이야. 그 자리를 다시 밟을 수 있을지는 네가 얼마나 움직이느냐에 달렸겠지. 시작하자.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K2_golden_023","speaker":"","text":"타르탈리아가 손을 움직였고 물빛 날이 번쩍였다. 바닥을 박차며 몸을 피했다. 칼날이 지나간 기둥에서 돌가루가 떨어졌다. 무언가 다르다는 감각을 지우지 않은 채, 눈앞의 공격을 상대해야 했다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_110","text":"황금옥 내부에서 타르탈리아와의 전투가 시작된다."},{"k":"line","id":"PRO_L03K2_golden_024","speaker":"","text":"몇 번이나 넘어질 뻔하며 뒤로 물러났다. 내가 디딘 금 간 돌판을 타르탈리아도 피하려 몸을 틀었다. 무기를 고쳐 쥐자 손끝이 아팠다. 바깥의 사람들을 떠올리고서야 한 걸음 움직였다. 멋있는 싸움은 아니었다. 아직 여기서 끝낼 수 없다는 고집만 남아 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_025","speaker":"나","text":"이제 그만해. 네가 다음에 뭘 하려고 했든 여기서 끝내. 나는 돌아가서 찾을 사람이 있어. 또 누군가가 없어졌다는 말만 듣고 서 있을 생각은 없으니까.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_026","speaker":"","text":"타르탈리아는 답하지 않았다. 상대의 시선이 내 무기 끝에서 벗어났지만, 무엇을 보았는지 확인하기 전에 몸이 앞으로 나갔다. 마지막 틈이라고 판단했다. 결정타를 날리려 팔을 뻗는 순간, 발밑의 감각이 통째로 내려앉았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_027","speaker":"","text":"기둥의 장식이 떨어지며 바닥을 부쉈고, 천장을 가로지르는 들보가 뒤틀렸다. 출구 방향을 기억해 몸을 틀었다. 바깥의 수레를 치워 두었다는 생각이 스쳤다. 길은 열어 두었다고 생각했다. 그러나 길이 남아 있어도 그 길에 닿을 시간이 남은 것은 아니었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_028","speaker":"나","text":"황금옥 무너져요! 문에서 떨어져! 안으로 들어오지 마요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_116","text":"무너진 돌이 어깨를 때렸고 다리가 꺾였다. 이어 떨어진 들보가 몸을 덮쳤다. 타르탈리아는 먼지에 가려 보이지 않았다. 남의 몸을 들어 올리려다 놓쳤던 팔이 이번에는 제 몸 위의 무게를 밀어내지 못했다. 황금옥이 내려앉으며 나를 잔해 아래에 묻었다."},{"k":"keep","id":"ISK_L03_K2_END","text":"내가 무너진 황금옥에 깔리는 순간에서 멈춘다. 구조 여부와 부상 상태는 아직 밝혀지지 않는다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_0","text":"자네! 살아 있었군. 물자 구역에 짐만 남았다고 해서 얼마나… 아저씨는? 아저씨는 같이 안 왔나?"},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_1","text":"행추, 숨 좀 쉬고 말해. 각청, 이 사람은 내가 알아. 고운각에서 회수한 인계표에 이 사람과 짐꾼 둘 다 적혀 있어. 네가 기억 못 하는 건 네 잘못이 아니지만, 이 사람이 없는 일을 꾸며 낸 것도 아니야."},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_2","text":"……두 사람이 이 사람을 안다는 거지. 알겠어. 지우지 않아. 찾을 사람을 늘리겠어. 너는 선인께 무슨 말을 했는지 계속 설명해 줘."},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_3","text":"……행추, 연비. 아저씨는 못 찾았어. 내가 두고 왔어. 찾았다는 소식 오면 나부터 불러 줘. 그 사람 밥 먹었는지도 물어봐 주고."}]},{"id":"ISK_L04_K1","entry":"ISK_L04_K1_001","items":[{"k":"keep","id":"ISK_L04_K1_001","hold":true,"text":"눈을 떴는지 감고 있는지 한동안 알 수 없었다. 입 안에 먼지가 씹혔고 숨을 들이마실 때마다 어깨가 아팠다. 들보는 기울어진 석재에 받쳐 있었고, 그 아래 생긴 비좁은 틈에 등이 눌려 있었다. 무게를 다 받았다면 버티지 못했을 것이다. 숨이 드나들 공간이 있다는 사실부터 붙잡았다."},{"k":"line","id":"PRO_L04K1_rubble_001","speaker":"","text":"팔을 비틀어 손목을 만졌다. 박동이 있었다. 각청에게서 찾지 못했던 것을 내 몸에서 찾자 안심과 죄책감이 함께 올라왔다. 어둠 속으로 귀를 기울였다. 타르탈리아가 움직이는 소리는 들리지 않았다. 대신 멀리서 돌 구르는 소리와 사람의 목소리가 났다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_002","speaker":"나","text":"여기 사람 있어요! 안쪽 관리 통로로 들어간 사람, 아직 살아 있습니다!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_003","speaker":"호위 병사","text":"들립니다! 목소리 나는 곳을 찾았으니 계속 소리 지르지 마십시오. 앞이 막혔습니다. 손은 움직입니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_004","options":[{"label":"손은 움직여요. 그런데 위에 들보가 걸려 있어요. 돌부터 막 치우지 마요. 이거 내려앉으면 대답 못 해요.","id":"PRO_L04K1_rubble_005","items":[{"k":"line","id":"PRO_L04K1_rubble_006","speaker":"호위 병사","text":"바깥에서도 들보가 보입니다. 먼저 받침을 넣겠습니다. 안에서는 손이 닿는 작은 돌만 옆으로 밀어 주십시오. 큰 것은 건드리지 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"어깨하고 허벅지가 눌렸어요. 손은 움직이고 다리도 감각은 있어요. 어떻게 하면 돼요?","id":"PRO_L04K1_rubble_007","items":[{"k":"line","id":"PRO_L04K1_rubble_008","speaker":"호위 병사","text":"그 정도면 됩니다. 억지로 몸을 빼지 마십시오. 바깥에서 받침을 넣는 동안, 손이 닿는 작은 돌만 옆으로 밀어 숨 쉴 틈을 넓혀 두세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"thru","id":"ISK_L04_K1_001"},{"k":"line","id":"PRO_L04K1_rubble_009","speaker":"","text":"틈으로 빛이 들어왔을 때 병사는 곧장 팔을 잡아당기지 않았다. 얼굴을 보며 숨을 쉬는지 묻고, 몸이 어디에 걸렸는지 살핀 뒤 다른 이들과 무게를 나누었다. 나를 찾는 목소리가 실제로 돌아왔다. 그제야 내가 구조를 기다리는 사람이 되었음을 알았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_010","speaker":"나","text":"옆에 있던 남자는 봤습니까? 붉은 머리, 회색 옷. 저랑 싸우다가 같이 안에 있었어요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_011","speaker":"호위 병사","text":"바깥으로 나오는 사람은 보지 못했습니다. 지금 열린 틈에서도 당신 외에는 보이지 않습니다. 안쪽 전체를 확인한 건 아니니 단정할 수는 없습니다. 먼저 당신부터 꺼냅니다. 고개를 이쪽으로 돌리십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K1_008","text":"몸이 잔해에서 빠져나오자 바람이 젖은 옷 안으로 들어왔다. 시원하다고 생각하기도 전에 통증이 밀려왔다. 무릎을 세우려다 옆으로 기울었고 병사가 받쳐 주었다. 무너진 황금옥은 내가 들어갔던 건물과 다른 모양이었다. 열린 틈과 무너진 바닥 어디에도 타르탈리아는 보이지 않았다."},{"k":"line","id":"PRO_L04K1_rubble_012","speaker":"군의관","text":"제 말을 들으면서 손가락을 펴 보세요. 이번에는 발을 움직이고요. 어깨와 허벅지가 심하게 눌렸지만 지금 보이는 출혈은 먼저 막을 수 있습니다. 숨이 더 차거나 가슴이 아프면 바로 말해야 합니다. 멀쩡히 말한다고 안쪽까지 괜찮다는 뜻은 아닙니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_013","options":[{"label":"치료받겠습니다. 저 혼자 멀쩡하다고 우겨 봐야 걷다가 또 업혀 갈 것 같네요. 움직이라는 때 움직이고, 멈추라는 때 멈출게요.","keep":"ISK_L04_K1_010","items":[{"k":"line","id":"PRO_L04K1_rubble_014","speaker":"군의관","text":"그 말이면 됩니다. 처치 자리를 만들겠습니다. 아픈 곳은 참지 말고 바로 말하세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K1_011","text":"병사들이 구조 지점 옆으로 구호 물자를 가져왔다. 군의관은 내 동의를 듣고 처치 자리를 마련했다. 호흡과 의식이 확인되었고, 나를 누르던 무게도 제거되었다. 어떻게 살아남았는지를 다 설명할 수는 없어도, 지금 치료할 사람이 이곳에 있다는 것은 분명했다."},{"k":"line","id":"PRO_L04K1_rubble_015","speaker":"","text":"군의관은 찢어진 옷을 걷어 상처를 씻고 눌러 지혈한 뒤 붕대를 감았다. 혼자 서 보겠다는 말을 삼켰다. 구해 달라고 외친 지 얼마 되지도 않았는데, 이제 괜찮은 사람인 척해서 구조한 이들의 수고를 늘리고 싶지는 않았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_016","options":[{"label":"저 살아 있는 거 맞죠? 웃긴 질문인 건 아는데, 요 며칠 제가 확인한 것들이 자꾸 뒤집혀서요.","id":"PRO_L04K1_rubble_017","items":[{"k":"line","id":"PRO_L04K1_rubble_018","speaker":"군의관","text":"지금 숨을 쉬고, 제 질문에 대답하고, 상처에서 피가 납니다. 여기까지는 제가 확인했습니다. 살아 있다는 것과 당장 뛰어도 된다는 것은 다른 말이니, 확인한 만큼만 움직입시다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"붕대 감는 솜씨가 너무 익숙해서 감사하면서도 좀 무섭네요. 혹시 조금 덜 아프게 믿을 수는 없을까요?","id":"PRO_L04K1_rubble_019","items":[{"k":"line","id":"PRO_L04K1_rubble_020","speaker":"군의관","text":"아프다고 말하는 건 잘하셨습니다. 압박을 조금 조절하겠습니다. 다만 출혈을 막을 만큼은 감아야 하니 참을 부분도 있습니다. 이를 악물고 괜찮다고만 하는 환자보다는 도와드리기 쉽군요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K1_019","text":"처치가 끝나기 전에 바다 쪽에서 소리가 왔다. 바람 소리와 달랐다. 먼 곳의 하늘이 검게 꺾이고, 수평선 위로 거대한 물줄기가 솟았다. 보고하러 달려온 병사의 얼굴을 본 군의관이 설명을 멈췄다. 바다에 나타난 것이 항구 쪽으로 움직이고 있었다. 선인들과 칠성이 이미 방어에 들어갔다는 말이 이어졌다."},{"k":"line","id":"PRO_L04K1_rubble_021","speaker":"나","text":"오셀이야. 황금옥에서 막으려고 했는데 결국 나왔어. 타르탈리아는 어디 갔는지도 모르겠고… 아니, 지금 그걸 찾고 앉아 있을 수는 없네. 군옥각으로 가야 합니다. 응광한테 제가 살아 나왔고, 황금옥은 무너졌다고 전해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_022","speaker":"군의관","text":"걸을 수 있는지 확인한 것이 전투를 허락했다는 뜻은 아닙니다. 혼자 달려가시면 도중에 다시 업고 와야 합니다. 병사들과 함께 움직이세요. 호흡이 바뀌면 바로 멈추십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_023","speaker":"","text":"말을 들으며 황금옥을 돌아보았다. 내가 기억하는 타르탈리아는 싸움을 즐겼다. 안에서 만난 상대는 마지막 순간까지 무엇이 끝나는지를 기다리는 듯했다. 그 차이가 마음을 잡아당겼지만, 바다 쪽에서는 더 큰 소리가 울렸다. 의문은 살아서 나중에 붙잡아야 했다. 병사가 내민 팔을 붙들었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K1_023","text":"호위대는 구조 지점을 표시하고 추가 수색 인원에게 인계했다. 안전한 길까지 부축받고, 완만한 구간에서는 직접 걸었다. 먼 바다에서 솟아난 형체를 보았다. 이야기 속에서 알고 있던 이름이 실제 도시보다 크게 일어섰다. 미리 경고했다는 사실이 그 크기를 줄여 주지는 않았다."},{"k":"keep","id":"ISK_L04_K1_024","text":"항구로 돌아오는 길에는 대피한 사람들이 이어졌다. 병사들이 어느 쪽을 비워 달라고 외치면 사람들은 움직였다. 그 작은 질서가 무너진 도시를 붙들고 있었다. 한참 뒤 방어 인원이 오가는 항구의 지정 집결지에 닿았다."},{"k":"line","id":"PRO_L04K1_harbor_001","speaker":"각청","text":"살아 돌아왔네. 황금옥이 무너졌다는 보고가 먼저 와서, 사람을 더 보내려던 참이야. 왜 그렇게 서 있어? 다친 쪽에 힘을 덜 줘. 보고는 앉아서 해도 들려.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_002","speaker":"나","text":"돌아오면 기다리겠다고 했잖아. 그 약속 지키러 왔는데 시작부터 자세 지적을 받네. 타르탈리아와 싸웠고, 끝낼 수 있을 것 같던 순간 건물이 무너졌어. 나는 병사들이 꺼냈고, 그 사람은 못 찾았대. 시신도 안에선 못 봤어. 바다를 막는 쪽에 나도 보태 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_003","speaker":"각청","text":"어디에 붙일지는 네 몸 상태부터 보고 정할 거야. 여기서 쓰러지면 널 지키느라 또 사람이 빠져. 싸울 수 있다는 말만 하지 말고, 팔을 들었을 때 어디가 아픈지 말해.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_004","speaker":"","text":"팔을 천천히 들자 붕대가 당겼다. 각청은 그 범위를 보고 칼을 크게 휘두르는 자리 대신 방어선 안쪽을 가리켰다. 부상자를 옮기고, 장치로 이어지는 길을 막는 자리였다. 바다의 거대한 몸을 향해 뛰어들 자리는 처음부터 누구도 내주지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_harbor_005","options":[{"label":"뒤쪽도 괜찮아. 앞으로 나가야 도와주는 거라는 고집은 황금옥 밑에 놓고 왔어. 대신 위험해지면 말해 줘.","id":"PRO_L04K1_harbor_006","items":[{"k":"line","id":"PRO_L04K1_harbor_007","speaker":"각청","text":"네가 알고 있다는 결말은 들었어. 지금 어디로 물러설지는 내 지시를 들어. 살려 놓은 사람을 다시 잃고 싶지 않으니까. 올라가는 동안에는 난간을 잡고, 손에 힘 빠지면 옆 사람을 불러.","map":"MAP_LIYUE_HARBOR"}]},{"label":"솔직히 앞에 서고 싶었는데, 네가 하라는 대로 할게. 물통 돌려주러 온 사람이 또 깔리면 체면이 없잖아.","id":"PRO_L04K1_harbor_008","items":[{"k":"line","id":"PRO_L04K1_harbor_009","speaker":"각청","text":"체면 때문에라도 말을 들어 준다면 그걸로 됐어. 올라가는 동안에는 난간을 잡고, 손에 힘 빠지면 옆 사람을 불러. 살려 놓은 사람을 다시 잃고 싶지 않아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_031","text":"방어 지점으로 가는 통로가 열렸다. 일반 대피 인원과 방어에 합류하는 인원이 갈라졌고, 나는 각청이 지정한 조를 따라 움직였다."},{"k":"keep","id":"ISK_L04_K1_032","text":"군옥각에 오르는 길은 전과 달랐다. 아래에서는 마지막 대피 인원이 길을 건넜고, 위에서는 선인들의 힘이 바다를 향해 뻗었다. 발을 디뎠을 때 그곳은 차를 마시며 지도를 펼쳤던 집이 아니라 도시 앞에 놓인 방어 진지가 되어 있었다."},{"k":"line","id":"PRO_L04K1_osial_001","speaker":"응광","text":"황금옥에서 바로 내 집까지 무너뜨리러 온 건 아니겠지? 살아 돌아온 건 환영하지만, 저 바다를 보니 환영할 형편이 아니네. 네가 알려 준 것 덕분에 대피를 먼저 시작했어. 이제 그 시간을 더 벌어야 해.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_002","options":[{"label":"앞 건물은 제가 부순 걸로 계산하지 말아 주세요. 다음 건물도 가능하면 남기고 싶습니다. 제가 본 이야기보다 일찍 움직였으니 뭐라도 달라졌으면 좋겠어요.","id":"PRO_L04K1_osial_003","items":[{"k":"line","id":"PRO_L04K1_osial_004","speaker":"응광","text":"달라진 건 이미 있어. 아래에 남을 뻔한 사람들이 빠져나갔고, 이곳에 있던 일꾼들도 먼저 내려보냈어. 하지만 상대가 작아지지는 않았네. 선인들이 전면을 맡는 동안 뒤로 들어오는 적을 막아 줘.","map":"MAP_OSIAL_BATTLE"}]},{"label":"어디를 맡으면 앞에서 싸우는 사람들 손이 덜 묶일까요? 제가 안다고 했던 순서대로 흘러가지도 않으니까, 지금 여기서 필요한 일부터 듣겠습니다.","id":"PRO_L04K1_osial_005","items":[{"k":"line","id":"PRO_L04K1_osial_006","speaker":"응광","text":"그렇게 물어 주는 편이 지금은 훨씬 도움이 돼. 선인들이 전면을 맡는 동안 뒤로 들어오는 적을 막아 줘. 그들이 힘을 돌려야 하면 바다를 향한 방어가 비어.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_007","speaker":"","text":"류운차풍진군이 고개를 돌렸다. 황금옥에서 깔렸다 나온 몸으로 또 높은 곳에 섰다는 말을 하려는 듯하다가, 다친 어깨와 그 옆에 선 병사를 보고 말을 줄였다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_008","speaker":"류운차풍진군","text":"살아 돌아온 것은 잘했네. 그렇다고 기둥 아래서 버텼다는 이유로 파도 앞에서도 버틸 몸이 되었다고 착각하지 말게. 장치 뒤쪽의 연결로를 지키게. 이 몸이 정면을 돌보는 동안 그곳에 발을 들이는 것들을 막아야 하네.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_009","speaker":"나","text":"알겠습니다. 저기 거대한 머리랑 눈 마주칠 생각은 없어요. 제 몸하고 크기 비교해 보니까 협상할 여지가 없더라고요. 이 길을 지키고, 다친 사람은 안쪽으로 빼겠습니다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_010","speaker":"","text":"바다에서 솟은 물줄기가 방어의 빛을 때렸다. 허리를 낮추고 난간을 잡았다. 뒤쪽으로 스며든 습격자들이 좁은 연결로를 향해 달려왔다. 각청이 앞의 공격을 끊어 냈고, 나는 내가 맡은 틈으로 다가오는 적을 향해 무기를 들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K1_040","text":"오셀에 맞선 공동 방어가 이어지는 동안, 군옥각 후방 연결로를 지키는 방어전이 시작된다."},{"k":"line","id":"PRO_L04K1_osial_011","speaker":"","text":"연결로에 밀려들던 적의 마지막 공격이 끊겼다. 뒤로 물러나는 사람을 부축하고 난간 안쪽으로 옮겼다. 길은 지켰다. 그러나 바다의 형체가 다시 몸을 일으키자 방어 장치 위로 균열이 번졌고, 선인들이 힘을 밀어 넣던 자리가 통째로 흔들렸다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_012","speaker":"각청","text":"뒤쪽 인원부터 내려보내! 장치를 붙들려고 남지 마. 사람 다 나갔는지 먼저 확인해. 너도 그 부상자 데리고 안쪽으로 와!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_013","speaker":"나","text":"이 사람 다리에 힘이 안 들어가. 반대쪽 어깨 좀 잡아 줘! 하나씩 옮기면 되니까 밀지 말고!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_014","speaker":"","text":"나와 병사 하나가 부상자를 사이에 두고 옮겼다. 피로해진 팔은 곧 떨렸지만 놓지 않았다. 각청이 다가와 무게를 받아 주자 숨이 터졌다. 전에는 손에 남은 사람을 놓고 도망쳤다. 지금은 누군가가 그 무게를 나누어 들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_015","speaker":"","text":"응광은 무너진 방어 지점과 바다를 번갈아 보았다. 류운차풍진군은 장치를 다시 이어도 오래 버티기 어렵다고 말했다. 응광은 창 안쪽을 한 번 보았다. 급히 챙겨 나온 문서와 물건들이 모여 있었지만 모든 것을 들고 나갈 수는 없었다. 그녀는 더 가져오라는 명령을 내리지 않았다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_016","speaker":"응광","text":"이제 결정할 때네. 군옥각을 포기하겠어. 바다에 떨어뜨려 그 틈을 막을 거야. 남은 사람을 모두 옮겨 줘. 내가 아끼는 것 때문에 누군가 마지막까지 이곳에 남는 일은 없도록.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_017","options":[{"label":"정말 다른 방법이 없는 겁니까? 제가 먼저 말했던 건 알아요. 그런데 당신이 지켜 온 걸 직접 보니까, 알고 있었으니 괜찮다는 말은 못 하겠네요.","id":"PRO_L04K1_osial_018","items":[{"k":"line","id":"PRO_L04K1_osial_019","speaker":"응광","text":"괜찮을 필요는 없어. 아깝고, 화도 나고, 다시 만들 생각을 하면 벌써 손이 많이 가겠지. 그래도 아래 도시를 남길 수 있다면 내 선택은 분명해. 네가 말했기 때문이 아니라 내가 지금 보고 결정한 거야. 그러니 내 표정을 살필 시간에 사람을 옮겨.","map":"MAP_OSIAL_BATTLE"}]},{"label":"……알겠습니다. 제가 그 얘기를 먼저 꺼낸 사람이라서, 지금은 아무 말도 안 하는 게 예의 같네요. 사람부터 옮길게요.","id":"PRO_L04K1_osial_020","items":[{"k":"line","id":"PRO_L04K1_osial_021","speaker":"응광","text":"그 예의는 받아 두지. 하지만 네가 말했기 때문에 하는 결정이 아니야. 내가 지금 보고 정한 거야. 그러니 내 표정을 살필 시간에 사람을 옮겨.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_022","speaker":"류운차풍진군","text":"이 몸이 길을 열겠네. 소, 남은 자들을 살피게. 칠성의 결정에 맞추어 힘을 모으겠어. 이 건물을 떨어뜨리는 것만으로 끝내서는 안 되니, 닿는 순간까지 빈틈을 남기지 말게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_023","speaker":"","text":"각청은 마지막 명단을 확인하는 사람 곁에서 직접 머릿수를 세었다. 난간에 매달려 있던 천을 걷어 발이 걸리지 않게 한 뒤, 뒤를 돌아보며 따라오는 사람을 재촉했다. 비 새는 천막을 둘이 들어 올리던 일이 떠올랐다. 이번에는 물을 빼는 대신 집을 두고 떠나야 했다.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_024","options":[{"label":"전에 천막에서는 왼쪽을 당기라더니 오늘은 오른쪽으로 빠지라네. 알았어, 이번에도 네 말 들을게. 그 대신 네가 마지막까지 남아서 혼자 확인하지는 마.","id":"PRO_L04K1_osial_025","items":[{"k":"line","id":"PRO_L04K1_osial_026","speaker":"각청","text":"천막 얘기는 모르겠지만, 이번에는 네가 먼저 가면 나도 따라갈 거야. 여기 남은 사람은 확인했어. 자꾸 뒤돌아보다가 발 헛디디지 마.","map":"MAP_OSIAL_BATTLE"}]},{"label":"남은 사람 없지? 내가 한 번 놓고 나온 사람을 자꾸 다시 찾는 버릇이 생겨서 그래. 너 살아 있는 건 이번에는 놓치고 싶지 않아.","id":"PRO_L04K1_osial_027","items":[{"k":"line","id":"PRO_L04K1_osial_028","speaker":"각청","text":"지금 여기 남은 인원은 확인했어. 네가 모든 사람을 혼자 기억해야만 하는 자리는 아니야. 병사들도, 나도 보고 있으니까 그쪽 발판부터 건너. 내가 바로 뒤에 있어.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_029","speaker":"","text":"발판이 기울자 몸을 낮췄다. 소가 마지막으로 주변을 살핀 뒤 남은 이들을 이끌었고, 선인들의 힘이 부서지는 가장자리에서 사람들을 떼어 냈다. 발밑에 있던 군옥각이 멀어졌다. 응광은 마지막까지 바다를 보며 힘을 내렸고, 거대한 건물이 빛을 안은 채 아래로 향했다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_030","speaker":"","text":"바다와 하늘 사이가 눈부시게 터졌다. 조금 전 차가 놓여 있던 방, 지도가 펼쳐졌던 탁자, 손님에게 비워 주었던 의자가 모두 빛과 물 아래로 사라졌다. 오셀을 향해 모인 힘이 바다를 누르자 솟아 있던 거대한 형체도 그 아래로 가라앉았다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K1_059","text":"안전한 지점에 내려선 뒤에도 다리가 흔들렸다. 군옥각은 돌아오지 않았다. 사람들은 환호하다가 누가 없는지 확인했고, 누군가는 앉아서 울었다. 응광을 찾았다. 그녀는 자신이 잃은 쪽보다 사람들이 모인 쪽을 먼저 보고 있었다."},{"k":"keep","id":"ISK_L04_K1_060","text":"해안의 감시 인원이 바다의 거대한 위협이 가라앉았다는 보고를 전했다. 군옥각을 희생해 마지막 틈을 막았고, 선인과 칠성이 함께 지켜 낸 도시가 뒤에 남았다."},{"k":"line","id":"PRO_L04K1_osial_031","speaker":"나","text":"일이 끝나면 같이 밥 한 번 먹고 싶습니다. 지금 이런 얘기가 이상하겠지만… 저기 있던 식탁은 잃었어도 같이 앉을 자리까지 없어진 건 아니라고 생각하고 싶어서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_osial_032","speaker":"응광","text":"밥 한 끼 먹을 곳도 남기지 못했으면 오늘 선택은 실패였겠지. 다행히 아래에 도시가 남았네. 너는 먼저 치료를 받아. 손님을 초대해 놓고 식탁에서 쓰러지게 만드는 건 내 취향이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_osial_033","speaker":"","text":"웃으려다가 갈비뼈 근처가 당겨 얼굴을 찡그렸다. 각청이 그 표정을 놓치지 않았다. 그녀는 군의관을 불렀고, 나는 이번에는 바다를 핑계로 일어서지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_064","text":"대피소의 치료 구역에서 군의관은 젖은 붕대를 풀었다. 멍이 번진 부위를 다시 살피고 상처를 씻었으며, 호흡할 때 통증이 생기는지 물었다. 침상에 누워 처음으로 천장이 움직이지 않는다는 사실을 오래 바라보았다."},{"k":"line","id":"PRO_L04K1_rest_001","speaker":"군의관","text":"상처가 다시 벌어진 곳은 처치했습니다. 오늘은 쉬십시오. 밤에 숨이 가빠지거나 의식이 흐려지면 곁의 사람을 부르세요. 내일 상태를 다시 보고 걷는 범위를 늘리겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_002","speaker":"나","text":"걷는 범위를 남이 정해 주는 생활에 아주 익숙해지고 있네요. 이번에는 도시를 구해야 한다는 핑계도 다 써 버렸으니까, 얌전히 누워 있을게요. 물 좀 가까이 놔 주실 수 있습니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_003","speaker":"","text":"그날 밤은 짧게 끊겼다. 돌이 쏟아지는 소리에 놀라 깼다고 생각했지만 실제로는 옆 침상의 사람이 물그릇을 떨어뜨린 소리였다. 내 손목을 찾았다가 멈췄다. 방 안에는 숨 쉬는 사람이 여럿 있었다. 모두의 맥박을 확인하지 않아도 같은 밤을 보내는 소리가 들렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_068","text":"이틀 동안 치료와 휴식이 이어졌다. 통증과 피로는 남았지만 다시 일어서서 식사를 하러 갈 수 있었다. 그동안 해안의 급한 정리는 끝났고, 항구는 피해 구역을 제외한 통행을 순서대로 되돌리고 있었다."},{"k":"line","id":"PRO_L04K1_rest_004","speaker":"","text":"각청이 찾아왔을 때 나는 침상 가장자리에 앉아 밥을 먹고 있었다. 그녀는 빈 그릇부터 확인하더니 오늘 열리는 길을 설명했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_005","speaker":"각청","text":"오늘부터 리월항의 일반 봉쇄를 해제해. 황금옥 잔해와 해안의 파손 구역만 계속 막아 둘 거야. 멀리 가지 말라는 건 군의관의 지시니까 내가 취소해 줄 수 없고. 네가 다시 사라졌다는 보고까지 받고 싶지는 않아.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_rest_006","options":[{"label":"보고 없이 뛰어나갈 생각은 없으니까 너무 수상한 환자처럼 보지 마. 그런데 너, 오늘 내가 뭘 먹었는지는 기억해 줄 수 있지? 나중에 똑같은 것만 가져오지 말라고 미리 부탁할 기회라도 있게.","id":"PRO_L04K1_rest_007","items":[{"k":"line","id":"PRO_L04K1_rest_008","speaker":"각청","text":"오늘 일은 기억해. 네가 빈 그릇을 앞에 두고 다음 메뉴부터 요구한 것도. 전에 네가 말한 닷새는 아직 떠오르지 않아. 그걸 대신 채워 주지는 못하겠지만, 지금부터 네가 자꾸 얄미운 말 하는 건 충분히 남길 수 있겠네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"오늘 먹은 것하고 걸은 거리는 같이 기억해 두자. 지난 닷새를 억지로 떠올려 달라는 뜻은 아니야. 지금부터 남길 수 있는 게 있으면 그걸 내가 무시하고 싶지는 않아서.","id":"PRO_L04K1_rest_009","items":[{"k":"line","id":"PRO_L04K1_rest_010","speaker":"각청","text":"그건 할 수 있어. 오늘 내가 직접 본 일과 아직 떠오르지 않는 일을 따로 말해 줄게. 네가 빈 그릇을 앞에 두고 앉아 있던 것부터 시작이네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_073","text":"그 대답을 듣고 나는 소리 없이 웃었다. 각청도 아주 잠깐 입가를 움직였다. 둘이 같은 일을 기억하며 웃는 순간이 새로 생겼다. 사라진 닷새를 돌려받은 것은 아니었다. 그래도 잃은 시간만 세느라 그 뒤에 생긴 시간을 놓칠 필요는 없었다."},{"k":"keep","id":"ISK_L04_K1_074","text":"며칠 전 지도를 펼쳤던 이들이 이번에는 땅 위의 임시 집무 공간에 모였다. 응광은 다른 사람의 책상에서도 자기 물건을 쓰는 것처럼 자연스러웠고, 류운차풍진군은 방의 낮은 처마를 잠깐 올려다보았다. 소는 열린 문 바깥에 서 있었다. 각청은 피해 보고를 마친 뒤 나에게 자리를 내주었다."},{"k":"line","id":"PRO_L04K1_council_001","speaker":"류운차풍진군","text":"군옥각이 사라졌다고 회의할 자리까지 없어지지는 않았군. 이 몸은 칠성의 판단을 가볍게 보지 않겠네. 허나 이번에 함께 막아 냈다고 해서 바다와 산의 경계를 풀어도 된다는 뜻은 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_002","speaker":"각청","text":"필요할 때 도움을 청하는 것과 평소 결정을 전부 맡기는 것은 다르다고 생각합니다. 이번에 직접 힘을 모았으니 다음에는 어떤 소식을 얼마나 빨리 전달해야 할지도 알게 됐어요. 저희가 맡은 곳에서 이상이 생기면 숨기지 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_003","speaker":"응광","text":"선인들과 사람들 사이에 남길 길이 하나 더 생긴 셈이겠죠. 같은 탁자에 앉았다고 모든 생각이 같아질 필요는 없어요. 이번에 서로가 지키려는 것을 직접 보았으니, 다음 대화는 조금 덜 돌아가도 되겠네요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_council_004","options":[{"label":"저는 산길을 덜 돌아가면 좋겠습니다. 그때 문 앞까지 올라가다가 사실 다리가 먼저 포기할 뻔했거든요. 급할 때 누구한테 말해야 하는지 이제는 좀 알겠다는 뜻입니다.","id":"PRO_L04K1_council_005","items":[{"k":"line","id":"PRO_L04K1_council_006","speaker":"류운차풍진군","text":"이 몸이 모든 방문객의 식사를 맡을 생각은 없네. 다만 제대로 소식을 가져온 사람이 문밖에서 쓰러져도 좋다는 뜻도 아니지. 다음에는 숨을 고를 여유가 있을 때 올라오게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"다음에 급히 전할 일이 생기면 문 앞에서 쓰러지기 전에 부를 방법부터 알려 주세요. 소식 전하러 왔다가 제가 구조 대상이 되는 건 서로 번거롭잖아요.","id":"PRO_L04K1_council_007","items":[{"k":"line","id":"PRO_L04K1_council_008","speaker":"류운차풍진군","text":"자신의 숨부터 살피겠다는 뜻이라면 이번에는 제법 제대로 배웠군. 급하다는 이유로 몸을 함부로 쓰는 버릇부터 고치게. 길은 이 몸이 일러 두겠네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_council_009","speaker":"","text":"농담 뒤에는 의례장의 이야기가 남았다. 각청도 응광도 모락스가 쓰러지던 순간을 되찾지 못했고, 나는 사람들의 실제 죽음을 기억했다. 도시를 구했다는 큰 결말 옆에 해결되지 않은 작은 시간이 그대로 붙어 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_010","speaker":"나","text":"바다가 잠잠해진 건 다행인데, 제가 의례에서 본 일은 아직 그대로예요. 각청이 죽었던 것도, 사람들이 한꺼번에 쓰러진 것도요. 없던 일로 넘기지는 말아 주세요. 황금옥에서 만난 타르탈리아도 제가 알던 성격과 달랐습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_011","speaker":"응광","text":"전투가 끝났다고 조사를 끝낸다는 명령은 내리지 않았어. 다만 살아 있는 사람들에게 네가 본 죽음을 날마다 증명하라고 요구할 수도 없겠지. 지금의 생활은 돌려주고, 남은 문제는 따로 추적할 거야. 네가 본 것을 다시 물어야 할 때는 사람을 보내겠어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_012","speaker":"소","text":"네 기억을 버릴 필요는 없어. 그렇다고 그 기억 때문에 지금 숨 쉬는 사람을 못 보면 안 된다. 네가 돌아올 자리를 남겨 둔 이유도 그 때문 아니었나.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_013","speaker":"","text":"소의 말을 듣고 각청 쪽을 보았다. 그녀는 고개를 끄덕여 주지 않았다. 이미 오늘의 자신으로 옆에 앉아 있었다. 그 사실을 확인하는 것으로 충분하다고 생각했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_001","speaker":"","text":"집무 공간을 나온 뒤 나는 길가의 긴 의자에 잠깐 앉았다. 멀리서 한 남자가 걸어왔다. 단정한 옷차림과 낮은 목소리가 기억 속 모습에 겹쳤다. 종려였다. 알고 있던 이름을 처음 실제로 부르게 되는 순간이었다. 반가운 지인을 대하듯 손을 흔들지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_002","speaker":"종려","text":"부상이 있는데도 오늘 여러 사람을 만났다고 들었네. 나는 왕생당의 객경, 종려라고 하네. 잠깐 함께 앉아도 괜찮겠나?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_003","speaker":"나","text":"앉으세요. 성함은 알고 있습니다. 처음 뵙는데 안다고 말하는 게 여기 와서는 자꾸 버릇이 됐네요. 어떤 분인지 안다고 생각했다가 몇 번 크게 틀렸으니, 이번에는 직접 이야기부터 듣겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_004","speaker":"종려","text":"남의 이야기를 통해 아는 것과 직접 마주한 것은 서로를 완전히 대신하지 못하지. 자네가 선인들에게 전한 경고가 도움이 되었다고 들었네. 다만 자네도 예상하지 못한 일을 많이 겪은 모양이군.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_005","options":[{"label":"도움이 됐다고는 하는데, 결국 군옥각은 사라졌어요. 황금옥도 무너졌고요. 사람들 먼저 옮긴 게 다행이라는 건 알아요. 그래도 알고 있다는 말에 제가 너무 기대 버린 것 같네요.","id":"PRO_L04K1_zhongli_006","items":[{"k":"line","id":"PRO_L04K1_zhongli_007","speaker":"종려","text":"남은 사람들을 사소한 결과로 여기지는 말게. 한 사람의 하루가 이어지는 일은 그 사람에게 결코 작은 일이 아니네. 그렇다고 잃은 것을 아쉬워하지 말라는 뜻도 아니야. 지켜 낸 것과 잃은 것을 함께 보아야 다음 선택이 가벼워지지 않겠지.","map":"MAP_LIYUE_HARBOR"}]},{"label":"제가 알고 있던 결말과 비교하느라, 오늘 실제로 도운 사람들을 자꾸 빠뜨리는 것 같아요. 그렇다고 잃은 걸 잘됐다고 말할 수도 없고요. 둘 중 하나만 골라서 정리하지 않아도 되겠죠?","id":"PRO_L04K1_zhongli_008","items":[{"k":"line","id":"PRO_L04K1_zhongli_009","speaker":"종려","text":"하나를 인정하기 위해 다른 하나를 지울 필요는 없네. 지켜 낸 것과 잃은 것을 함께 보아야 다음 선택이 가벼워지지 않겠지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_010","speaker":"","text":"종려는 군옥각이 사라진 하늘을 바라보았다. 제군이라는 호칭을 길 한가운데 던지면 곁을 지나가는 사람들의 이야기도 바뀔 수 있었다. 지금 종려가 시민들에게 어떤 이름으로 서 있는지까지 내가 결정할 수는 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_011","speaker":"나","text":"당신에게는 따로 묻고 싶은 게 있어요. 제가 알고 있는 당신의 일하고, 당신이 아직 제게 직접 말하지 않은 일. 여기서 목소리 높여 꺼내지는 않겠습니다. 조용히 이야기할 자리가 있습니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_012","speaker":"종려","text":"나도 마침 약속된 일을 마무리하러 가는 길이네. 북국은행에서 만나지. 자네가 묻고 싶은 것 가운데 답할 수 있는 것도, 답할 수 없는 것도 있을 걸세. 그 차이는 그곳에서 말해 주겠네.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_101","text":"북국은행으로 가는 길에는 다시 가게를 여는 사람들이 있었다. 은행 안으로 들어가자 종려와 시뇨라가 먼저 보였다. 그 옆에 서 있는 타르탈리아를 본 순간 발이 멈췄다. 황금옥의 먼지 속으로 사라졌던 얼굴이 너무 멀쩡하게 그곳에 있었다."},{"k":"line","id":"PRO_L04K1_zhongli_013","speaker":"시뇨라","text":"몬드에서 보았던 얼굴이군. 이번에도 손님이 앞을 가로막으려는 건가? 이곳에서 끝낼 일은 정해져 있어. 사적인 불만으로 순서를 늘리지 않았으면 좋겠네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_014","speaker":"나","text":"방해하지 않겠습니다. 당신들 사이의 계약을 제가 여기서 뒤집을 수 있다고 생각하지도 않아요. 대신 끝난 뒤에 묻고 싶은 건 묻겠습니다. 지금 저쪽에 아무렇지 않게 서 있는 사람한테도요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_015","speaker":"","text":"타르탈리아는 그 시선을 받고 눈썹을 올렸다. 낯선 적을 경계하는 것과 자신을 아는 상대를 흥미로워하는 기색이 섞여 있었다. 황금옥에서 보았던, 끝을 기다리는 듯한 눈길과 달랐다. 반사적으로 무기에 손을 댔다가 거두었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_016","speaker":"종려","text":"얼음의 여왕과 맺은 계약에 따라 약속한 것을 이행하겠네. 이것으로 나의 신의 심장은 자네가 받아 전하게 되겠지. 그 대가와 조건 역시 계약에 따라 지켜지기를 바라네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_017","speaker":"","text":"종려가 내민 신의 심장을 시뇨라가 받았다. 알고 있던 모락스와 종려의 관계가 눈앞에서 행동으로 확인되고 있었다. 거리에서는 여전히 각자의 물건 값을 흥정하는 소리가 들렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_018","speaker":"타르탈리아","text":"결국 나는 바깥에서 한참 뛰고, 마지막 이야기는 두 사람이 다 알고 있었던 거네. 종려 씨, 숨겨 둔 패가 많다는 건 알겠지만 이번에는 설명을 듣고 싶어지는군요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_019","speaker":"시뇨라","text":"모든 수를 미리 알렸어야 한다는 조항은 없었을 텐데. 맡은 일이 끝났으면 결과를 봐. 여기서 네 기분을 풀어 주는 것까지 내 역할은 아니니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_020","speaker":"","text":"타르탈리아는 불쾌한 듯 웃었다. 자신만 모른 일에 짜증을 느끼면서도 대화를 놓치지 않는 반응이었다. 그 모습에 더 불편해졌다. 낯설어서가 아니라, 이제야 내가 기억하던 타르탈리아와 닮아 보였기 때문이다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_021","speaker":"나","text":"종려 씨, 왜 그런 계약을 맺은 겁니까? 신의 심장을 넘길 만큼 무엇을 받았어요? 리월이 직접 버티는 모습을 보고 싶었다는 설명만으로는 그 계약의 내용까지 알 수가 없잖아요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_022","speaker":"종려","text":"그 질문에 모두 답할 수는 없네. 계약에는 비밀을 지켜야 한다는 약속도 포함되어 있어. 자네가 위험을 겪었다는 사실을 가볍게 여겨서 말을 아끼는 것은 아니네.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_023","options":[{"label":"위험을 겪은 사람은 밖에서 몸으로 값을 치르고, 값이 어떻게 정해졌는지는 못 듣는다는 게 참 기분 나쁘네요. 약속을 어기라고 떼쓰지는 않을게요. 그래도 제가 납득했다는 뜻으로 듣지는 마세요.","id":"PRO_L04K1_zhongli_024","items":[{"k":"line","id":"PRO_L04K1_zhongli_025","speaker":"종려","text":"그러겠네. 침묵을 받아들였다는 것과 그 침묵에 만족한다는 것은 다른 일이니. 말할 수 없는 것을 다른 말로 꾸며 납득을 구하지도 않겠네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 약속 하나는 받아 두죠. 계약 때문에 말 못 하는 부분을 제 잘못된 기억 탓으로 돌리지는 말아 주세요. 요즘은 제 기억만 남는 일이 너무 많습니다.","id":"PRO_L04K1_zhongli_026","items":[{"k":"line","id":"PRO_L04K1_zhongli_027","speaker":"종려","text":"자네가 기억한다고 말한 일을 내 편의를 위해 지우지는 않겠네. 다만 자네의 기억과 내가 말할 수 있는 사실 사이에 빈칸이 있다면, 그 빈칸을 채웠다고 가장할 수도 없지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_028","speaker":"","text":"시뇨라는 받은 물건을 확인하고 몸을 돌렸다. 타르탈리아는 내 다친 팔을 살피다가 먼저 말을 걸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_029","speaker":"타르탈리아","text":"나한테도 할 말이 있다고 했지. 그런데 네 표정은 처음 만난 사람한테 인사하려는 표정이 아니네. 그 상처하고 내가 무슨 관계가 있다고 생각하는 거야?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_030","speaker":"나","text":"황금옥에서 너하고 싸웠어. 네가 밀리고, 내가 끝내려는 순간 건물이 무너졌지. 나는 돌에 깔렸고 병사들이 꺼냈어. 넌 사라졌고. 너, 거기서 무슨 일이 있었는지 기억해?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_031","speaker":"타르탈리아","text":"황금옥에서 너와 싸웠다고? 잠깐, 그건 내가 아는 일이 아닌데. 그 시간의 일이 매끄럽지 않은 건 맞아. 하지만 너와 칼을 맞댄 기억은 없어. 이렇게까지 적의를 받는데 재미있게 싸웠다는 기억도 없으니 나한테도 달가운 상황은 아니군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_032","speaker":"","text":"손이 굳었다. 각청에게 들었던 말이 다른 얼굴에서 돌아왔다. 다만 이번 상대는 죽은 것을 본 사람이 아니라 나와 싸우다 사라진 사람이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_033","options":[{"label":"그때 너는 싸움이 즐거워 보이지 않았어. 끝나는 순간만 기다리는 것 같았고, 바깥의 네 사람들 얘기에도 관심이 없었어. 그런데 지금은 또 내가 알던 얼굴을 하네. 이걸 기억 못 한다는 말 하나로 넘기라고?","id":"PRO_L04K1_zhongli_034","items":[{"k":"line","id":"PRO_L04K1_zhongli_035","speaker":"타르탈리아","text":"넘기라고는 안 했어. 나도 누가 내 이름으로 네게 그런 기억을 남겼는지, 내가 무엇을 놓쳤는지 알고 싶으니까. 그렇지만 없는 기억을 있는 척해서 네 설명에 맞출 생각은 없어. 칼로 확인하고 싶다면 상처부터 낫고 와.","map":"MAP_LIYUE_HARBOR"}]},{"label":"황금옥에서 우리가 싸웠다는 말 자체가 처음 듣는 얘기야, 아니면 그때만 기억이 끊긴 거야? 둘을 같은 말로 넘기고 싶진 않아.","id":"PRO_L04K1_zhongli_036","items":[{"k":"line","id":"PRO_L04K1_zhongli_037","speaker":"타르탈리아","text":"그 시간만 끊겨 있어. 내가 기억하지 못한다는 말로 네가 겪은 일까지 없애려는 건 아니야. 하지만 기억이 있는 척 맞장구칠 수도 없지. 칼로 확인하고 싶다면 상처부터 낫고 와.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_038","speaker":"나","text":"칼로 확인하면 알 수 있는 일이었으면 황금옥에서 끝났겠지. 됐어, 지금 다시 싸울 생각은 없어. 기억나는 게 생기면 숨기지 마. 나도 내가 본 걸 거짓말로 바꿔서 편해질 생각은 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_128","text":"종려는 두 사람의 말을 듣고 있었다. 내가 돌아보자 그는 고개를 아주 조금 저었다. 모든 현상을 한마디로 설명할 답을 내놓지는 않았다. 계약을 아는 사람과 지금 벌어진 이상을 전부 아는 사람은 같지 않을 수 있었다."},{"k":"line","id":"PRO_L04K1_depart_001","speaker":"","text":"은행 밖으로 나오자 햇빛이 눈에 들어왔다. 도시를 구한 뒤에는 답이 이어질 줄 알았다. 실제로 손에 남은 것은 더 정확해진 질문들이었다. 모락스의 계획만으로 설명되지 않는 죽음, 살아 돌아온 사람들의 빈 기억, 내가 알던 사람과 달랐던 상대.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_002","speaker":"나","text":"이나즈마로 가 보자. 다음에 무슨 일이 있는지 안다고 자신할 생각은 없어. 그래도 이 세계가 내가 알던 이야기와 어디서 달라지는지 직접 보려면 계속 움직여야 해. 이번에는 아는 줄 안다는 말부터 좀 줄이고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_131","text":"그 결심을 입 밖에 낸 뒤 곧장 항구로 뛰어가지 않았다. 치료소에 돌아가 군의관에게 장거리 이동을 준비하고 싶다고 말할 차례였다. 목적지를 정하는 것과 당장 갈 수 있다는 것은 다르다는 정도는 이제 몸으로 알았다."},{"k":"line","id":"PRO_L04K1_depart_003","speaker":"나","text":"이나즈마로 갈 생각입니다. 바로 떠나겠다는 건 아니고, 배편을 알아보는 동안 치료를 계속 받고 싶어요. 이번에는 중간에 건물 무너지는 일정은 제가 잡지 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_004","speaker":"군의관","text":"그 일정은 앞으로도 잡지 마십시오. 당분간은 이틀마다 상처를 확인하고, 무거운 짐을 한쪽 어깨에 걸지 마세요. 항해 날짜가 정해지면 그 전에 다시 오십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_005","speaker":"","text":"각청은 해안 통행을 확인하러 가는 길에 나를 만났다. 처음처럼 내가 누구인지 묻지 않았다. 오늘 약속한 사람이 어느 자리에 앉아 있는지 알고 찾아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_006","speaker":"나","text":"나, 다음에는 이나즈마로 가려고 해. 그리고 진한테는 내가 살아 있고 리월의 위기는 일단 막았다고 알려야겠어. 치료받는 중이라는 말도 빼지 말고 보낼 생각이야. 다음 소식이 수색 요청이면 너무 미안하잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_007","speaker":"각청","text":"그 내용이면 길드의 정규 전달편에 맡길 수 있어. 네가 여기서 확인한 이상도 짧게 구분해서 적어. 추측까지 진이 본 사실처럼 쓰지는 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_137","text":"치료소 책상에서 편지를 적었다. 리월에서 살아남았고 치료 중이라는 소식, 바다의 위기를 막았다는 일, 다음 목적지를 알아보고 있다는 계획이었다. 길드 창구에 맡겼고 몬드행 전달편에 접수되었다는 답을 받았다. 이번에는 내가 어디에 있는지 알리는 일이 실제로 시작되었다."},{"k":"line","id":"PRO_L04K1_depart_008","speaker":"각청","text":"배편은 남십자 함대 쪽에도 물어봐. 만나게 되면 황금옥에서 살아 나왔다는 얘기부터 자랑하지 마. 네 몸 상태를 과장하면 배에 태우는 사람도 곤란해져.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_depart_009","options":[{"label":"알았어. 처음 만나는 선장한테는 얌전히 소개부터 할게. 너한테는… 고마웠어. 내가 기억하는 닷새의 너한테도, 그걸 기억 못 하면서 다시 도와준 지금의 너한테도.","id":"PRO_L04K1_depart_010","items":[{"k":"line","id":"PRO_L04K1_depart_011","speaker":"각청","text":"둘을 따로 세워 두지는 말라니까. 네가 기억하는 일을 내 기억으로 만들 수는 없어도, 지금 고맙다는 말은 내가 들었어. 네가 돌아오면 오늘처럼 이름부터 부르면 돼. 이번에는 내가 먼저 어디서 만났느냐고 묻지 않았으면 좋겠네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"돌아오면 오늘부터 이어서 얘기하자. 네가 모르는 닷새를 내가 매번 설명하면서 처음부터 다시 만나는 건 그만하고 싶어. 지금 같이 겪은 일도 충분히 많잖아.","id":"PRO_L04K1_depart_012","items":[{"k":"line","id":"PRO_L04K1_depart_013","speaker":"각청","text":"그래. 네가 가진 과거를 버리라는 뜻은 아니지만, 지금의 내가 들을 인사도 하나 남겨 둬. 네가 돌아오면 오늘처럼 이름부터 부르면 돼. 이번에는 내가 먼저 어디서 만났느냐고 묻지 않았으면 좋겠네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_depart_014","speaker":"","text":"한동안 답하지 않고 웃었다. 돌아오라는 명령도, 계속 머무르라는 부탁도 아니었다. 다시 만났을 때 서로 아는 사람으로 서고 싶다는 말이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_142","text":"다음 날 항구에 마련된 남십자 함대의 연락 장소로 갔다. 선장은 아직 만나지 못했고, 창구의 선원 역시 초면이었다. 이나즈마 방면의 출항 안내를 기다리는 사람들 곁에 서자 다음 여정을 준비하고 있다는 실감이 났다."},{"k":"line","id":"PRO_L04K1_depart_015","speaker":"나","text":"각청에게 남십자 함대 쪽에 문의해 보라는 소개를 받았습니다. 이나즈마 방면 운항과 승선 상담을 부탁드리고 싶어요. 지금 치료받는 중이라 출발 전에 몸 상태도 다시 확인하려고 합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_016","speaker":"남십자 선원","text":"신청은 전하겠습니다. 선장님이 목적과 몸 상태를 직접 물으실 겁니다. 출발 날짜를 정한 것으로 생각하지는 마십시오. 연락받을 곳은 치료소로 남겨 두면 되겠습니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_017","speaker":"나","text":"네. 당분간은 거기서 부르면 됩니다. 돌아갈 곳을 알려 두는 게 생각보다 중요하더라고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_018","speaker":"","text":"치료소에 돌아온 뒤에는 칠성 쪽의 정산 담당자가 기다리고 있었다. 새로운 직위를 주는 절차도 아니었다. 끝낸 일의 몫을 실제로 돌려받는 자리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_019","speaker":"정산 담당자","text":"지급액은 1,800모라, 영웅의 경험 두 개와 모험가의 경험 세 개입니다. 이번 리월 방어에 참여하고 위험을 전달한 공적에 대한 정산입니다. 물품과 금액을 확인하신 뒤 받아 주십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_depart_020","options":[{"label":"확인했습니다. 1,800모라에 영웅의 경험 두 개, 모험가의 경험 세 개. 받겠습니다. 다음에는 돈 쓸 일이 치료보다 밥하고 배편 쪽에 많았으면 좋겠네요.","keep":"ISK_L04_K1_149","items":[{"k":"line","id":"PRO_L04K1_depart_021","speaker":"정산 담당자","text":"지급 기록에 남겼습니다. 다음 몫도 밥값으로 쓰이기를 바라겠습니다.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_150","text":"치료소 창 너머의 바다 위에는 군옥각이 없었다. 잠깐 그 하늘을 올려다본 뒤 침상 곁에 놓은 여행 준비 메모로 눈을 내렸다. 이나즈마로 떠날 준비는 시작되었고, 아직 풀리지 않은 질문들은 함께 가지고 갈 것이었다. 이제 그 자리를 부수지 않고 떠나는 법을 배울 차례였다."},{"k":"keep","id":"ISK_L04_K1_END"}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L04_K1_001_0","text":"바깥을 향해 손을 뻗었다. 큰 들보는 건드리지 않았다. 손끝에 닿는 작은 돌부터 옆으로 밀었다."},{"k":"text","id":"V141_AFTER_ISK_L04_K1_001_0","text":"작은 돌이 옆으로 굴렀다. 좁은 틈으로 빛이 들어오고, 바깥에서 받침을 부르는 소리가 가까워졌다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."},{"k":"text","id":"V141_BEFORE_ISK_L04_K1_073_0","text":"감우와 연비가 치료소를 찾아왔다. 고운각에서 함께 보고를 찾던 두 사람이, 이번에는 보고 대신 밥을 들고 왔다."}]},{"id":"ISK_L04_K2","entry":"ISK_L04_K2_001","items":[{"k":"keep","id":"ISK_L04_K2_001","hold":true,"text":"들보가 다리를 누르고 있었다. 몸을 일으키려 하자, 통증에 숨이 턱 막혔다."},{"k":"line","id":"PRO_L04K2_rubble_001","speaker":"나","text":"...아, 안 돼... 다리가 안 빠져.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_002","speaker":"","text":"출구가 있던 쪽에서 돌 구르는 소리가 들렸다. 손에 잡힌 파편으로 바닥을 두드렸다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_003","speaker":"나","text":"거기... 사람 있어요? 여기 있어요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_004","speaker":"천암군","text":"들립니다! 들어가신 통로를 따라왔습니다. 그 자리에서 움직이지 마세요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_005","speaker":"나","text":"여기까지... 올 수 있어요?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_006","speaker":"천암군","text":"앞이 막혔습니다. 목소리는 잘 들립니다. 손을 움직일 수 있습니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K2_rubble_007","options":[{"label":"손은 움직여요. 이쪽이에요... 소리 들려요?","id":"PRO_L04K2_rubble_008","items":[{"k":"line","id":"PRO_L04K2_rubble_009","speaker":"","text":"손에 쥔 파편으로 다시 두드렸다. 이번에는 바로 가까운 곳에서 대답이 돌아왔다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_010","speaker":"천암군","text":"들립니다. 그쪽부터 열겠습니다. 손은 잠깐 뒤로 빼 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"다리가 눌렸어요... 여기, 더 무너지는 건 아니죠?","id":"PRO_L04K2_rubble_011","items":[{"k":"line","id":"PRO_L04K2_rubble_012","speaker":"천암군","text":"바깥에서도 들보가 보입니다. 먼저 받치겠습니다. 혼자 다리를 빼려 하지 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_013","speaker":"","text":"바깥에서 받침을 부르는 소리가 이어졌다. 꽉 쥐었던 파편을 내려놓았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L04K2_rubble_014","speaker":"천암군","text":"손앞의 작은 파편부터 치우겠습니다. 몸을 누르는 들보는 건드리지 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_015","speaker":"나","text":"...이 작은 것만요. 손은 닿아요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"thru","id":"ISK_L04_K2_001"},{"k":"line","id":"PRO_L04K2_rubble_016","speaker":"천암군","text":"보입니다! 뒤쪽, 받쳐! 조금만 더...","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_017","speaker":"나","text":"아...! 잠깐, 다리가...!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_018","speaker":"천암군","text":"멈춰! 받침 그대로 잡아. 더 들지 마!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_019","speaker":"","text":"움직임이 멎었다. 천암군이 다시 신호를 맞추자 다리를 누르던 무게가 조금씩 줄었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_020","speaker":"나","text":"...타르탈리아는요? 그 사람은 나왔어요?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_021","speaker":"천암군","text":"...우인단 집행관 말입니까? 안에 같이 있었습니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_022","speaker":"나","text":"네... 무너지기 전엔 바로 앞에 있었는데...","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_023","speaker":"천암군","text":"바깥에도 전하겠습니다. 먼저 손을 이쪽으로 뻗어 보십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_024","speaker":"","text":"돌 틈을 더듬던 손이 천암군에게 붙잡혔다. 손이 미끄러질까 봐 손가락에 힘을 줬다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_025","speaker":"나","text":"...잡았어요. 놓지 마요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_026","speaker":"천암군","text":"놓지 않습니다. 여기 있으니 제 목소리를 듣고 계세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K2_007","text":"손이 팔 아래로 들어왔다. 병사 둘이 같은 속도로 몸을 끌어내자 거친 바닥이 옷을 긁었다. 바깥의 빛을 본 뒤에도 한동안 눈을 제대로 뜨지 못했다. 공기를 들이마시자 가슴이 들썩였고, 그 움직임이 아직 내 것이라는 사실이 이상했다. 타르탈리아가 있을 자리는 보이지 않았다."},{"k":"line","id":"PRO_L04K2_rubble_027","speaker":"군의관","text":"다리를 펴려고 힘주지 마세요. 눌렸던 곳부터 확인하겠습니다. 감각이 있는지 말해 주시고, 제가 만지는 위치를 보지 않은 상태로도 느껴지는지 확인해 보세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K2_rubble_028","options":[{"label":"받을게요. 치료해 주세요. 제 멋대로 움직여서 두 번 꺼내게 할 생각은 없습니다. 그런데 살았다고 그렇게 아무렇지 않게 말해 주시니까 좋네요. 저 혼자 있으면 이게 무슨 뜻인지부터 자꾸 생각하게 돼서요.","keep":"ISK_L04_K2_009","items":[{"k":"line","id":"PRO_L04K2_rubble_029","speaker":"군의관","text":"살아 있으니 치료하는 겁니다. 그 이상의 뜻은 나중에 생각하셔도 됩니다. 다리부터 보겠습니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K2_010","text":"군의관은 구호 상자를 열고 지혈에 쓸 천과 약품을 꺼냈다. 호흡과 눈의 반응을 살피고 눌린 다리의 감각을 확인한 뒤 상처를 씻었다. 잔해에서 꺼낸 몸은 살아 있었고 치료에 반응했다. 내가 왜 살아남았는지는 이 짧은 진찰만으로 알아낼 수 없었다."},{"k":"choice","group":"G_PRO_L04K2_rubble_030","options":[{"label":"바지 자르셔도 됩니다. 원래 남한테 보여 줄 옷차림은 아니었는데 오늘 확실히 끝났네요. 옷값보다 다리값이 비싸다는 정도는 저도 압니다.","id":"PRO_L04K2_rubble_031","items":[{"k":"line","id":"PRO_L04K2_rubble_032","speaker":"군의관","text":"그렇게 말씀하시면 처치하기 편합니다. 다만 다리값을 아는 분이 처치 끝나자마자 뛰어가겠다고 하면 제가 조금 곤란해지겠군요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"저 다리 움직일 수 있을까요? 당장 잘 걷겠다는 말은 아니고, 옆에서 받쳐 주면 어디까지 가능한지 알고 싶어요.","id":"PRO_L04K2_rubble_033","items":[{"k":"line","id":"PRO_L04K2_rubble_034","speaker":"군의관","text":"감각과 움직임은 확인되고 있습니다. 처치한 뒤 부축받으며 천천히 서 보겠습니다. 걸을 수 있는 만큼과 버텨야 한다고 마음먹은 만큼을 혼동하지 않으면 됩니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K2_017","text":"붕대가 감기는 동안 먼 바다에서 일어난 거대한 움직임이 공기와 땅을 울렸다. 호위 병사 하나가 언덕 끝을 보고 돌아와, 항구에서 오셀에 맞선 방어가 시작되었다는 급한 연락을 전했다. 일어서려다 군의관의 손에 어깨를 눌렸다."},{"k":"line","id":"PRO_L04K2_rubble_035","speaker":"나","text":"알아요, 갑자기 일어나지 말라는 거죠. 그런데 저쪽은 가야 합니다. 황금옥에서 막을 수 있을 줄 알았는데 결국 바다가 움직였어요. 응광과 각청에게 제가 살아 나왔고 타르탈리아는 보이지 않는다고 알려 주세요. 저도 뒤따라가겠습니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_036","speaker":"군의관","text":"호위대와 함께 이동하십시오. 부축 없이 다리를 끌면서 따라가는 것은 허락하지 않겠습니다. 지금 당장 싸울 몸이라고 판단한 게 아닙니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K2_020","text":"병사의 어깨를 빌려 일어섰다. 안에서 만난 타르탈리아가 떠올랐다. 누군가를 찾는다는 말에도, 부하들의 상태에도 무심하던 얼굴이었다. 그러나 지금 그 얼굴을 붙잡으려 무너진 안으로 돌아가는 것은 사람들을 다시 위험 속에 세우는 일이었다. 바다를 향한 길을 골랐다."},{"k":"keep","id":"ISK_L04_K2_021","text":"병사들은 길의 완만한 부분을 골라 이동했다. 자꾸 부축을 받는 것이 미안했지만 그때마다 거절하면 오히려 더 늦어졌다. 한참 뒤 대피한 사람들이 모이는 항구 외곽의 넓은 길에 닿았다."},{"k":"line","id":"PRO_L04K2_porter_001","speaker":"","text":"수레 하나가 길을 가로막고 있었다. 사람을 태우려고 짐을 내린 수레였다. 앞쪽에서 누군가 끈을 당기는 병사에게 매듭을 너무 깊게 넣지 말라고 핀잔을 주었다. 걸음이 멎었다. 닷새 동안 들어 귀에 익었던 목소리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_002","speaker":"짐꾼","text":"다시 풀어야 하는 매듭인데 그렇게 꽉 묶으면 칼로 끊어야 하잖아. 손 이쪽으로 빼고… 거기, 당신 왜 그렇게 보고 있어? 어디 갔다가 그런 꼴로 돌아왔어? 같이 내려오기로 해 놓고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_003","speaker":"","text":"살아 있었다. 내가 들어 올리려다 끝내 두고 온 사람이 자기 발로 서서 다른 사람의 일을 도와주고 있었다. 이름을 부를 수 없어서 그대로 앞으로 다가갔다. 짐꾼은 다친 다리를 보고 손을 내밀었다. 그 손을 잡자 어깨가 무너졌다. 차가웠던 몸과 따뜻한 손이 같은 사람의 것이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_004","speaker":"나","text":"……살아 계셨네요. 나… 당신을 거기 두고 나왔어요. 데리고 가려고 했는데 힘이 안 됐고, 너무 무서워서 도망쳤어요. 돌아와서 찾았는데 어디 있는지도 모르겠고. 지금 이렇게 서 계시면 제가 무슨 말을 해야 할지 모르겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_005","speaker":"짐꾼","text":"두고 나왔다니 어디서? 의례에 같이 간 건 기억하지. 그다음에 정신 차리니까 길 옆에 사람들이 모여 있었고, 내가 왜 거기 있는지 모르겠더라고. 병사들이 쉬라고 했는데 바다에서 난리가 나서 여기로 옮겼어. 당신이 나를 찾는다는 말은 아까 들었는데, 대피하는 사이에 서로 엇갈린 모양이야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_027","text":"더 세게 손을 잡으려다가 놓았다. 손에 붕대를 감은 나를 보고 짐꾼이 얼굴을 찌푸렸기 때문이다. 의례에서 분명 이 사람의 죽음을 확인했다. 지금의 대답이 그 사실을 지우지는 않았다. 대신 죽었던 사람에게도 설명할 수 없는 시간이 있고, 그 뒤에 다시 시작된 하루가 있다는 것을 눈앞에서 보았다."},{"k":"choice","group":"G_PRO_L04K2_porter_006","options":[{"label":"자세한 건 나중에 이야기해도 될까요? 지금은 당신이 여기 계신 것부터 좀 믿고 싶어요. 당신보고 설명하라고 소리치고 싶지는 않아요.","id":"PRO_L04K2_porter_007","items":[{"k":"line","id":"PRO_L04K2_porter_008","speaker":"짐꾼","text":"내가 설명할 수 있었으면 벌써 했겠지. 당신이 나를 두고 도망쳤다고 말하는데, 나는 돌아와서 나를 찾는 사람을 보고 있잖아. 둘 다 할 말이 많아 보이는데 바다가 잠잠해진 다음에 해.","map":"MAP_LIYUE_HARBOR"}]},{"label":"각청은 저를 기억 못 해요. 당신은… 닷새 동안 같이 있었던 거, 기억하세요?","id":"PRO_L04K2_porter_009","items":[{"k":"line","id":"PRO_L04K2_porter_010","speaker":"짐꾼","text":"기억하지. 매듭 못 묶던 사람이 닷새째 되니까 어깨에 멘 포대는 안 떨어뜨리더라고. 의례 다음부터가 비어 있는 거야. 그러니까 지금 내 앞에 있는 사람부터 봐. 할 말은 바다가 잠잠해진 다음에 해.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_porter_011","speaker":"","text":"웃으려다가 울음처럼 숨을 뱉었다. 각청에게서 잃었던 닷새가 이 사람에게는 남아 있었다. 모두의 기억이 같은 범위로 사라진 것이 아니라는 차이도 보였지만, 나는 지금 그 손을 단서라고 부르고 싶지 않았다. 살아 있는 사람이 먼저였다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_porter_012","options":[{"label":"저는 군옥각 쪽으로 갈 겁니다. 위에서 막는 동안 길을 지켜야 해요. 당신은 대피하는 사람들하고 같이 나가 주세요. 자기 몸 하나만 잘 챙겨 주세요.","id":"PRO_L04K2_porter_013","items":[{"k":"line","id":"PRO_L04K2_porter_014","speaker":"짐꾼","text":"그 몸으로 또 가겠다고? 말리면 들을 얼굴도 아니네. 그럼 당신도 나한테 한 약속은 지켜. 내려와서 짐이 어찌 됐는지 같이 확인하기로 했잖아. 이번에는 누가 먼저 사라졌느냐고 따지지 말고, 끝까지 보고 나서 헤어지자고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"저는 군옥각 쪽 길을 지키러 가겠습니다. 헤어진 뒤 짐을 확인하러 만날 때까지, 서로 무사히 돌아오는 걸 먼저 약속합시다.","id":"PRO_L04K2_porter_015","items":[{"k":"line","id":"PRO_L04K2_porter_016","speaker":"짐꾼","text":"그 약속이라면 나도 할 수 있지. 짐 때문에 여기 남으라는 부탁을 안 하는 건 고맙군. 내려와서 짐이 어찌 됐는지 같이 확인하기로 한 것도 잊지 말고. 이번에는 끝까지 보고 나서 헤어지자고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_porter_017","speaker":"","text":"각청이 보낸 병사가 수색을 마쳤다는 보고를 가지고 다가왔다. 이번에는 찾았다는 소식이 실제로 목적지에 닿아야 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_018","speaker":"나","text":"찾았습니다. 제가 찾던 분이 맞고 지금 살아 계십니다. 각청에게도 그렇게 전해 주세요. 우선 이분이 대피하는 길부터 안내해 주세요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_019","speaker":"","text":"병사는 대피 조에 짐꾼을 인계하고 발견 소식을 각청에게 전했다. 그가 걸어가는 뒷모습을 오래 보지 않았다. 이번에는 어디로 가는지 알고 있었고, 다시 만날 일을 남겨 두었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_020","speaker":"각청","text":"그 사람을 찾았다는 보고를 받았어. 다행이네. 네가 직접 확인했으니 이제 수색 인원도 대피 쪽에 붙일 수 있어. 네 상태는 군의관에게 들었어. 정면에서 뛰어다닐 생각이면 돌려보낼 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_021","speaker":"나","text":"정면으로 뛰어갈 기운은 없어. 하지만 길 하나라도 지킬 수 있으면 맡겨 줘. 그분 찾았다고 나만 안심하고 앉아 있기에는 저 바다가 아직 너무 시끄럽잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_022","speaker":"각청","text":"군옥각의 연결 지점에 인원이 필요해. 선인들이 정면의 힘을 막는 동안 뒤에서 장치를 노리는 적을 끊어야 해. 혼자 멀리 쫓아갔다가 다리 풀리는 일은 없어야 해.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_039","text":"각청은 나를 전투 인원에게 넘기며 다친 쪽을 분명히 알렸다. 누구도 그것을 듣고 도움이 안 된다고 말하지 않았다. 작은 몫을 실제로 끝내는 편이 큰일을 하겠다며 쓰러지는 것보다 나았다."},{"k":"keep","id":"ISK_L04_K2_040","text":"군옥각 위에서는 바람이 얼굴을 때렸다. 응광과 선인들의 힘이 바다를 향해 이어졌고, 그 빛 뒤로 병사들이 움직였다. 물결이 부딪칠 때마다 바닥이 흔들렸지만 곧바로 부서지지는 않았다."},{"k":"line","id":"PRO_L04K2_osial_001","speaker":"응광","text":"황금옥에서 살아 나온 손님이 돌아왔군. 지금은 앉을 의자를 내줄 수 없어. 네가 경고한 덕분에 옮긴 사람이 있지만, 아직 이곳을 비울 만큼 시간을 벌지는 못했어. 뒤쪽 길을 부탁할게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_002","speaker":"나","text":"의자는 나중에 빌리겠습니다. 먼저 말씀드리면 짐꾼을 찾았어요. 살아 있고 대피 중입니다. 그 일까지 놓지 않고 사람 붙여 주신 거, 잊지 않을게요. 그러니까 남은 사람도 다 내보내고 나서 당신 집 얘기를 합시다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_003","speaker":"응광","text":"기쁜 소식 하나는 가져왔네. 그렇다고 지금 마음이 가벼워져서 다친 몸을 잊지는 마. 네가 선 곳을 비우지 않는 것이 지금 가장 필요한 도움이야.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_004","speaker":"류운차풍진군","text":"이 몸이 바다를 막는 사이 연결 장치에 손을 대려는 것들이 있네. 장치를 살피겠다고 함부로 선 밖으로 나가지 말게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_005","speaker":"나","text":"알겠습니다. 제 자리 지키고, 옆에 있는 사람하고 맞춰 움직이겠습니다. 오늘은 혼자 더 많이 들겠다고 고집부리는 사람이 제일 먼저 지치는 날인 것 같네요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_006","speaker":"","text":"금속이 부딪치는 소리가 뒤에서 울렸다. 연결로 끝에 나타난 습격자들이 방어 인원을 밀어내며 안쪽을 노렸다. 옆의 병사가 방패를 세웠고, 각청이 앞을 막는 동안 나는 그 틈으로 파고드는 적에게 무기를 겨누었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K2_047","text":"선인과 칠성이 오셀의 압력을 막는 동안, 군옥각의 연결 지점과 진법을 지키는 방어전이 시작된다."},{"k":"line","id":"PRO_L04K2_osial_007","speaker":"","text":"연결 지점을 향하던 적의 움직임이 마침내 꺾였다. 그러나 바다의 힘이 다시 장치를 덮치자 선인들이 펼친 방어가 크게 휘었고, 건물 아래로 떨어진 파편이 돌아오지 않는 깊이까지 내려갔다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_008","speaker":"류운차풍진군","text":"연결부가 더 버티지 못하겠네. 이 몸이 힘을 받아 낼 테니 안쪽 인원부터 물리게. 장치를 붙잡으려고 남으면 구해야 할 사람만 늘어나네!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_009","speaker":"","text":"응광은 남은 대피 인원과 손상된 지점을 빠르게 확인했다. 비서가 들고 가려던 상자에 시선이 갔다. 큰 상자는 두 사람이 들어야 했다. 그 곁에 서지 못하는 부상자가 있었다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_010","speaker":"나","text":"상자는 여기 놔요. 저 사람 먼저 옮깁시다. 지금은 한 번에 하나밖에 못 가잖아요. 어깨 이쪽으로 잡아 주세요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_011","speaker":"","text":"비서는 상자를 내려놓았다. 의례장에서 짐꾼을 혼자 들어 올리려다 실패한 팔이었다. 이번에는 혼자가 아니었고, 들어야 할 사람도 숨을 쉬며 발을 움직이려 애썼다. 그 숨소리에 보폭을 맞췄다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_012","speaker":"응광","text":"군옥각을 포기하겠어. 남은 힘을 모아 바다로 떨어뜨릴 거야. 사람은 모두 옮겨. 가져갈 수 없는 물건은 두고 가고. 여기 남는 것은 내가 책임질 손해니까, 누구도 그것 때문에 목숨을 걸 필요는 없어.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K2_osial_013","options":[{"label":"이름 모르는 물건이어도 당신이 모은 것들인 건 알아요. 아깝지 않다는 얼굴 안 하셔도 됩니다. 제가 버리라고 한 말 때문에 하는 선택처럼 남기지는 않겠습니다.","id":"PRO_L04K2_osial_014","items":[{"k":"line","id":"PRO_L04K2_osial_015","speaker":"응광","text":"이미 알고 있군. 그렇다면 내가 같은 말을 두 번 할 필요는 없겠네. 내 결정을 네가 대신 짊어지려고 하지는 마. 너는 네가 받친 사람을 놓지 않는 쪽에 힘을 써. 그게 지금 내 집을 가장 값있게 떠나는 방법이야.","map":"MAP_OSIAL_BATTLE"}]},{"label":"제가 챙길 수 있는 사람부터 데리고 나갈게요. 당신이 무엇을 포기하는지 모르는 척하지도, 나중에 제가 결단한 것처럼 말하지도 않겠습니다.","id":"PRO_L04K2_osial_016","items":[{"k":"line","id":"PRO_L04K2_osial_017","speaker":"응광","text":"내 결정을 존중한다면 지금은 남은 사람들에게 길을 내줘. 설명은 살아서 내려간 뒤에도 할 수 있어. 네가 받친 사람을 놓지 않는 쪽에 힘을 써.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K2_osial_018","speaker":"","text":"선인들이 힘을 모으자 바람의 방향이 바뀌었다. 지나가다 문턱에 걸린 끈을 손으로 걷어 냈다. 풀어야 하는 매듭을 너무 깊게 넣지 말라던 목소리가 떠올랐다. 떠나야 할 때 붙잡는 것은 좋은 매듭이 아니었다.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K2_osial_019","options":[{"label":"뒤쪽 상자는 놔두고 왔어. 주인 허락받았으니까 물건 찾으러 돌아갈 사람 없게 해 줘. 이제 우리도 빠지면 되는 거지?","id":"PRO_L04K2_osial_020","items":[{"k":"line","id":"PRO_L04K2_osial_021","speaker":"각청","text":"맞아. 더 돌아갈 이유는 없어. 부상자는 그쪽 인원이 받았으니 네 손을 빼도 돼. 사람들을 다 내보내고 너만 뒤에 남으면 끝난 게 아니야.","map":"MAP_OSIAL_BATTLE"}]},{"label":"내가 맡은 사람은 넘겼어. 이제 내가 좀 부축받아도 되겠지? 계속 괜찮은 척하는 재주가 늘어서 그게 제일 걱정이네.","id":"PRO_L04K2_osial_022","items":[{"k":"line","id":"PRO_L04K2_osial_023","speaker":"각청","text":"지금 말한 건 잘했어. 팔 이쪽으로 걸어. 다리에 힘이 없으면 그만큼 내가 받으면 돼. 끝까지 버티다가 넘어지는 것보다 서로 덜 다치는 방법이야.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K2_osial_024","speaker":"","text":"소가 남은 사람들의 위치를 확인하고 선인들이 빠져나갈 길을 붙들었다. 바닥이 기울면서 발이 미끄러졌지만 옆의 손이 나를 잡았다. 응광이 힘을 내려 보내는 순간 군옥각은 도시를 받치던 높이를 버리고 바다를 향해 떨어졌다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_025","speaker":"","text":"거대한 충격이 하늘과 물을 갈랐다. 조금 전까지 사람을 들고 나오던 문과, 그 뒤에 두고 온 상자와, 손님을 위해 비워졌던 의자가 하나의 빛 속으로 사라졌다. 오래 도시를 위협하던 울림이 마침내 잦아들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K2_065","text":"안전지대에 내려왔을 때 나는 한동안 팔을 둥글게 든 채 있었다. 이미 다른 인원에게 넘긴 부상자의 무게가 아직 몸에 남아 있었다. 각청이 어깨에서 손을 빼도 된다고 말하자 그제야 팔을 내렸다. 살아 있는 이들의 이름을 부르는 소리가 올라왔다."},{"k":"keep","id":"ISK_L04_K2_066","text":"해안의 급한 대피는 멈췄고 전투 인원은 남은 사람을 확인하기 시작했다. 군옥각을 잃었지만 도시 전체가 그 뒤를 따라 가라앉지는 않았다. 서로의 빈자리를 받치며 버틴 끝에, 응광과 선인들이 마지막 결정을 실행한 결과였다."},{"k":"line","id":"PRO_L04K2_osial_026","speaker":"나","text":"살아 있는 사람 이름 부르는 소리가 들리니까 이제 좀 알겠네. 끝났다는 게 이런 소리였구나. 나 잠깐 앉을게. 이번에는 어디 안 가. 다리가 더는 내 의견을 안 받아 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_osial_027","speaker":"각청","text":"앉아. 군의관이 올 거야. 어디 안 간다는 말은 방금 여기 있는 사람들 모두 들었으니까, 혼자 일어나서 걷지 마. 찾던 사람도 대피소에 도착했다고 확인됐어. 네가 쉬고 나서 다시 만날 수 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_069","text":"치료 구역에서 군의관은 다시 벌어진 상처를 살피고 붕대를 갈았다. 다친 다리에 과하게 힘을 준 탓에 붓기가 늘었지만 감각과 움직임은 남아 있었다. 아픈 곳을 아프다고 말하는 일이 오히려 쉬워졌다."},{"k":"line","id":"PRO_L04K2_name_001","speaker":"나","text":"이번에는 정말 쉬겠습니다. 다만 사람 하나가 찾아오면 저 여기 있다고 알려 주세요. 짐꾼이고, 의례 전에 저하고 같이 지냈던 분입니다. 그분을 다른 데로 보내지만 말아 주세요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_002","speaker":"군의관","text":"접수 담당자에게 이야기해 두겠습니다. 당신도 사람을 만나면 설명하느라 흥분해서 일어나지 마세요. 오늘은 치료받는 역할을 맡으시면 됩니다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_072","text":"누워서 천막 위를 보았다. 짐꾼이 언제 올지 기다리는 동안 잠이 들었다. 깨어났을 때는 낮이 지나 있었고, 침상 옆의 의자에 익숙한 사람이 앉아 있었다. 의례장에서 내려놓았던 몸이 이번에는 제 팔을 무릎 위에 얹고 꾸벅꾸벅 졸고 있었다."},{"k":"line","id":"PRO_L04K2_name_003","speaker":"나","text":"의자가 불편하면 깨우시지 그랬어요. 그렇게 자면 허리 더 아프잖아요. 그런데… 다시 와 주셨네요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_004","speaker":"짐꾼","text":"누운 사람 깨워 놓고 나 쉬겠다고 할 수는 없잖아. 당신이 먼저 찾아오겠다더니 몸을 그 꼴로 만들어 놓아서 내가 왔지. 내려오면 이야기하자던 약속은 지켜야 하니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_005","speaker":"","text":"두 사람은 한동안 마주 보고 있었다. 짐꾼이 살아 있는지 다시 손목을 확인하지 않았다. 잠에서 깬 사람이 뻣뻣해진 허리를 펴고 물을 찾는 모습을 보았다. 닷새 동안 너무 흔해서 흘려보냈던 행동들이 전부 선명했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_006","speaker":"나","text":"제대로 말할게요. 의례에서 사람들이 한꺼번에 죽었어요. 당신 숨도 맥박도 없었고, 제가 들어 올리려다 못 했어요. 당신이 잘못 기억한다고 몰아붙이려는 말은 아니에요. 제가 왜 그렇게 굴었는지 알아 주셨으면 해서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_007","speaker":"짐꾼","text":"그 말을 들으니 당신 얼굴은 이해가 되네. 나는 내가 그렇게 됐다는 감각이 없어. 알고 있다고 거짓말해 줄 수도 없겠지. 그래도 당신이 찾으러 돌아왔다는 건 알아. 당신이 나를 두고 왔다고 자신을 계속 붙들면, 지금 찾아온 나는 어디에 서 있어야 하겠어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_008","speaker":"","text":"시선을 내렸다가 다시 들었다. 죽음을 기억하는 사람만 대화의 중심에 두면 살아 돌아온 사람이 자기 이야기를 할 자리가 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_name_009","options":[{"label":"당신이 여기 오신 걸 자꾸 제 죄책감 끝내는 일로 만들면 안 되겠네요. 이름부터 알려 주세요. 닷새를 같이 있었는데 짐꾼이라고만 부른 게 이제 와서 너무 미안해요.","id":"PRO_L04K2_name_010","items":[{"k":"line","id":"PRO_L04K2_name_011","speaker":"짐꾼","text":"미안할 일까지는 아니지. 일터에서는 늘 그렇게 불리니까. 그래도 이름을 묻는 건 좋네. 내가 적어 줄게. 당신도 적어 줘. 다음에 다른 사람이 찾으러 와도 서로 설명하기 편하게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 오늘은 제가 설명하는 쪽을 좀 줄일게요. 당신이 정신 차린 다음에 어떤 일이 있었는지 듣고 싶어요. 누가 물 줬는지 같은 것부터요.","id":"PRO_L04K2_name_012","items":[{"k":"line","id":"PRO_L04K2_name_013","speaker":"짐꾼","text":"길가에 앉아 있는데 한 아주머니가 물을 줬어. 내가 짐부터 찾으려고 일어나니까 당신하고 똑같이 고집부린다고 핀잔도 주고. 이름은 못 물었지. 그러고 보니 당신한테도 내 이름을 말한 적이 없네. 적어 줄게. 당신도 적어 줘.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_name_014","speaker":"","text":"짐꾼은 종이에 자기 이름과 찾을 수 있는 작업 구역을 적어 주었다. 종이를 받아 이름을 읽고서 짐꾼의 얼굴을 다시 보았다. 장록. 닷새 동안 포대 뒤에 가려져 있던 이름이 두 글자로 손 안에 놓였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_015","speaker":"나","text":"장록 씨. ……이제야 부르네요. 제 이름과 지금 머무는 곳도 같이 적어 드릴게요. 몸 좀 나아지면 포대 확인하러 같이 가요. 이번에는 끝나는 것까지 옆에서 볼게요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_016","speaker":"장록","text":"그렇게 불리니까 일터가 아니라 집 같네. 됐어, 포대는 안 도망가. 당신 다리가 먼저야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_017","speaker":"","text":"나도 내 이름과 당분간 머무는 치료소를 적어 건넸다. 서로를 부르는 데 더는 막연한 설명이 필요하지 않았다. 그 종이가 사라진 시간을 되돌리지는 않았지만 다음 만남을 마련하는 데는 도움이 되었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_088","text":"다음 이틀 동안 재진료를 받으며 짧게 걷는 연습을 했다. 장록은 자신의 작업 구역과 치료소를 오가며 필요한 소식을 전했다. 그가 겪은 빈 시간은 돌아오지 않았지만, 지금 어디에 머무는지 모르는 사람으로 다시 사라지지는 않았다."},{"k":"line","id":"PRO_L04K2_name_018","speaker":"각청","text":"리월항의 일반 봉쇄는 오늘 해제해. 황금옥 잔해와 해안 파손 구역은 계속 막아 두지만, 물자 대기 구역과 시내의 통행은 다시 연다. 너희가 기다리던 포대도 상대와 검수 인원을 불러 확인할 거야. 이번에는 기억에만 맡겨 설명하지 않고 실제 물건을 함께 볼 수 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_019","speaker":"나","text":"좋아. 지난번에 내가 본 건 끈이 풀린 것까지였고, 안에 뭐가 있었는지는 못 봤어. 그건 그대로 말할게. 끝까지 같이라고 해 놓고 중간에 또 쓰러지면 안 되니까 천천히 걸어갈게.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_091","text":"각청은 통행을 재개한 길을 안내하고 검수 인원에게 시간을 알렸다. 나와 장록은 그 길을 함께 걸었다. 전에 기다리던 자리에 포대가 있었고, 물건을 넘겨받을 담당자가 도착해 있었다. 끈을 풀고 내용물과 수량을 확인하는 동안 나는 옆에서 지켜보았다. 지금 새로 인계할 수 있게 된 자리였다."},{"k":"keep","id":"ISK_L04_K2_092","text":"상대가 물건을 확인하고 인수 증서를 건넸다. 장록은 서명을 마친 뒤 증서와 빈손을 번갈아 보았다. 누구의 기억이 옳았는지 싸우느라 멈춰 있던 일이, 현재의 물건을 함께 확인하는 일로 마침내 끝났다. 장록은 어깨를 한 번 크게 돌리고 내 쪽으로 몸을 돌렸다."},{"k":"line","id":"PRO_L04K2_cargo_001","speaker":"장록","text":"끝났네. 이거 하나 내려놓는 데 무슨 일이 이렇게 많이 생겼는지. 당신이 내 짐 대신 들어준 건 없는데, 끝까지 같이 본 사람은 됐어. 나도 그건 기억할 수 있겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_cargo_002","options":[{"label":"대신 안 들어도 한몫은 할 수 있네요. 이제 제 다리 핑계로 밥집까지는 장록 씨가 천천히 걸어 주세요. 비싼 집 고르자는 뜻은 아니고요.","id":"PRO_L04K2_cargo_003","items":[{"k":"line","id":"PRO_L04K2_cargo_004","speaker":"장록","text":"말은 여전히 뻔뻔하네. 됐어, 길가에서 먹을 만한 데는 알아. 먹고 나면 나는 집에 소식부터 보낼 거야. 당신도 기다리는 사람 있으면 알려. 없다고 하더라도 앞으로 돌아올 곳은 하나쯤 적어 두고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"식사하고 나면 서로 소식 보낼 곳부터 정리하죠. 살아 있다고 알려야 한다는 생각을, 저는 자꾸 일이 전부 끝난 다음으로 미뤘거든요.","id":"PRO_L04K2_cargo_005","items":[{"k":"line","id":"PRO_L04K2_cargo_006","speaker":"장록","text":"그건 좋은 순서네. 배부터 채우고, 기다리는 사람한테도 밥이 넘어갈 만한 소식을 보내자고. 길가에서 먹을 만한 데는 알아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_096","text":"두 사람은 길가의 식당에서 천천히 한 끼를 먹었다. 장록은 다음에 맡을 일과 집에 보낼 소식을 이야기했고, 나는 듣다가 내 몫의 국물을 마셨다. 의례장에서 두고 온 사람의 이야기가 그 장면에서 멈추지 않았다. 지금의 그는 다음 일을 고르는 사람이었다."},{"k":"keep","id":"ISK_L04_K2_097","text":"응광과 선인들을 다시 만난 것은 그날 늦은 오후였다. 군옥각 대신 임시로 마련한 공간에서 피해 보고와 이후의 경계를 논하고 있었다. 전투의 규모에 비하면 작은 이야기였지만, 이번에는 스스로 작은 말로 줄이지 않기로 했다."},{"k":"line","id":"PRO_L04K2_council_001","speaker":"나","text":"찾던 분은 살아 계시고 지금 화물 인계도 끝났습니다. 장록이라는 분이에요. 의례의 그 순간은 기억 못 하지만, 저랑 기다리던 닷새는 기억하세요. 수색을 계속해 주신 덕분에 다시 만났고요. 이 얘기는 바다 얘기 뒤에 묻히기 전에 제가 직접 전하고 싶었습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_002","speaker":"응광","text":"잘 전해 줬어. 도시를 지킨 뒤 남겨야 할 것은 거대한 승리 이야기만이 아니니까. 다만 기억의 빈칸은 계속 남아 있군. 네가 본 것과 그 사람이 기억하는 것을 나누어 확인해 두겠어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_003","speaker":"류운차풍진군","text":"산에서 자네가 그 사람을 두고 왔다며 괴로워하던 모습을 기억하네. 다시 만났으니 이 몸도 다행이라 생각해. 그러나 기뻐할 일과 설명할 일을 한데 섞어 억지 답을 만들지는 말게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_004","speaker":"나","text":"이제는 조금 알겠습니다. 처음에는 살아 있는 사람만 보면 어떻게 살아 있냐고 붙들었는데, 그분이 그러더라고요. 그렇게만 묻고 있으면 지금 찾아온 자기는 어디 서 있느냐고. 그 말 듣고 좀 부끄러웠어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_005","speaker":"각청","text":"그래서 지금 할 수 있는 일을 다시 정하는 거야. 선인들께 도움받은 바다의 경계도 계속할 거고, 사람들의 통행과 생활은 저희가 돌려놓을 거예요. 이 도시가 앞으로 누구의 손으로 움직일지 보여 주는 건 큰 선언보다 매일 그 일을 끝내는 쪽이겠죠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_006","speaker":"류운차풍진군","text":"자네의 뜻은 들었네. 이번에는 직접 지키고 직접 내놓는 것을 보았지. 서로 확인할 길을 남겨 두는 편이 낫겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_007","speaker":"응광","text":"연락할 길은 열어 둘게요. 군옥각을 잃었다고 리월의 결정까지 공중에 매달려 사라진 것은 아니니까요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_council_008","options":[{"label":"저도 리월에서 더 해야 할 일이 있으면 알려 주세요. 다만 군의관이 무거운 짐은 아직 들지 말랬습니다. 또 산에 뛰어 올라가라는 일은 며칠만 뒤로 미뤄 주시면 좋겠네요.","id":"PRO_L04K2_council_009","items":[{"k":"line","id":"PRO_L04K2_council_010","speaker":"류운차풍진군","text":"이 몸이 자네를 급한 전갈에만 쓰려고 기다리는 줄 아는가. 자네 다리가 낫는 동안에도 날 수 있는 자들은 있네. 몸부터 돌보게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"몸이 나을 때까지는 가벼운 전달이나 설명으로 돕겠습니다. 제가 할 수 있는 일의 범위를 먼저 말씀드리는 게 낫겠지요.","id":"PRO_L04K2_council_011","items":[{"k":"line","id":"PRO_L04K2_council_012","speaker":"류운차풍진군","text":"그 범위를 아는 것도 책임이지. 의지가 있다는 이유로 몸의 상태를 지울 수는 없네. 몸부터 돌보게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_council_013","speaker":"","text":"그 잔소리를 다시 들을 수 있다는 사실이 나에게는 위로였다. 소는 문밖에서 시선을 돌려 나를 보았다. 황금옥으로 가기 전 돌아올 길을 보라고 했던 사람이었다. 이번에는 고개를 숙여 인사했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_014","speaker":"나","text":"그때 돌아올 길 보라고 하신 말씀, 도움이 됐습니다. 관리 통로로 들어간 걸 병사들에게 남겼고, 그 길을 기억해서 저를 찾았대요. 제가 혼자 잘해서 나온 건 아니었습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_015","speaker":"소","text":"살아 돌아왔으면 됐어. 다음에도 길을 남겨. 네가 찾는 사람만 있는 게 아니라 너를 찾는 사람도 생겼으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_001","speaker":"","text":"면담이 끝난 뒤 임시 집무 공간을 나서자 종려가 길가에서 기다리고 있었다. 그의 얼굴을 알아보았지만 다가가며 오래된 친구처럼 부르지는 않았다. 류운차풍진군은 두 사람을 잠깐 보고 먼저 다른 선인들과 이동했다. 옛 인연을 설명하는 말은 남기지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_002","speaker":"종려","text":"나는 왕생당의 객경, 종려라고 하네. 자네가 리월에서 겪은 일이 적지 않다고 들었어. 몸이 괜찮다면 잠깐 이야기를 나누고 싶군. 다리가 불편하면 앉을 곳부터 찾지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_003","speaker":"나","text":"종려 씨. 성함은 알고 있습니다. 어디부터 물어야 할지 모르겠는 사람을 이렇게 길가에서 만나니까 이상하네요. 우선 앉고 싶다는 데는 동의합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_114","text":"두 사람은 가까운 차 자리로 옮겼다. 종려는 내가 자세를 잡은 뒤 차를 권했다. 의례와 폐허 사이를 오간 뒤 처음으로 누군가와 뜨거운 잔이 식기를 기다리는 시간이 생겼다."},{"k":"line","id":"PRO_L04K2_zhongli_004","speaker":"나","text":"사람들이 제군 없이 리월을 지켰다는 말을 하더라고요. 저는 그 말이 맞다고 생각하면서도 화가 납니다. 막상 시험당하는 사람들은 시험이라고 들은 적이 없잖아요. 하루 벌어 먹고살던 사람은 그날도 짐을 들러 나온 거였고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_005","speaker":"종려","text":"사람의 하루는 더 큰 목적이 있다는 이유로 가벼워지지 않네. 자네가 그 일에 화를 내는 것은 이해하네. 하지만 리월 사람들이 이번에 한 선택까지 다른 누군가의 생각 속으로 돌려놓을 필요는 없을 걸세.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_006","options":[{"label":"그건 알아요. 응광이 군옥각을 포기한 건 그 사람이 직접 고른 일이었어요. 그래서 더 묻고 싶어집니다. 누군가는 얼마나 알고 있었고, 누군가는 왜 아무것도 모른 채 버텨야 했는지요.","id":"PRO_L04K2_zhongli_007","items":[{"k":"line","id":"PRO_L04K2_zhongli_008","speaker":"종려","text":"자네가 나에 대해 알고 있다고 여기는 부분도 있겠군. 지금 여기서 이름을 크게 확인하려 하지 않는 것을 보니, 어디까지 말할지 생각은 하고 온 모양이네. 답할 수 있는 일은 직접 답하겠어. 다만 모든 질문에 같은 범위의 대답을 줄 수는 없지.","map":"MAP_LIYUE_HARBOR"}]},{"label":"사람들이 무슨 위험을 감수하는지 알고 선택할 기회는 있었는지 묻고 싶어요. 제가 아는 이름을 확인받는 것보다, 그때 누가 어디까지 설명을 들었는지가 더 걸립니다.","id":"PRO_L04K2_zhongli_009","items":[{"k":"line","id":"PRO_L04K2_zhongli_010","speaker":"종려","text":"책임의 범위를 묻는 질문으로 듣겠네. 다만 내가 공개할 수 있는 범위에도 한계는 있어. 답할 수 있는 일은 직접 답하겠어. 모든 질문에 같은 범위의 대답을 줄 수는 없지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_zhongli_011","speaker":"나","text":"그럼 하나만요. 의례에서 사람들이 실제로 죽고 다시 나타난 일, 그것도 당신이 의도한 겁니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_012","speaker":"종려","text":"자네가 겪었다는 그 죽음과 기억의 빈자리를 내가 계획한 시험의 결과라고 말해 줄 수는 없네. 내가 설명할 수 있는 계획이 있다는 이유로 그 밖의 모든 현상을 거기에 넣어서는 안 되지. 자네가 본 일은 그 자체로 살펴야 할 일이네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_013","speaker":"","text":"잔을 내려놓았다. 모든 일이 하나의 손에서 나왔다고 들으면 미워할 사람을 정하기는 쉬웠을 것이다. 그러나 그 대답은 내가 알고 있는 이야기와 현재 벌어진 일 사이에 다시 경계를 그었다. 답답했지만 없는 다리를 밟고 건너가는 것보다는 나았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_014","speaker":"나","text":"그럼 남은 질문은 계약 쪽이겠네요. 물을 수 있는 자리에서 직접 묻고 싶습니다. 당신이 가는 곳에 함께 가도 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_015","speaker":"종려","text":"북국은행에서 마무리할 일이 있네. 그곳으로 오게. 다만 자네가 내 답에 만족할 것이라고 미리 약속할 수는 없겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_016","options":[{"label":"솔직한 초대네요. 알겠습니다. 대답이 마음에 안 들어도 컵을 던지지는 않을게요. 치료비 내고 나면 남의 그릇값까지 물 여유는 없거든요.","id":"PRO_L04K2_zhongli_017","items":[{"k":"line","id":"PRO_L04K2_zhongli_018","speaker":"종려","text":"그릇을 지켜 준다니 다행이군. 불만은 말로 전하게. 적어도 무엇이 답답한지는 더 분명히 들을 수 있을 테니.","map":"MAP_LIYUE_HARBOR"}]},{"label":"알겠습니다. 다만 제 말이 거칠어지면 못 배운 사람 취급부터 하지는 마세요. 모르는 게 많아서 묻는 건데, 오늘은 모르는 값이 좀 컸습니다.","id":"PRO_L04K2_zhongli_019","items":[{"k":"line","id":"PRO_L04K2_zhongli_020","speaker":"종려","text":"질문이 거칠다는 이유로 그 안의 일을 못 들은 척하지는 않겠네. 자네도 대답을 듣기 전에 정한 결론이 있다면 잠깐 내려놓고 오게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_130","text":"북국은행에 들어섰을 때 시뇨라를 먼저 보았다. 옆에 선 타르탈리아가 고개를 돌렸다. 멀쩡한 얼굴이었다. 붕대 아래 손가락을 움켜쥐었다. 잔해와 함께 사라진 상대가 살아 있는 사람들 사이에서 대화를 나누고 있었다."},{"k":"line","id":"PRO_L04K2_zhongli_021","speaker":"시뇨라","text":"몬드에 두고 왔다고 생각한 방해꾼이 리월에도 와 있었군. 그 팔은 또 어디서 성급하게 나서다 얻은 상처지? 이곳의 일까지 길게 만들 생각이면 미리 말해 두겠어. 참아 줄 생각은 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_022","speaker":"나","text":"방해하지 않겠습니다. 계약을 마무리하는 자리에 주먹부터 들이밀러 온 건 아니에요. 다만 그 계약 때문에 제가 묻고 싶은 일이 있고, 저 사람한테도 할 말이 있습니다. 당신들이 끝내면 제 차례도 좀 남겨 주세요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_023","speaker":"타르탈리아","text":"나한테? 시뇨라한테 한 소리 듣고도 눈은 계속 이쪽을 보고 있네. 종려 씨의 거래부터 끝내는 편이 좋겠군요. 나도 그 설명을 기다리던 중이라서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_024","speaker":"","text":"그 말투에 눈을 가늘게 떴다. 기분이 좋지 않아도 상대와 한 번 부딪쳐 보고 싶어 하는 온도가 있었다. 황금옥에서는 같은 입가의 웃음이 비어 보였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_025","speaker":"종려","text":"얼음의 여왕과 맺은 계약에 따라 나의 신의 심장을 넘기겠네. 시뇨라, 자네가 받아 전하게. 약속한 대가와 조건도 그대로 지켜져야 하겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_026","speaker":"","text":"시뇨라가 신의 심장을 받았다. 종려가 모락스라는 사실은 알고 있었지만, 그 힘의 상징이 다른 손으로 넘어가는 일은 처음 보는 현실이었다. 문밖을 향해 누구의 이름도 외치지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_027","speaker":"타르탈리아","text":"나는 내 방식대로 움직이고 있다고 생각했는데, 뒤에서는 이미 합의가 되어 있었던 거군요. 적어도 언제부터 어디까지 알고 있었는지는 들을 수 있겠죠?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_028","speaker":"시뇨라","text":"네가 알아야 할 만큼을 알았고, 이제 결과도 보았잖아. 모든 사람에게 모든 설명을 돌리는 것은 계약의 조건이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_029","speaker":"나","text":"그 불만은 저도 있어요. 종려 씨, 왜 그 계약을 맺은 겁니까? 신의 심장을 건네줄 만큼 받은 게 무엇이고, 어떤 조건이었어요? 이번에는 당신에게 직접 듣고 싶습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_030","speaker":"종려","text":"이번 계약에는 그 이유와 내용을 외부에 밝히지 않겠다는 약속도 포함되어 있네. 계약을 중요하게 여기니 아무것도 말하지 않겠다는 일반적인 뜻이 아니라, 이 계약에서 내가 지켜야 할 비밀이 있다는 뜻이지.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_031","options":[{"label":"그러면 저는 끝까지 모르는 채로 아픈 기억만 들고 나가겠네요. 그렇다고 제가 이해했다거나 괜찮다고 생각했다고 말하지는 않겠습니다. 그건 제 입으로도 거짓말이니까요.","id":"PRO_L04K2_zhongli_032","items":[{"k":"line","id":"PRO_L04K2_zhongli_033","speaker":"종려","text":"그렇게 받아들이겠네. 자네에게 없는 납득을 만들어 달라고 요구할 수는 없지. 다만 자네가 리월을 지키기 위해 한 일에 대한 감사까지 비밀로 둘 이유는 없네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"지금 답할 수 없는 질문은 그대로 남겨 둘게요. 설명을 못 들은 자리에 제가 멋대로 이유를 채워 넣지는 않겠습니다. 대신 아직 납득하지 못했다는 것도 같이 기억해 주세요.","id":"PRO_L04K2_zhongli_034","items":[{"k":"line","id":"PRO_L04K2_zhongli_035","speaker":"종려","text":"답을 얻지 못했다는 사실을 정확히 남기는 것도 중요하지. 침묵을 동의로 받아들이지는 않겠네. 자네가 리월을 지키기 위해 한 일에 대한 감사까지 비밀로 둘 이유는 없네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_zhongli_036","speaker":"나","text":"타르탈리아, 황금옥에서 있었던 일은 기억해? 나하고 싸웠고, 네가 밀리다가 바닥이 무너졌어. 너는 먼지 속으로 사라졌지. 나는 깔렸다가 병사들이 꺼냈고. 그 중에 기억나는 게 있어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_037","speaker":"타르탈리아","text":"네가 황금옥에서 나와 싸웠다고? 그건 처음 듣는 이야기야. 그 무렵의 일이 끊겨 있는 건 나도 알아. 하지만 너와 싸운 장면은 기억나지 않아. 내가 패색을 보였다는 말까지 붙으니 더 직접 확인하고 싶어지는군. 다친 몸을 지금 상대하겠다는 뜻은 아니고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_038","speaker":"나","text":"그때는 내가 찾는 짐꾼 얘기를 해도 아무 관심이 없었어. 싸움을 즐기는 게 아니라 내가 어디까지 오는지만 기다리는 것 같았다고. 지금 너는 그때하고 느낌이 달라. 본인도 모른다는 거야?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_039","speaker":"타르탈리아","text":"없는 기억을 꾸며서 맞장구쳐 줄 수는 없지. 네가 묘사하는 내가 좀 기분 나쁜 상대라는 건 알겠어. 누군가 내 일에 손을 댄 건지, 내가 놓친 게 있는지부터 알아봐야겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_040","speaker":"","text":"기억이 없다는 사람에게 기억하라고 소리친다고 답이 생기지 않는다는 것은 이미 배웠다. 장록 앞에서 들었던 말을 적 앞에서도 적용해야 한다는 사실이 썩 반갑지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_041","speaker":"나","text":"좋아. 다시 기억나는 게 있으면 사람 보내. 나도 본 걸 안 봤다고 바꾸지는 않을 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_042","speaker":"타르탈리아","text":"그 정도면 이야기할 여지는 있네. 다 낫고 나면 너와 직접 겨뤄 보고 싶다는 말도 남겨 둘게. 잊은 싸움으로만 내 실력을 평가받는 건 재미없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_043","speaker":"나","text":"환자 앞에서 재경기 예약부터 잡는 건 역시 만만치 않네. 지금은 예약 안 받을게. 나는 아직 멀쩡한 다리로 밥집까지 가는 게 다음 목표거든.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_152","text":"타르탈리아가 웃었다. 그 웃음을 보면서도 손을 내밀지는 않았다. 지금의 가벼움과 황금옥의 낯섦은 둘 다 기억해 두기로 했다. 오늘 당장 대답이 나올 질문을 모두 썼다는 것을 알았다."},{"k":"line","id":"PRO_L04K2_depart_001","speaker":"","text":"북국은행을 나와 사람들 사이에 섞여 천천히 걸었다. 이곳에서 같은 질문을 반복한다고 모든 답이 열릴 것 같지는 않았다. 내가 아는 이야기와 실제로 벌어진 일의 차이는 한 도시에서 시작해 한 도시에서 끝나는 것처럼 보이지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_002","speaker":"나","text":"다음에는 이나즈마로 가야겠어. 거기까지 가면 답이 나온다고 장담할 수는 없지만, 신을 만나 물을 길도 더 찾아봐야지. 이번에는 가기 전에 사람들한테 어디로 가는지도 남기고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_155","text":"바로 배를 찾아 달려가지 않았다. 치료소로 돌아와 여행 준비를 하고 싶다는 말을 군의관에게 먼저 꺼낼 차례였다. 황금옥에서 살아 나왔다고 그 뒤의 위험이 모두 나를 비껴가는 것은 아니었다."},{"k":"line","id":"PRO_L04K2_depart_003","speaker":"나","text":"이나즈마행 배편을 알아보려고 합니다. 지금 당장 떠나겠다는 건 아니에요. 항해 전에 어떤 상태까지 회복되어야 하는지 알려 주세요. 몸이 괜찮다는 말을 제가 혼자 먼저 정하지는 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_004","speaker":"군의관","text":"그렇게 준비하시면 됩니다. 무거운 짐을 메지 말고, 걷다가 어지럽거나 다리 감각이 달라지면 바로 돌아오세요. 출항 날짜가 정해지면 그 전에 다시 진료를 받으십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_158","text":"장록에게는 다음 날 만나는 자리에서 여행할 뜻을 전하기로 했다. 그는 이제 기다릴 화물이 없는 사람이었고, 나는 새로 챙길 짐이 생긴 사람이었다. 서로의 일이 끝나야만 헤어질 수 있다고 붙들 이유는 없어졌지만, 말 없이 사라질 이유도 없었다."},{"k":"line","id":"PRO_L04K2_depart_005","speaker":"나","text":"저는 이나즈마 쪽으로 갈 준비를 하려고요. 아직 배도 정해지지 않았고 들어갈 수 있는지도 알아봐야 합니다. 당분간은 치료소에서 찾으시면 되고, 출항할 수 있게 되면 다시 인사드릴게요. 이번에는 소리 소문 없이 없어지지 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_006","speaker":"장록","text":"갈 곳을 정했구나. 여기서 알아낸 게 다 끝났다는 얼굴은 아니네. 그래도 계속 붙잡고 있을 이유만 찾다 보면 평생 짐을 못 내릴 수도 있지. 내가 줄 만한 대단한 물건은 없어. 대신 배에 가져갈 짐은 한쪽으로 쏠리지 않게 싸. 그 어깨로 아직 욕심내지 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_007","options":[{"label":"대단한 물건보다 그 말이 저한테는 더 필요한 것 같네요. 장록 씨도 다음 일 시작하기 전에 쉬세요. 허리 아픈 사람 둘이 서로 걱정하는 모양새가 됐네.","id":"PRO_L04K2_depart_008","items":[{"k":"line","id":"PRO_L04K2_depart_009","speaker":"장록","text":"허리는 내가 선배지. 당신은 다리부터 챙겨. 다음에 리월 오면 물자 구역에 와서 이름 불러. 포대 뒤에서라도 대답할 테니까.","map":"MAP_LIYUE_HARBOR"}]},{"label":"이름을 알고 헤어지니까 이상하게 덜 무섭네요. 길에서 또 아무 말 없이 사라지는 사람이 될까 봐 그게 제일 싫었거든요.","id":"PRO_L04K2_depart_010","items":[{"k":"line","id":"PRO_L04K2_depart_011","speaker":"장록","text":"이름 적은 종이 잃어버리지 마. 그거 하나면 어디서든 찾아올 수 있잖아. 다음에 리월 오면 물자 구역에 와서 이름 불러. 포대 뒤에서라도 대답할 테니까.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_depart_012","speaker":"","text":"장록은 웃으며 어깨를 한 번 두드리려다 다친 곳을 보고 손을 거두었다. 대신 멀쩡한 쪽 팔을 가볍게 잡았다. 서로가 살아 돌아온 이유는 알지 못했다. 그러나 누가 먼저 찾았는지, 다음에는 어디서 부르면 되는지는 알고 있었다. 그 정도를 가진 채 헤어지는 것도 가능한 일이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_013","speaker":"","text":"각청은 남십자 함대가 이나즈마 방면 항해를 상의할 수 있는 창구를 알려 주었다. 먼저 몬드에도 현재 소식을 남겨 두기로 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_014","options":[{"label":"진에게 편지를 보낼게. 리월의 위기는 막았고 나는 살아서 치료 중이라고. 황금옥에서 겪은 일과 기억 공백은 내가 본 범위만 적을게. 범인까지 알아낸 것처럼 보내지는 않을 테니까.","id":"PRO_L04K2_depart_015","items":[{"k":"line","id":"PRO_L04K2_depart_016","speaker":"각청","text":"길드 전달편에 접수하면 돼. 여기서 네가 찾는 사람의 행방을 몰라 답답했으니, 너를 기다리는 사람에게는 먼저 알려 주는 게 좋겠지. 보내는 일은 지금 할 수 있어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"편지 첫 줄은 살아 있고 치료받고 있다는 말로 할게. 그다음에 실제로 본 일만 적고. 다음 행선지를 알아보는 중이라는 말을 벌써 출항했다는 소식처럼 보내지는 않을 거야.","id":"PRO_L04K2_depart_017","items":[{"k":"line","id":"PRO_L04K2_depart_018","speaker":"각청","text":"그렇게 구분해서 적으면 받는 쪽도 네가 어디에 있는지 알 수 있겠지. 회신 받을 숙소도 빠뜨리지 마. 길드 전달편에 접수하면 돼.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_166","text":"길드에서 편지를 작성해 맡겼다. 전하려던 소식과 당분간 연락받을 치료소를 적었고, 전달 담당자가 몬드행으로 접수했다. 이번에는 어디로 갔는지도 모를 사람으로 남지 않도록 내 쪽에서 할 일을 마쳤다."},{"k":"line","id":"PRO_L04K2_depart_019","speaker":"나","text":"네가 나를 처음 못 알아봤을 때는 되게 억울했어. 내가 겪은 일을 나만 떠안게 된 것 같아서. 그런데 너는 그 뒤에 찾는 사람도 찾아줬고 내 말 듣고 움직였잖아. 잊은 일을 원망하느라 새로 해 준 일까지 못 볼 뻔했네. 고마워, 각청.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_020","speaker":"각청","text":"그렇게 말해 주면 나도 듣기 편하지. 기억나지 않는 닷새를 떠올리라고 하는 건 할 수 없었지만, 지금 해야 할 일은 할 수 있었어. 다음에 와서는 포대 끈 이야기부터 할 필요 없어. 네 이름으로 불러. 나도 오늘 이후의 널 기억하고 있을 테니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_169","text":"내 이름을 다시 소개하지 않았다. 각청이 이미 알고 있는 이름으로 고개를 끄덕였다. 잊힌 인연을 처음부터 되돌릴 수는 없었어도 다음에 만날 사람으로 남을 수는 있었다. 그녀는 도시의 일로 돌아갔고, 나는 항구의 연락 창구로 향했다."},{"k":"line","id":"PRO_L04K2_depart_021","speaker":"나","text":"이나즈마 방면 배편을 상담하고 싶습니다. 각청에게 이쪽으로 문의하라는 소개를 받았어요. 저는 지금 상처를 치료하는 중입니다. 출항 일정과 승선 조건을 먼저 듣고, 입국 문제도 어떻게 준비해야 하는지 알고 싶어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_022","speaker":"남십자 선원","text":"뜻은 선장님께 전달하겠습니다. 다만 배에 자리가 있는 것과 이나즈마에 들어갈 수 있는 것은 별개입니다. 만나 뵐 일정이 정해지면 어디로 연락드리면 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_023","speaker":"나","text":"항구 치료소에 있습니다. 연락 오기 전에 무작정 배에 올라가 자리를 맡지는 않겠습니다. 남의 짐처럼 실려 가고 싶은 것도 아니고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_024","speaker":"","text":"접수가 끝난 것을 확인하고 치료소로 돌아왔다. 길에서 군옥각이 있던 하늘을 보았다. 그 빈자리는 도시를 구한 값이 무엇인지 기억하게 했지만, 남아 있는 길과 사람까지 가리지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_025","speaker":"정산 담당자","text":"돌아오셨군요. 리월 방어에 참여하고 위험을 전달한 공적에 대한 정산입니다. 1,800모라, 영웅의 경험 두 개와 모험가의 경험 세 개를 지급합니다. 금액과 물품을 확인하고 받아 주십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_026","options":[{"label":"확인했습니다. 1,800모라, 영웅의 경험 두 개, 모험가의 경험 세 개. 받겠습니다. 이번에는 제가 받았다는 것까지 확실히 남겨 두세요. 남의 화물 끝나는 걸 보고 왔더니 이제 제 몫 확인할 차례네요.","keep":"ISK_L04_K2_176","items":[{"k":"line","id":"PRO_L04K2_depart_027","speaker":"정산 담당자","text":"수령 기록에 남겼습니다. 인계가 끝나는 걸 지켜본 분이니 절차는 익숙하시겠군요.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_177","text":"받은 물품을 치료소의 짐 옆에 정리했다. 장록은 자기 일을 마쳤고, 각청은 도시를 되돌리고 있었으며, 응광과 선인들은 다음 경계를 맡았다. 나도 이곳에 남길 연락처와 떠날 이유를 정했다. 죽음과 기억의 의문은 풀리지 않았다. 그러나 리월에서 해야 했던 일은 사람들을 살아 있는 다음 하루로 돌려놓는 곳까지 왔다. 다음 행선지는 이나즈마였다."},{"k":"keep","id":"ISK_L04_K2_END"}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L04_K2_001_0","text":"손앞의 작은 파편에 손가락을 걸었다. 들보는 건드리지 않았다."},{"k":"text","id":"V141_AFTER_ISK_L04_K2_001_0","text":"파편이 옆으로 굴렀다. 좁은 틈으로 빛이 들고, 흙 묻은 손 하나가 나타났다."},{"k":"text","id":"V141_BEFORE_ISK_L04_K2_091_0","text":"향릉과 행추가 소식을 듣고 물자 구역까지 찾아왔다. 지금 나눌 이야기는 남은 짐의 수량보다, 함께 겪고 돌아온 일이었다."},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_0","text":"자, 이건 기다리지 말고 지금 먹기! 아저씨 것도 있어요!"},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_1","text":"자네가 끝까지 봤다는 그 짐, 내용물이 책이면 한 권 빌려도 되겠나?"},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_2","text":"그건 주인한테 말해. 난 이름 제대로 물어본 것만으로 오늘 할 일 다 했어."}]}]};})(globalThis);
